title: $:/core/modules/commands/inspect/lsp/lsp-inlay.js
type: application/javascript
module-type: library

Inlay hints: each positional argument labelled with the parameter it binds to,
so <<list-links "[tag[x]]">> reads as <<list-links filter: "[tag[x]]">>, the
label grey and not part of the text.

\*/

"use strict";

var source = require("$:/core/modules/commands/inspect/lsp/lsp-source.js"),
	files = require("$:/core/modules/commands/inspect/lsp/lsp-files.js"),
	macros = require("$:/core/modules/commands/inspect/lsp/lsp-macros.js"),
	calls = require("$:/core/modules/commands/inspect/calls.js");

// LSP InlayHintKind.
var KIND_PARAMETER = 2;

// Prefixes a positional value's index, which no written value starts with.
var MARK = "�";

// The closing bracket of each filter operand opener.
var OPERAND_CLOSE = { "[": "]", "{": "}", "<": ">", "(": ")" };

/**
 * Hints within range (every line when range is absent), in document positions.
 * @param {string} uri Document URI.
 * @param {string} text Document text.
 * @param {{start: {line: number, character: number}, end: {line: number, character: number}}} [range] Lines to hint.
 * @returns {Array<object>} LSP InlayHint objects.
 */
function inlayHints(uri, text, range) {
	var body = source.bodyOf(uri, text),
		hints = [];
	if(!files.isWikitext(uri, body)) {
		return hints;
	}
	// An operand's label reads "name=", since "name:" before a bracket looks like a filter suffix.
	function hint(offset, name, operand) {
		var position = source.positionAt(body.starts, body.offset + offset);
		if(!range || (position.line >= range.start.line && position.line <= range.end.line)) {
			hints.push(operand ?
				{ position: position, label: name + "=", kind: KIND_PARAMETER, paddingLeft: true } :
				{ position: position, label: name + ":", kind: KIND_PARAMETER, paddingRight: true });
		}
	}
	// Only where the name resolves, and by the definition's own binding rule;
	// each positional value is marked so its bound parameter can be told apart.
	function hintBound(name, offset, args) {
		var found = macros.findDefinition(name, body.text, offset);
		if(!found) {
			return;
		}
		var marked = args.map(function(arg, index) {
			return arg.positional ? Object.assign({}, arg, { value: MARK + index }) : arg;
		});
		macros.bindArguments(found.params, marked, found.kind === "javascript" ? "macro" : found.kind).forEach(function(bound) {
			if(bound.origin === "positional") {
				var arg = args[Number(bound.value.slice(MARK.length))];
				hint(valueStart(body.text, arg.start), bound.name);
			}
		});
	}
	// [x.y[a],[b]]: a dotted function's operands bind to its parameters by index.
	function hintOperands(site) {
		var found = macros.findDefinition(site.name, body.text, site.start),
			p = site.end + (/^:[^\[\{<\/(]*/.exec(body.text.slice(site.end)) || [""])[0].length;
		for(var i = 0; found && i < found.params.length && OPERAND_CLOSE[body.text.charAt(p)]; i++) {
			hint(p, found.params[i].name, true);
			p = body.text.indexOf(OPERAND_CLOSE[body.text.charAt(p)], p + 1) + 1;
			if(body.text.charAt(p) !== ",") {
				break;
			}
			p++;
		}
	}
	macros.callSites(source.parseWithBodies(body.text)).forEach(function(site) {
		if(site.args.some(function(arg) { return arg.positional; })) {
			hintBound(site.name, site.start, site.args);
		}
	});
	calls.sitesIn(body.text).calls.forEach(function(site) {
		if(site.form !== "filter") {
			return;
		}
		if(body.text.charAt(site.start - 1) === "<") {
			// [<fn "a" b>] passes arguments as a <<call>> does.
			var operand = body.text.slice(site.start, body.text.indexOf(">", site.end));
			hintBound(site.name, site.start, ($tw.utils.parseFilterVariable(operand).params || []).map(function(param) {
				return { name: param.name || null, value: param.value, positional: !param.name, start: site.start + param.start };
			}));
		} else if(site.name.includes(".")) {
			hintOperands(site);
		}
	});
	return hints;
}

/**
 * Skips the whitespace an argument's start includes, since the hint goes after it.
 * @param {string} text Body text.
 * @param {number} start Argument offset.
 * @returns {number} Offset of the value itself.
 */
function valueStart(text, start) {
	return start + /^\s*/.exec(text.slice(start))[0].length;
}

exports.inlayHints = inlayHints;
