title: $:/core/modules/commands/inspect/lsp/lsp-pragmas.js
type: application/javascript
module-type: library

Hovering a pragma line: its keyword, the name a definition declares, and each
parameter in its list. A pragma renders nothing where it is written, so no
other hover answers there.

\*/

"use strict";

var source = require("$:/core/modules/commands/inspect/lsp/lsp-source.js"),
	files = require("$:/core/modules/commands/inspect/lsp/lsp-files.js"),
	scope = require("$:/core/modules/commands/inspect/lsp/lsp-scope.js"),
	calls = require("$:/core/modules/commands/inspect/calls.js");

// One line per keyword, since no tiddler in the wiki describes them.
var KEYWORDS = {
	procedure: "Defines a procedure: wikitext whose parameters are variables inside it.",
	"function": "Defines a function: a filter, called as `[<name>]` or `[function[name]]`, or as a filter operator when its name holds a dot.",
	define: "Defines a macro, the older form of `\\procedure`: its `$param$` placeholders are replaced as text.",
	widget: "Defines a custom widget: `<$name>` renders its body, and `<$slot>` places the widget's own content.",
	end: "Ends the multi-line definition above it; a name written after it must be that definition's.",
	"import": "Imports the definitions of every tiddler the filter lists.",
	parameters: "Declares the parameters this tiddler takes when it is transcluded.",
	whitespace: "`trim` drops the whitespace between widgets, `notrim` keeps it.",
	rules: "`only` or `except`: which wikitext rules apply in this tiddler."
};

// The keywords that declare a named definition.
var DEFINING = ["procedure", "function", "define", "widget"];

function hover(uri, text, position, openDocuments) {
	var body = source.bodyOf(uri, text);
	if(position.line < body.firstLine) {
		return null;
	}
	var pragma = /^(\s*)\\(\w+)/.exec(body.lines[position.line] || "");
	if(!pragma) {
		return null;
	}
	var lineStart = body.starts[position.line] - body.offset,
		cursor = lineStart + position.character,
		keywordStart = lineStart + pragma[1].length,
		keywordEnd = keywordStart + 1 + pragma[2].length,
		definitions = calls.sitesIn(body.text).definitions;
	if(cursor >= keywordStart && cursor <= keywordEnd) {
		return keywordHover(body, pragma[2], keywordStart, keywordEnd, definitions);
	}
	for(var i = 0; i < definitions.length; i++) {
		var definition = definitions[i];
		if(definition.range.start !== keywordStart) {
			continue;
		}
		if(cursor >= definition.start && cursor <= definition.end) {
			return answer(body, definition.start, definition.end, nameHover(uri, text, definition, definitions, openDocuments));
		}
		var hit = parameterRanges(body, definition).find(function(range) { return cursor >= range.start && cursor <= range.end; });
		if(hit) {
			return answer(body, hit.start, hit.end, parameterHover(uri, text, body, definition, hit.param));
		}
	}
	return null;
}

function keywordHover(body, name, start, end, definitions) {
	if(!KEYWORDS[name]) {
		return null;
	}
	var isDefinition = definitions.some(function(definition) { return definition.range.start === start; }),
		value = "```\n\\" + name + "\n```\n\n" + KEYWORDS[name];
	if(DEFINING.includes(name) && !isDefinition) {
		value += "\n\n**Not a definition here:** a pragma counts only where nothing but pragmas precedes it, so TiddlyWiki shows this line as text.";
	}
	return answer(body, start, end, value);
}

function nameHover(uri, text, definition, definitions, openDocuments) {
	var title = source.titleOfDocument(uri, text),
		parent = definition.parent === null ? null : definitions[definition.parent],
		reach = parent ? "local to `" + parent.name + "`" : (calls.importedGlobally(title) ? "global" : "local to this tiddler"),
		hidden = parent ? null : calls.globalDefinition(definition.name),
		value = "**" + definition.kind + "** `" + definition.name + "`, defined here, " + reach + "\n\n";
	if(hidden && hidden.title !== title) {
		value += "`" + hidden.title + "` defines it globally too; inside this tiddler this one wins.\n\n";
	}
	if(definition.params.length) {
		value += "| Parameter | Default |\n| --- | --- |\n" + definition.params.map(function(param) {
			return "| " + cell(param.name) + " | " + (param["default"] === undefined ? "" : "`" + cell(param["default"]) + "`") + " |";
		}).join("\n") + "\n\n";
	} else {
		value += "Takes no parameters.\n\n";
	}
	// Counted by name: which definition a call reaches depends on its caller.
	var documents = Object.assign({}, openDocuments);
	documents[uri] = text;
	var hits = files.sitesNamed(definition.name, documents).filter(function(hit) {
			return !hit.site.definition;
		}),
		here = hits.filter(function(hit) { return files.sameFileKey(hit.uri) === files.sameFileKey(uri); }).length,
		views = hits.filter(function(hit) { return source.isVirtualUri(hit.uri); }).length;
	return value + plural(hits.length, "call") + " of this name: " + here + " here, " + (hits.length - here - views) +
		" in other files, " + views + " in tiddlers without a file.";
}

function parameterHover(uri, text, body, definition, param) {
	var uses;
	if(definition.kind === "macro") {
		uses = placeholderUses(body, definition, param);
	} else {
		uses = bodyUses(uri, text, body, definition, param);
	}
	return "**parameter** `" + param.name + "` of `" + definition.name + "`" +
		(param["default"] === undefined ? ", no default" : ", default `" + cell(param["default"]) + "`") +
		"\n\nNamed " + plural(uses, "time") + " in its body. Definitions it calls can read it too, so no count shows it unused.";
}

// Calls in the body that resolve to this very parameter: an inner binding or a
// nested definition's parameter of the same name is another variable.
function bodyUses(uri, text, body, definition, param) {
	if(!definition.body) {
		return 0;
	}
	var tree = source.parseWithBodies(body.text);
	return files.sitesOfDocument(uri, text).filter(function(site) {
		if(site.definition || site.name !== param.name) {
			return false;
		}
		var binding = scope.resolve(site.name, site.start, tree, body.text);
		return !!binding && binding.kind === "parameter" && binding.scope.start === definition.body.start;
	}).length;
}

// A \define parameter is used as a $name$ placeholder, which no parser sees.
function placeholderUses(body, definition, param) {
	if(!definition.body) {
		return 0;
	}
	return body.text.slice(definition.body.start, definition.body.end).split("$" + param.name + "$").length - 1;
}

// Where each parameter's name sits on the definition's first line. The list is
// read left to right, stepping over each default, so a default that happens to
// hold a parameter's name is never taken for it.
function parameterRanges(body, definition) {
	var lineEnd = body.text.indexOf("\n", definition.end),
		list = body.text.slice(definition.end, lineEnd < 0 ? body.text.length : lineEnd),
		pos = list.indexOf("("),
		ranges = [];
	if(pos < 0) {
		return ranges;
	}
	pos++;
	for(var i = 0; i < definition.params.length; i++) {
		var param = definition.params[i];
		while(pos < list.length && /[\s,]/.test(list.charAt(pos))) {
			pos++;
		}
		if(list.substr(pos, param.name.length) !== param.name) {
			break;
		}
		ranges.push({ param: param, start: definition.end + pos, end: definition.end + pos + param.name.length });
		pos += param.name.length;
		while(pos < list.length && /\s/.test(list.charAt(pos))) {
			pos++;
		}
		if(list.charAt(pos) === ":") {
			pos = skipValue(list, pos + 1);
		}
	}
	return ranges;
}

// Past a parameter's default, in any of the quotings a parameter list allows.
function skipValue(list, pos) {
	while(pos < list.length && /\s/.test(list.charAt(pos))) {
		pos++;
	}
	var closers = [["\"\"\"", "\"\"\""], ["\"", "\""], ["'", "'"], ["[[", "]]"]];
	for(var i = 0; i < closers.length; i++) {
		if(list.substr(pos, closers[i][0].length) === closers[i][0]) {
			var close = list.indexOf(closers[i][1], pos + closers[i][0].length);
			return close < 0 ? list.length : close + closers[i][1].length;
		}
	}
	while(pos < list.length && !/[\s,)]/.test(list.charAt(pos))) {
		pos++;
	}
	return pos;
}

function answer(body, start, end, value) {
	return value === null ? null : {
		contents: { kind: "markdown", value: value },
		range: { start: source.positionAt(body.starts, body.offset + start), end: source.positionAt(body.starts, body.offset + end) }
	};
}

// A "|" in a cell ends the column.
function cell(value) {
	return String(value).replace(/\|/g, "\\|");
}

function plural(count, word) {
	return count + " " + word + (count === 1 ? "" : "s");
}

exports.hover = hover;
","type":"application/javascript","module-type":"library"},"$:/core/modules/commands/inspect/lsp/lsp-primary.js":{"title":"$:/core/modules/commands/inspect/lsp/lsp-primary.js","text":"/*\
title: $:/core/modules/commands/inspect/lsp/lsp-primary.js
type: application/javascript
module-type: library

Links the LSP process an editor started to the MCP server of its wiki: the link
says who the LSP process is, notices the server come and go, and forwards files
saved in the editor, since each process holds its own copy of the wiki.

\*/

"use strict";

var net = $tw.node ? require("net") : null;

var mcpLib = require("$:/core/modules/commands/inspect/mcp/mcp-lib.js");

var POLL_MS = 2000;
var TIMEOUT_MS = 3000;
// A pipe that is gone or refuses belongs to a server that stopped; the next poll looks again.
var GONE_CODES = ["ENOENT", "ECONNREFUSED", "ECONNRESET", "EPIPE"];

/**
 * Links this LSP process to the wiki's MCP primary, found by its discovery file and polled until it appears.
 * @param {object} [options] - hello (sent on connect), log, onChange(server or null), pollMs, timeoutMs, readDiscovery (test seam)
 * @returns {object} Link
 */
function createLink(options) {
	options = options || {};
	var log = options.log || function() {},
		onChange = options.onChange || function() {},
		readDiscovery = options.readDiscovery || mcpLib.readDiscoveryFile,
		timeoutMs = options.timeoutMs || TIMEOUT_MS,
		hello = Object.assign({}, options.hello),
		socket = null,
		server = null,
		connected = false,
		buffer = "",
		nextId = 1,
		pending = Object.create(null);

	function write(message) {
		message.params._meta = {};
		message.params._meta[mcpLib.TW_AUTH] = server.token;
		message.params._meta[mcpLib.TW_PID] = process.pid;
		message.params._meta[mcpLib.TW_LABEL] = hello.label || "lsp";
		socket.write(JSON.stringify(message) + "\n");
	}

	function sendHello() {
		write({ jsonrpc: "2.0", method: mcpLib.LSP_HELLO_METHOD, params: Object.assign({}, hello) });
	}

	function poll() {
		if(socket) {
			return;
		}
		var found = readDiscovery();
		if(!found || found.pid === process.pid) {
			return;
		}
		server = found;
		socket = net.connect(found.pipe);
		// The editor's pipe decides when this process ends, not this link.
		socket.unref();
		socket.on("connect", function() {
			connected = true;
			log("MCP server found: PID " + found.pid + (found.label ? " @" + found.label : "") + (found.listen && found.port ? ", browser on port " + found.port : ", no browser"));
			sendHello();
			onChange(describe(found));
		});
		socket.on("data", receive);
		socket.on("error", function(err) {
			if(!GONE_CODES.includes(err.code)) {
				log("MCP server connection failed: " + err.message);
			}
		});
		socket.on("close", function() {
			var wasConnected = connected;
			if(wasConnected) {
				log("MCP server gone: PID " + found.pid + (found.label ? " @" + found.label : ""));
			}
			socket = null;
			server = null;
			connected = false;
			buffer = "";
			failPending(new Error("the MCP server went away"));
			if(wasConnected) {
				onChange(null);
			}
		});
	}

	function receive(chunk) {
		buffer += chunk.toString("utf8");
		var lines = buffer.split("\n");
		buffer = lines.pop();
		lines.forEach(function(line) {
			var reply = line.trim() ? JSON.parse(line) : null,
				entry = reply && pending[reply.id];
			// Broadcasts reach every pipe client; only answers to this link's requests count.
			if(!entry) {
				return;
			}
			delete pending[reply.id];
			clearTimeout(entry.timer);
			if(reply.error) {
				entry.callback(new Error(reply.error.message));
			} else {
				entry.callback(null, reply.result.titles);
			}
		});
	}

	function failPending(err) {
		Object.keys(pending).forEach(function(id) {
			var entry = pending[id];
			delete pending[id];
			clearTimeout(entry.timer);
			entry.callback(err);
		});
	}

	// callback(err, titles): titles is undefined when no MCP server is linked, and
	// null when the server does not own the file.
	function reloadFile(filepath, callback) {
		if(!connected) {
			callback(null, undefined);
			return;
		}
		var id = nextId++;
		pending[id] = {
			callback: callback,
			timer: setTimeout(function() {
				delete pending[id];
				callback(new Error("the MCP server did not answer within " + timeoutMs + " ms"));
			}, timeoutMs)
		};
		write({ jsonrpc: "2.0", id: id, method: mcpLib.RELOAD_FILE_METHOD, params: { path: filepath } });
	}

	// Details learned later, such as the editor's name, are told again.
	function update(fields) {
		Object.assign(hello, fields);
		if(connected) {
			sendHello();
		}
	}

	// What an editor shows about the server: no token or pipe.
	function describe(found) {
		var browsing = found.listen && found.port;
		return {
			pid: found.pid,
			label: found.label || null,
			browserPort: browsing ? found.port : null,
			// A primary from before tw-mcp 0.23.1 records no host; it served 127.0.0.1 unless told otherwise.
			browserUrl: browsing ? "http://" + (found.host || "127.0.0.1") + ":" + found.port : null
		};
	}

	var timer = setInterval(poll, options.pollMs || POLL_MS);
	timer.unref();
	poll();

	return {
		reloadFile: reloadFile,
		update: update,
		isConnected: function() { return connected; },
		server: function() { return connected ? describe(server) : null; },
		close: function() {
			clearInterval(timer);
			if(socket) {
				socket.destroy();
			}
		}
	};
}

exports.createLink = createLink;
","type":"application/javascript","module-type":"library"},"$:/core/modules/commands/inspect/lsp/lsp-references.js":{"title":"$:/core/modules/commands/inspect/lsp/lsp-references.js","text":"/*\
title: $:/core/modules/commands/inspect/lsp/lsp-references.js
type: application/javascript
module-type: library

Find references: every place the macro, procedure, function or widget under the
cursor is called, across every document the editor can open (lsp-files.js).

The call sites come from tw-mcp-core's calls.js, which knows nothing about LSP;
this file adds the editor's view of them, and keeps a parameter or a widget's
variable to its own scope.

\*/

"use strict";

var source = require("$:/core/modules/commands/inspect/lsp/lsp-source.js"),
	scope = require("$:/core/modules/commands/inspect/lsp/lsp-scope.js"),
	files = require("$:/core/modules/commands/inspect/lsp/lsp-files.js");

function references(uri, text, position, context, openDocuments) {
	var here = files.sitesOfDocument(uri, text),
		target = files.siteAt(here, position);
	if(!target) {
		return null;
	}
	var includeDeclaration = !!(context && context.includeDeclaration),
		body = source.bodyOf(uri, text),
		tree = source.parseWithBodies(body.text),
		binding = target.definition ? null : scope.resolve(target.name, target.start, tree, body.text);
	if(binding) {
		return scopedReferences(uri, here, binding, tree, body, includeDeclaration);
	}
	var documents = Object.assign({}, openDocuments);
	documents[uri] = text;
	return files.sitesNamed(target.name, documents).filter(function(hit) {
		return includeDeclaration || !hit.site.definition;
	}).map(function(hit) {
		return { uri: hit.uri, range: hit.site.range };
	}).sort(byPosition);
}

// A parameter or a widget's variable is that name only inside its own scope in
// this document, and an inner binding of the same name hides it.
function scopedReferences(uri, sites, binding, tree, body, includeDeclaration) {
	var locations = scopedUses(sites, binding, tree, body).map(function(range) {
			return { uri: uri, range: range };
		}),
		declared = declarationRange(binding, body);
	if(includeDeclaration && declared) {
		locations.push({ uri: uri, range: declared });
	}
	return locations.sort(byPosition);
}

// The ranges of every use of a binding in its own scope.
function scopedUses(sites, binding, tree, body) {
	return sites.filter(function(site) {
		if(site.definition || site.name !== binding.name) {
			return false;
		}
		var own = scope.resolve(site.name, site.start, tree, body.text);
		return own && own.scope.node === binding.scope.node;
	}).map(function(site) {
		return site.range;
	});
}

// Where a binding is declared, or null for a variable no attribute names.
function declarationRange(binding, body) {
	if(!binding.declaration) {
		return null;
	}
	return {
		start: source.positionAt(body.starts, body.offset + binding.declaration.start),
		end: source.positionAt(body.starts, body.offset + binding.declaration.end)
	};
}

function byPosition(a, b) {
	if(a.uri !== b.uri) {
		return a.uri < b.uri ? -1 : 1;
	}
	return (a.range.start.line - b.range.start.line) || (a.range.start.character - b.range.start.character);
}

exports.references = references;
exports.scopedUses = scopedUses;
exports.declarationRange = declarationRange;
exports.sameFileKey = files.sameFileKey;
","type":"application/javascript","module-type":"library"},"$:/core/modules/commands/inspect/lsp/lsp-reload.js":{"title":"$:/core/modules/commands/inspect/lsp/lsp-reload.js","text":"/*\
title: $:/core/modules/commands/inspect/lsp/lsp-reload.js
type: application/javascript
module-type: library

A .tid saved in the editor, read into the running wiki. The wiki does not watch
its folder, so without this every hover, global and reference would keep
answering from the text as it was when the wiki started.

\*/

"use strict";

var path = $tw.node ? require("path") : null;

var source = require("$:/core/modules/commands/inspect/lsp/lsp-source.js"),
	files = require("$:/core/modules/commands/inspect/lsp/lsp-files.js"),
	shared = require("$:/core/modules/commands/inspect/handlers/shared.js");

// Loads the .tid at uri into the wiki and returns the titles it holds, or null
// when the file is not the wiki's.
function reloadSaved(uri) {
	return source.isTidUri(uri) ? reloadFile(path.resolve(source.uriToPath(uri))) : null;
}

// Loads a tiddler file into the wiki and returns the titles it holds, or null when
// the file is not the wiki's: one it files a tiddler in, or one in its tiddlers
// folder. A plugin's source file must never become a real tiddler.
function reloadFile(filepath) {
	var key = files.sameFileKey(source.pathToUri(filepath)),
		filed = titlesFiledAt(key);
	if(!filed.length && !inTiddlersFolder(key)) {
		return null;
	}
	filepath = filed.length ? $tw.boot.files[filed[0]].filepath : filepath;
	var loaded = $tw.loadTiddlersFromFile(filepath),
		titles = [];
	loaded.tiddlers.forEach(function(fields) {
		if(!fields.title) {
			return;
		}
		titles.push(fields.title);
		$tw.boot.files[fields.title] = Object.assign({}, $tw.boot.files[fields.title], { filepath: filepath, type: loaded.type, hasMetaFile: loaded.hasMetaFile });
		if(!sameFields($tw.wiki.getTiddler(fields.title), fields)) {
			shared.addToWikiSilently(fields);
		}
	});
	// A title the file no longer holds is unfiled first, so the syncer's delete
	// finds no file to remove: the file now belongs to the new title.
	filed.forEach(function(title) {
		if(!titles.includes(title)) {
			delete $tw.boot.files[title];
			$tw.wiki.deleteTiddler(title);
		}
	});
	return titles;
}

// A file deleted on disk takes its tiddlers with it; they are unfiled first, so
// a syncer's delete finds no file left to remove.
function forgetFile(filepath) {
	var filed = titlesFiledAt(files.sameFileKey(source.pathToUri(filepath)));
	filed.forEach(function(title) {
		delete $tw.boot.files[title];
		$tw.wiki.deleteTiddler(title);
	});
	return filed;
}

function titlesFiledAt(key) {
	return Object.keys($tw.boot.files || {}).filter(function(title) {
		var filepath = $tw.boot.files[title].filepath;
		return !!filepath && files.sameFileKey(source.pathToUri(filepath)) === key;
	});
}

function inTiddlersFolder(key) {
	return !!$tw.boot.wikiTiddlersPath && key.startsWith(files.sameFileKey(source.pathToUri(path.resolve($tw.boot.wikiTiddlersPath))) + "/");
}

// An unchanged save adds nothing, so it fires no change and clears no cache.
function sameFields(tiddler, fields) {
	if(!tiddler) {
		return false;
	}
	var before = tiddler.getFieldStrings(),
		after = new $tw.Tiddler(fields).getFieldStrings();
	return Object.keys(before).length === Object.keys(after).length && Object.keys(after).every(function(name) {
		return before[name] === after[name];
	});
}

exports.reloadSaved = reloadSaved;
exports.reloadFile = reloadFile;
exports.forgetFile = forgetFile;
","type":"application/javascript","module-type":"library"},"$:/core/modules/commands/inspect/lsp/lsp-rename.js":{"title":"$:/core/modules/commands/inspect/lsp/lsp-rename.js","text":"/*\
title: $:/core/modules/commands/inspect/lsp/lsp-rename.js
type: application/javascript
module-type: library

Rename: a definition with every call that reaches it, in every file, or a
parameter with its uses, its $param$ substitutions and the named arguments that
fill it. What cannot be renamed safely is refused with the reason.

A parameter can be read by a definition its body calls, which no parse shows,
so parameter edits always open the editor's preview first.

\*/

"use strict";

var fs = $tw.node ? require("fs") : null;

var source = require("$:/core/modules/commands/inspect/lsp/lsp-source.js"),
	files = require("$:/core/modules/commands/inspect/lsp/lsp-files.js"),
	scope = require("$:/core/modules/commands/inspect/lsp/lsp-scope.js"),
	macros = require("$:/core/modules/commands/inspect/lsp/lsp-macros.js"),
	references = require("$:/core/modules/commands/inspect/lsp/lsp-references.js"),
	filters = require("$:/core/modules/commands/inspect/lsp/lsp-filters.js"),
	names = require("$:/core/modules/commands/inspect/lsp/lsp-names.js"),
	widgets = require("$:/core/modules/commands/inspect/lsp/lsp-widgets.js"),
	calls = require("$:/core/modules/commands/inspect/calls.js");

// A name a call can write: nothing that ends a name or starts an argument.
var VALID_NAME = /^[^\s<>"'`=:\/|\[\]{}]+$/;

var CONFIRM = "tw-rename-confirm";

// What F2 would rename, as { range, placeholder }, or { error }.
function prepareRename(uri, text, position, openDocuments) {
	var plan = planAt(uri, text, position, openDocuments);
	return plan.error ? plan : { range: plan.origin, placeholder: plan.name };
}

// The WorkspaceEdit renaming what is at position to newName, or { error }.
function rename(uri, text, position, newName, options, openDocuments) {
	var plan = planAt(uri, text, position, openDocuments),
		refused = plan.error || refusal(plan, newName);
	return refused ? { error: refused } : workspaceEdit(plan, newName, uri, options);
}

function planAt(uri, text, position, openDocuments) {
	var documents = Object.assign({}, openDocuments);
	documents[uri] = text;
	var load = loader(documents),
		doc = load(uri),
		closingTag = files.siteAt(doc.sites, position) ? null : closingTagAt(doc, position),
		site = closingTag ? closingTag.site : files.siteAt(doc.sites, position),
		declared = site ? null : parameterDeclaredAt(doc, source.offsetAt(doc.body.starts, position) - doc.body.offset);
	if(declared) {
		return parameterPlan(load, documents, doc, declared.definition, declared.name);
	}
	if(!site) {
		return { error: "Nothing to rename here: put the cursor on a call, a definition's name or a parameter." };
	}
	if(filters.CORE_VARIABLES.includes(site.name)) {
		return { error: "`" + site.name + "` is set by TiddlyWiki itself." };
	}
	var binding = site.definition || site.start < 0 ? null : scope.resolve(site.name, site.start, doc.tree, doc.body.text);
	if(binding && binding.kind === "variable") {
		return { error: "`" + site.name + "` is set by " + binding.by + ": renaming a widget's variable is not supported, since definitions it calls can read it too." };
	}
	if(binding) {
		return parameterPlan(load, documents, doc, doc.definitions.filter(function(d) { return d.body && d.body.start === binding.scope.start; })[0], site.name);
	}
	var plan = definitionPlan(load, documents, doc, site);
	if(closingTag && !plan.error) {
		plan.origin = closingTag.range;
	}
	return plan;
}

// Each document read once: open buffer, else the file, else a tiddler's view.
function loader(documents) {
	var cache = Object.create(null);
	return function(docUri) {
		var key = files.sameFileKey(docUri);
		if(!cache[key]) {
			var text = textOf(docUri, documents),
				body = source.bodyOf(docUri, text);
			cache[key] = {
				uri: docUri,
				text: text,
				body: body,
				tree: source.parseWithBodies(body.text),
				sites: files.sitesOfDocument(docUri, text),
				definitions: calls.sitesIn(body.text).definitions,
				title: source.titleOfDocument(docUri, text)
			};
		}
		return cache[key];
	};
}

// A closing tag name holding position, which is no call site of its own, as { site, range } with the
// site of its opening tag.
function closingTagAt(doc, position) {
	for(var i = 0; i < doc.sites.length; i++) {
		var site = doc.sites[i],
			range = site.name.charAt(0) === "$" ? names.closingTagRange(site, doc.body, doc.tree) : null;
		if(range && !before(position, range.start) && !before(range.end, position)) {
			return { site: site, range: range };
		}
	}
	return null;
}

function before(p, q) {
	return p.line < q.line || (p.line === q.line && p.character < q.character);
}

function textOf(docUri, documents) {
	var open = Object.keys(documents).filter(function(key) { return files.sameFileKey(key) === files.sameFileKey(docUri); })[0];
	if(open !== undefined) {
		return documents[open];
	}
	return source.isVirtualUri(docUri) ? source.virtualText(source.titleOfVirtualUri(docUri)) : fs.readFileSync(source.uriToPath(docUri), "utf8");
}

function rangeIn(doc, start, end) {
	return { start: source.positionAt(doc.body.starts, doc.body.offset + start), end: source.positionAt(doc.body.starts, doc.body.offset + end) };
}

// --- Definitions ---

function definitionPlan(load, documents, doc, site) {
	var target = site.definition ? { doc: doc, definition: doc.definitions.filter(function(d) { return d.start === site.start; })[0] } : definitionOfCall(load, doc, site);
	if(target.error) {
		return target;
	}
	var defDoc = target.doc,
		def = target.definition,
		global = def.parent === null && calls.importedGlobally(defDoc.title),
		found = callsTo(load, documents, defDoc, def, global);
	if(found.error) {
		return found;
	}
	var edits = [{ uri: defDoc.uri, range: rangeIn(defDoc, def.start, def.end) }];
	found.calls.forEach(function(call) {
		edits.push({ uri: call.doc.uri, range: call.site.range });
		// A widget's tag closes with its name again.
		var closing = def.kind === "widget" ? names.closingTagRange(call.site, call.doc.body, call.doc.tree) : null;
		if(closing) {
			edits.push({ uri: call.doc.uri, range: closing });
		}
	});
	return {
		kind: "definition",
		name: def.name,
		origin: site.range,
		edits: edits,
		conflict: function(newName) {
			if(def.kind === "widget" && newName.charAt(0) !== "$") {
				return "A \\widget's name starts with $.";
			}
			// Without a dot, core widget.js only lets a \widget replace the core widget of that name.
			if(def.kind === "widget" && !newName.includes(".")) {
				return "`" + newName + "` needs a dot to name a \\widget of its own.";
			}
			if(def.kind !== "widget" && newName.charAt(0) === "$") {
				return "A name starting with $ is a widget's.";
			}
			if(def.kind === "function" && def.name.includes(".") && !newName.includes(".")) {
				return "`" + def.name + "` can be called as a filter operator, which needs a dot in the name.";
			}
			if(defDoc.definitions.some(function(d) { return d.name === newName && d.parent === def.parent; })) {
				return "`" + newName + "` is already defined beside `" + def.name + "` in `" + defDoc.title + "`.";
			}
			var existing = global ? calls.globalDefinition(newName) : null;
			if(existing) {
				return "`" + newName + "` is already a global, defined in `" + existing.title + "`.";
			}
			return visibleAt(found.calls, newName);
		}
	};
}

// The definition a call reaches, in the document that holds it, or { error }.
function definitionOfCall(load, doc, site) {
	var found = macros.findDefinition(site.name, doc.body.text, site.start);
	if(!found) {
		return { error: "`" + site.name + "` is not defined anywhere TiddlyWiki would look from here." };
	}
	if(found.kind === "javascript") {
		return { error: "`" + site.name + "` is a JavaScript macro, defined in code." };
	}
	if(found.title === null) {
		return { doc: doc, definition: found.site };
	}
	if(found.imported) {
		return { error: "`" + site.name + "` is brought in by an \\import from `" + found.title + "`, and rename cannot find every tiddler that imports it." };
	}
	var where = source.documentUriOf(found.title);
	if(!where || source.isVirtualUri(where)) {
		return { error: "`" + site.name + "` is defined in `" + found.title + "`, a tiddler without a file of its own, which cannot be edited." };
	}
	var defDoc = load(where),
		definition = defDoc.definitions.filter(function(d) { return d.parent === null && d.name === site.name; }).pop();
	return definition ? { doc: defDoc, definition: definition } : { error: "`" + site.name + "` is no longer defined in the file of `" + found.title + "`." };
}

// Every call that reaches def: in its own document by the resolver, and for a
// global in every other document whose call TiddlyWiki would send to its title.
function callsTo(load, documents, defDoc, def, global) {
	var found = [],
		error = null;
	defDoc.sites.forEach(function(site) {
		if(!site.definition && site.name === def.name && (site.start < 0 ? global : reaches(defDoc, site, def))) {
			found.push({ doc: defDoc, site: site });
		}
	});
	if(global) {
		files.sitesNamed(def.name, documents).forEach(function(hit) {
			if(hit.site.definition || files.sameFileKey(hit.uri) === files.sameFileKey(defDoc.uri)) {
				return;
			}
			var doc = load(hit.uri);
			if(!callsGlobal(doc, hit.site, defDoc.title)) {
				return;
			}
			if(source.isVirtualUri(hit.uri)) {
				error = error || "`" + def.name + "` is called in `" + doc.title + "`, a tiddler without a file of its own, which cannot be edited.";
			}
			found.push({ doc: doc, site: hit.site });
		});
	}
	return error ? { error: error } : { calls: found };
}

function reaches(doc, site, def) {
	if(scope.resolve(site.name, site.start, doc.tree, doc.body.text)) {
		return false;
	}
	var local = macros.localDefinition(site.name, doc.definitions, site.start);
	return !!local && local.start === def.start;
}

function callsGlobal(doc, site, title) {
	if(site.start >= 0 && scope.resolve(site.name, site.start, doc.tree, doc.body.text)) {
		return false;
	}
	var found = macros.findDefinition(site.name, doc.body.text, site.start);
	return !!found && found.title === title;
}

// A call that newName would already reach: renaming would hand it the wrong definition.
function visibleAt(found, newName) {
	for(var i = 0; i < found.length; i++) {
		var doc = found[i].doc,
			site = found[i].site;
		if(macros.findDefinition(newName, doc.body.text, site.start) || (site.start >= 0 && scope.resolve(newName, site.start, doc.tree, doc.body.text))) {
			return "`" + newName + "` already means something where it would be called, in `" + doc.title + "` line " + (site.range.start.line + 1) + ".";
		}
	}
	return null;
}

// --- Parameters ---

// A parameter under the cursor in a definition's head, as { definition, name }.
function parameterDeclaredAt(doc, cursor) {
	for(var i = 0; i < doc.definitions.length; i++) {
		var definition = doc.definitions[i];
		for(var p = 0; p < definition.params.length; p++) {
			var at = declarationOf(doc, definition, definition.params[p].name);
			if(at && cursor >= at.start && cursor <= at.end) {
				return { definition: definition, name: definition.params[p].name };
			}
		}
	}
	return null;
}

// Where a parameter is declared, between the parentheses on the head line.
function declarationOf(doc, definition, name) {
	var head = doc.body.text.slice(definition.range.start, definition.range.end).split("\n")[0],
		match = new RegExp("[(,\\s]" + $tw.utils.escapeRegExp(name) + "(?=\\s*[:,)])").exec(head);
	return match ? { start: definition.range.start + match.index + 1, end: definition.range.start + match.index + 1 + name.length } : null;
}

function parameterPlan(load, documents, doc, definition, name) {
	if(!definition) {
		return { error: "Nothing to rename here: `" + name + "` is not a parameter of a definition in this tiddler." };
	}
	var declared = declarationOf(doc, definition, name),
		binding = definition.body ? scope.resolve(name, definition.body.start, doc.tree, doc.body.text) : null,
		edits = [{ uri: doc.uri, range: rangeIn(doc, declared.start, declared.end) }];
	(binding ? references.scopedUses(doc.sites, binding, doc.tree, doc.body) : []).forEach(function(range) {
		edits.push({ uri: doc.uri, range: range });
	});
	// A \define substitutes $name$ and $(name)$ into its body as text.
	if(definition.kind === "macro" && definition.body) {
		var text = doc.body.text.slice(definition.body.start, definition.body.end),
			pattern = new RegExp("\\$(\\(?)" + $tw.utils.escapeRegExp(name) + "\\)?\\$", "g"),
			match;
		while((match = pattern.exec(text)) !== null) {
			var start = definition.body.start + match.index + 1 + match[1].length;
			edits.push({ uri: doc.uri, range: rangeIn(doc, start, start + name.length) });
		}
	}
	var global = definition.parent === null && calls.importedGlobally(doc.title),
		found = callsTo(load, documents, doc, definition, global);
	if(found.error) {
		return found;
	}
	found.calls.forEach(function(call) {
		var at = definition.kind === "widget" ? widgetAttribute(call.doc, call.site, name) : namedArgument(call.doc, call.site, name);
		if(at !== null) {
			edits.push({ uri: call.doc.uri, range: rangeIn(call.doc, at, at + name.length) });
		}
	});
	return {
		kind: "parameter",
		name: name,
		origin: rangeIn(doc, declared.start, declared.end),
		edits: edits.map(function(edit) { return Object.assign(edit, { confirm: true }); }),
		conflict: function(newName) {
			if(definition.params.some(function(param) { return param.name === newName; })) {
				return "`" + newName + "` is already a parameter of `" + definition.name + "`.";
			}
			if(definition.body && doc.sites.some(function(site) { return site.name === newName && site.start >= definition.body.start && site.start < definition.body.end; })) {
				return "`" + newName + "` is already used inside `" + definition.name + "`, and would then mean the parameter.";
			}
			return null;
		}
	};
}

// Where a call names this parameter as an argument (tag: or tag=), or null.
function namedArgument(doc, site, name) {
	var call = macros.callSites(doc.tree).filter(function(c) { return c.start <= site.start && site.start < c.end; })[0],
		arg = call ? call.args.filter(function(a) { return a.name === name; })[0] : null;
	return arg && arg.start !== undefined ? arg.start + /^\s*/.exec(doc.body.text.slice(arg.start))[0].length : null;
}

// Where a call of a \widget gives this parameter as an attribute, or null: on the widget's own tag, or
// on the <$transclude> whose $variable names it, whichever is the innermost widget holding the call.
function widgetAttribute(doc, site, name) {
	var holder = widgets.widgetSites(doc.tree, doc.body.text).filter(function(widget) {
			return widget.start <= site.start && site.start < widget.end;
		}).sort(function(a, b) { return b.start - a.start; })[0],
		attribute = holder ? holder.attributes.filter(function(a) { return a.name === name; })[0] : null;
	return attribute && attribute.start !== undefined ? attribute.start + /^\s*/.exec(doc.body.text.slice(attribute.start))[0].length : null;
}

// --- The answer ---

function refusal(plan, newName) {
	if(!VALID_NAME.test(newName)) {
		return "`" + newName + "` is not a name a call can write.";
	}
	if(filters.CORE_VARIABLES.includes(newName)) {
		return "`" + newName + "` is set by TiddlyWiki itself.";
	}
	return plan.conflict(newName);
}

// Edits outside the asking document, and every parameter edit, open the
// editor's preview first when the client supports change annotations.
function workspaceEdit(plan, newName, uri, options) {
	var byKey = Object.create(null),
		order = [],
		annotate = !!(options && options.annotations);
	plan.edits.forEach(function(edit) {
		var key = files.sameFileKey(edit.uri);
		if(!byKey[key]) {
			byKey[key] = { uri: edit.uri, edits: [] };
			order.push(key);
		}
		var text = { range: edit.range, newText: newName };
		if(annotate && (edit.confirm || key !== files.sameFileKey(uri))) {
			text.annotationId = CONFIRM;
		}
		byKey[key].edits.push(text);
	});
	if(!annotate) {
		var changes = {};
		order.forEach(function(key) { changes[byKey[key].uri] = byKey[key].edits; });
		return { changes: changes };
	}
	var annotations = {};
	annotations[CONFIRM] = {
		label: "Rename `" + plan.name + "` to `" + newName + "`",
		description: plan.kind === "parameter" ? "Definitions its body calls can read a parameter too, which rename cannot see." : "In another tiddler",
		needsConfirmation: true
	};
	return {
		documentChanges: order.map(function(key) {
			return { textDocument: { uri: byKey[key].uri, version: null }, edits: byKey[key].edits };
		}),
		changeAnnotations: annotations
	};
}

exports.prepareRename = prepareRename;
exports.rename = rename;
","type":"application/javascript","module-type":"library"},"$:/core/modules/commands/inspect/lsp/lsp-scope.js":{"title":"$:/core/modules/commands/inspect/lsp/lsp-scope.js","text":"/*\
title: $:/core/modules/commands/inspect/lsp/lsp-scope.js
type: application/javascript
module-type: library

What binds a name at a position: a parameter of the definition whose body holds
it, or a variable set by a widget around it. TiddlyWiki looks a name up the same
way when it renders, innermost first, so either one hides any definition of the
same name.

\*/

"use strict";

var calls = require("$:/core/modules/commands/inspect/calls.js"),
	widgets = require("$:/core/modules/commands/inspect/lsp/lsp-widgets.js");

/**
 * The first source offset anywhere below nodes: where a widget's content starts.
 * @param {object[]} [nodes] - parse tree nodes
 * @returns {(number|undefined)} Offset
 */
function firstStart(nodes) {
	for(var i = 0; i < (nodes || []).length; i++) {
		if(nodes[i].start !== undefined) {
			return nodes[i].start;
		}
		var inner = firstStart(nodes[i].children);
		if(inner !== undefined) {
			return inner;
		}
	}
	return undefined;
}

/**
 * Every definition body and widget content holding offset, innermost first; a widget binds its content only, not its attributes.
 * @param {object[]} tree - parse tree
 * @param {string} text - source text
 * @param {number} offset - offset into text
 * @param {boolean} [atCursor] - a cursor at a body's very end is inside it
 * @returns {Array<{node: object, definition: boolean, start: number, end: number}>} Scopes
 */
function scopesAt(tree, text, offset, atCursor) {
	var scopes = [];
	(function walk(nodes) {
		for(var i = 0; i < (nodes || []).length; i++) {
			var node = nodes[i],
				body = calls.definitionBody(node, text),
				end = body ? body.start + body.text.length : 0;
			if(body && offset >= body.start && (offset < end || (atCursor && offset === end))) {
				scopes.push({ node: node, definition: true, start: body.start, end: body.start + body.text.length });
			} else if(node.tag && node.start !== undefined && offset < node.end) {
				var content = firstStart(node.children);
				if(content !== undefined && offset >= content) {
					scopes.push({ node: node, definition: false, start: content, end: node.end });
				}
			}
			walk(node.children);
		}
	})(tree);
	return scopes.reverse();
}

/**
 * How a binding names the widget that sets it: <%if%> for a conditional clause, else the tag.
 * @param {object} node - parse tree node
 * @param {string} text - source text
 * @returns {string} Label
 */
function bindingLabel(node, text) {
	return widgets.isConditionalList(node, text) ? "<%if%>" : "<" + node.tag + ">";
}

/**
 * The binding of name at offset, or null when nothing in the document binds it there.
 * @param {string} name - variable or parameter name
 * @param {number} offset - offset into text
 * @param {object[]} tree - parse tree
 * @param {string} text - source text
 * @returns {(object|null)} Binding with ranges as offsets into text
 */
function resolve(name, offset, tree, text) {
	var scopes = scopesAt(tree, text, offset);
	for(var i = 0; i < scopes.length; i++) {
		var scope = scopes[i],
			node = scope.node;
		if(scope.definition) {
			var param = (node.params || []).filter(function(p) { return p.name === name; })[0];
			if(param) {
				return {
					kind: "parameter",
					name: name,
					of: node.attributes.name.value,
					value: param["default"],
					scope: scope,
					declaration: parameterDeclaration(node, text, name)
				};
			}
		} else if(widgets.variablesOf({ name: node.tag.slice(1), attributes: node.orderedAttributes || [] }).includes(name)) {
			return {
				kind: "variable",
				name: name,
				by: bindingLabel(node, text),
				scope: scope,
				declaration: variableDeclaration(node, text, name)
			};
		}
	}
	return null;
}

/**
 * Every name bound at a cursor, innermost scope first.
 * @param {number} offset - offset into text
 * @param {object[]} tree - parse tree
 * @param {string} text - source text
 * @returns {object[]} { name, kind, of } for a parameter, { name, kind, by } for a widget's variable
 */
function bindingsAt(offset, tree, text) {
	var found = [];
	scopesAt(tree, text, offset, true).forEach(function(scope) {
		var node = scope.node;
		if(scope.definition) {
			(node.params || []).forEach(function(param) {
				found.push({ name: param.name, kind: "parameter", of: node.attributes.name.value });
			});
		} else {
			widgets.variablesOf({ name: node.tag.slice(1), attributes: node.orderedAttributes || [] }).forEach(function(name) {
				found.push({ name: name, kind: "variable", by: bindingLabel(node, text) });
			});
		}
	});
	return found;
}

/**
 * Where a parameter is declared, between the parentheses on the pragma's first line.
 * @param {object} node - definition node
 * @param {string} text - source text
 * @param {string} name - parameter name
 * @returns {({start: number, end: number}|null)} Range
 */
function parameterDeclaration(node, text, name) {
	var line = text.slice(node.start, node.end).split("\n")[0],
		match = new RegExp("[(,\\s]" + $tw.utils.escapeRegExp(name) + "(?=\\s*[:,)])").exec(line);
	return match ? { start: node.start + match.index + 1, end: node.start + match.index + 1 + name.length } : null;
}

/**
 * Where a widget names the variable: a $let, $vars or $parameters attribute of that name, or a name, variable or counter value.
 * @param {object} node - widget node
 * @param {string} text - source text
 * @param {string} name - variable name
 * @returns {({start: number, end: number}|null)} Range
 */
function variableDeclaration(node, text, name) {
	var attributes = node.attributes || {},
		holder = attributes[name] && ["$let", "$vars", "$parameters"].includes(node.tag) ? attributes[name] : null;
	["name", "variable", "counter"].forEach(function(key) {
		if(!holder && attributes[key] && attributes[key].type === "string" && attributes[key].value === name) {
			holder = attributes[key];
		}
	});
	if(!holder || holder.start === undefined) {
		return null;
	}
	var slice = text.slice(holder.start, holder.end),
		at = holder.name === name ? slice.indexOf(name) : slice.lastIndexOf(name);
	return at < 0 ? null : { start: holder.start + at, end: holder.start + at + name.length };
}

exports.resolve = resolve;
exports.bindingsAt = bindingsAt;
exports.parameterDeclaration = parameterDeclaration;
