title: $:/core/modules/commands/inspect/lsp/lsp-typing.js
type: application/javascript
module-type: library

Text still being typed: the call or widget the cursor is inside, and where it
stands in a filter. The parser cannot help here, since an unclosed <<name or
<$name parses as plain text, so both are read from the raw text before the
cursor, the way title completion reads an open [[.

\*/

"use strict";

var filters = require("$:/core/modules/commands/inspect/lsp/lsp-filters.js"),
	calls = require("$:/core/modules/commands/inspect/calls.js");

// How far back an unclosed call is looked for, at most.
var MAX_LOOKBACK = 4000;

// A value opened inside a call runs to its closer; nothing in it opens a call.
var QUOTES = [["\"\"\"", "\"\"\""], ["{{{", "}}}"], ["[[", "]]"], ["{{", "}}"], ["\"", "\""], ["'", "'"], ["`", "`"]];

// Outside a call, code is text: a fence, then inline code in either width.
var CODE_MARKS = ["```", "``", "`"];

// The closing bracket of each filter operand opener.
var OPERAND_CLOSE = { "[": "]", "{": "}", "<": ">", "(": ")", "/": "/" };

// The innermost unclosed <<call or <$widget before offset in text, or null:
// { form: "macro"|"widget", name, nameStart, inName, args: [{name, value,
// positional}], inValue: null | {attribute, start}, argument }, argument being
// the argument name typed so far ("" after a space), else null. Offsets are
// into text; a widget's name is given without its $.
function callContext(text, offset) {
	var frames = [],
		i = lookbackStart(text, offset);
	while(i < offset) {
		var top = frames[frames.length - 1],
			mark = top ? null : codeMarkAt(text, i);
		if(mark) {
			// A mark without a partner is a literal backtick; one closing after the cursor puts the cursor in code.
			var end = text.indexOf(mark, i + mark.length);
			if(end >= 0 && end < offset) {
				i = end + mark.length;
			} else if(end >= 0) {
				return null;
			} else {
				i += mark.length;
			}
		} else if(top && top.quote) {
			var close = text.indexOf(top.quote, i);
			if(close < 0 || close + top.quote.length > offset) {
				break;
			}
			i = close + top.quote.length;
			top.quote = null;
		} else if(text.startsWith("<<", i)) {
			frames.push({ form: "macro", start: i });
			i += 2;
		} else if(text.startsWith("<$", i)) {
			frames.push({ form: "widget", start: i });
			i += 2;
		} else if(top && top.form === "macro" && text.startsWith(">>", i)) {
			frames.pop();
			i += 2;
		} else if(top && top.form === "widget" && text.charAt(i) === ">") {
			frames.pop();
			i++;
		} else {
			var quote = top ? quoteAt(text, i) : null;
			if(quote) {
				top.quote = quote[1];
				top.quoteAt = i;
				i += quote[0].length;
			} else {
				i++;
			}
		}
	}
	var frame = frames[frames.length - 1];
	return frame ? describeFrame(text, offset, frame) : null;
}

// Where an unclosed call could start: after the last pragma line before offset,
// since a definition's head ends whatever came before it.
function lookbackStart(text, offset) {
	var start = Math.max(0, offset - MAX_LOOKBACK),
		pragma = /(^|\n)\\(?:procedure|define|widget|function|end)\b[^\n]*/g,
		match;
	pragma.lastIndex = start;
	while((match = pragma.exec(text)) !== null && match.index < offset) {
		var lineStart = match.index + match[1].length;
		// On the pragma line itself, a one-line body after the head still counts.
		start = match.index + match[0].length <= offset ? match.index + match[0].length : lineStart;
	}
	return start;
}

function codeMarkAt(text, i) {
	return CODE_MARKS.find(function(mark) {
		return text.startsWith(mark, i);
	}) || null;
}

function quoteAt(text, i) {
	for(var q = 0; q < QUOTES.length; q++) {
		if(text.startsWith(QUOTES[q][0], i)) {
			return QUOTES[q];
		}
	}
	return null;
}

function describeFrame(text, offset, frame) {
	var written = text.slice(frame.start, frame.quote ? frame.quoteAt : offset),
		head = (frame.form === "macro" ? /^<<([^\s>"':\[\]]*)/ : /^<\$([^\s>\/"'=]*)/).exec(written),
		nameStart = frame.start + 2,
		context = {
			form: frame.form,
			name: head[1],
			nameStart: nameStart,
			inName: !frame.quote && nameStart + head[1].length === offset,
			args: argumentsIn(written.slice(head[0].length), frame.form),
			inValue: null,
			argument: null
		};
	if(frame.quote) {
		// The attribute or parameter whose value the cursor is typing.
		var naming = (frame.form === "macro" ? /([^\s:"'>]+)\s*:\s*$/ : /([^\s=\/>"']+)\s*=\s*$/).exec(written);
		context.inValue = { attribute: naming ? naming[1] : null, start: frame.quoteAt + quoteAt(text, frame.quoteAt)[0].length };
		context.args = argumentsIn(written.slice(head[0].length, naming ? naming.index : written.length), frame.form);
	} else if(!context.inName) {
		var typed = /\s([^\s=:"'>\/]*)$/.exec(written),
			value = (frame.form === "macro" ? /\s([^\s:"'>]+)\s*:\s*([^\s"'>]*)$/ : /\s([^\s=\/>"']+)\s*=\s*([^\s"'>]*)$/).exec(written);
		if(typed) {
			context.argument = typed[1];
			context.args = argumentsIn(written.slice(head[0].length, written.length - typed[1].length), frame.form);
		} else if(value) {
			// An unquoted value, or none yet after name: or name=.
			context.inValue = { attribute: value[1], start: offset - value[2].length };
			context.args = argumentsIn(written.slice(head[0].length, value.index), frame.form);
		}
	}
	return context;
}

// The arguments written so far, as { name, value, positional }.
function argumentsIn(rest, form) {
	var pattern = form === "macro"
			? /\s*(?:([^\s:"'>\[\]]+)\s*:\s*)?("""[\s\S]*?"""|"[^"]*"|'[^']*'|\[\[[\s\S]*?\]\]|<<[\s\S]*?>>|[^\s"'>]+)/g
			: /\s*([^\s=\/>"'`]+)(?:\s*=\s*("""[\s\S]*?"""|"[^"]*"|'[^']*'|`[^`]*`|\{\{\{[\s\S]*?\}\}\}|\{\{[\s\S]*?\}\}|<<[\s\S]*?>>|[^\s"'=>`]+))?/g,
		args = [],
		match;
	while((match = pattern.exec(rest)) !== null && match[0].trim()) {
		if(form === "macro") {
			args.push({ name: match[1] || null, value: unquote(match[2]), positional: !match[1] });
		} else {
			args.push({ name: match[1], value: unquote(match[2] || "true"), positional: false });
		}
	}
	return args;
}

// What a call context calls: a <<call>>'s name, a widget form's $variable or
// $name, else the \widget of its tag (a JavaScript widget declares nothing).
function calleeOf(context) {
	if(context.form === "macro") {
		return context.name;
	}
	var named = function(name) {
		var arg = context.args.filter(function(a) { return a.name === name; })[0];
		return arg ? arg.value : null;
	};
	if(context.name === "transclude") {
		return named("$variable");
	}
	if(context.name === "macrocall") {
		return named("$name");
	}
	return "$" + context.name;
}

// The filter typed so far on a line, up to the cursor: a filter attribute, a
// {{{ }}}, an <%if%> condition or a \function body; null elsewhere.
function filterBefore(upto) {
	var context = filters.filterContext(upto, upto.length);
	if(context) {
		return upto.slice(context.start);
	}
	var match = /<%\s*(?:else)?if\s((?:(?!%>).)*)$/.exec(upto) || /^\s*\\function\s+[^\s(]+\([^)]*\)\s(.*)$/.exec(upto);
	return match ? match[1] : null;
}

// The filter typed so far before offset in text, which may have started on an earlier line: upto
// is the cursor's line up to it, where most filters are found; null outside a filter.
function filterAt(text, offset, upto) {
	var onLine = filterBefore(upto);
	if(onLine !== null) {
		return onLine;
	}
	var before = text.slice(Math.max(0, offset - MAX_LOOKBACK), offset),
		call = callContext(text, offset);
	if(call) {
		// A call's value is a filter when its attribute says so, or when it is a {{{ }}}.
		var value = call.inValue;
		return value && ((value.attribute && calls.isFilterAttribute(value.attribute)) || text.slice(value.start - 3, value.start) === "{{{") ? text.slice(value.start, offset) : null;
	}
	var braces = before.lastIndexOf("{{{");
	if(braces >= 0 && before.indexOf("}}}", braces) < 0) {
		return before.slice(braces + 3);
	}
	var condition = /<%\s*(?:else)?if\s((?:(?!%>)[\s\S])*)$/.exec(before);
	return condition ? condition[1] : functionBodyBefore(before);
}

// The body typed so far of a \function whose head stands alone on its line, before anything ends it.
function functionBodyBefore(before) {
	var head = /(?:^|\n)[ \t]*\\function[ \t]+[^\s(]+(?:\([^)\n]*\))?[ \t]*\r?\n/g,
		match,
		last = null;
	while((match = head.exec(before)) !== null) {
		last = match;
	}
	if(!last) {
		return null;
	}
	var body = before.slice(last.index + last[0].length);
	return /(?:^|\n)[ \t]*\\(?:end|procedure|define|widget|function)\b/.test(body) ? null : body;
}

function unquote(value) {
	var quote = quoteAt(value, 0);
	return quote && value.endsWith(quote[1]) ? value.slice(quote[0].length, value.length - quote[1].length) : value;
}

// Where the cursor stands at the end of upto, a filter typed so far:
// { state: "name", word } while an operator is named, { state: "operand",
// opener, operator, word, index } inside its index-th operand, else
// { state: "other" }.
function filterPosition(upto) {
	var state = "outside",
		word = "",
		operator = "",
		opener = null,
		index = 0;
	for(var i = 0; i < upto.length; i++) {
		var ch = upto.charAt(i);
		if(state === "outside") {
			if(ch === "[") {
				state = "name";
				word = "";
			} else if(ch === "\"" || ch === "'") {
				state = ch;
			}
		} else if(state === "\"" || state === "'") {
			if(ch === state) {
				state = "outside";
			}
		} else if(state === "name") {
			if(OPERAND_CLOSE[ch]) {
				state = "operand";
				opener = ch;
				operator = word;
				word = "";
				index = 0;
			} else if(ch === "]") {
				state = "outside";
			} else {
				word += ch;
			}
		} else if(state === "operand") {
			if(ch === OPERAND_CLOSE[opener]) {
				state = "after";
			} else {
				word += ch;
			}
		} else if(state === "after") {
			if(ch === "]") {
				state = "outside";
			} else if(ch === ",") {
				state = "comma";
			} else {
				state = "name";
				word = ch;
			}
		} else if(state === "comma") {
			if(OPERAND_CLOSE[ch]) {
				state = "operand";
				opener = ch;
				word = "";
				index++;
			}
		}
	}
	if(state === "name") {
		return { state: "name", word: word };
	}
	if(state === "operand") {
		return { state: "operand", opener: opener, operator: operator, word: word, index: index };
	}
	return { state: "other" };
}

exports.callContext = callContext;
exports.calleeOf = calleeOf;
exports.argumentsIn = argumentsIn;
exports.filterBefore = filterBefore;
exports.filterAt = filterAt;
exports.filterPosition = filterPosition;
","type":"application/javascript","module-type":"library"},"$:/core/modules/commands/inspect/lsp/lsp-watch.js":{"title":"$:/core/modules/commands/inspect/lsp/lsp-watch.js","text":"/*\
title: $:/core/modules/commands/inspect/lsp/lsp-watch.js
type: application/javascript
module-type: library

Keeps a wiki the editor started in step with its folders: tiddler files a
running dev server writes for MCP tools and browser edits are read in as they
change, since this process has its own copy of the wiki.

\*/

"use strict";

var fs = $tw.node ? require("fs") : null,
	path = $tw.node ? require("path") : null;

var reload = require("$:/core/modules/commands/inspect/lsp/lsp-reload.js");

// A save arrives as several events, and the first can find the file half written.
var DEBOUNCE_MS = 100;
// Windows refuses to read a file another process is still writing.
var RETRY_CODES = ["EBUSY", "EPERM", "EACCES", "ENOENT"];
var MAX_ATTEMPTS = 5;
var META_SUFFIX = ".meta";
var NOT_TIDDLERS = ["tiddlywiki.files", "plugin.info"];

// The outermost folders holding the wiki's files, so each is watched once.
function watchRoots(tiddlersPath, filepaths) {
	var dirs = (tiddlersPath ? [path.resolve(tiddlersPath)] : []).concat(filepaths.map(function(filepath) {
		return path.dirname(path.resolve(filepath));
	}));
	return dirs.filter(function(dir, index) {
		return dirs.indexOf(dir) === index && !dirs.some(function(other) {
			return isInside(dir, other);
		});
	});
}

function isInside(dir, ancestor) {
	var relative = path.relative(ancestor, dir);
	return !!relative && !relative.startsWith("..") && !path.isAbsolute(relative);
}

// Boot skips these names wherever they appear, so they never were tiddlers.
function isExcluded(filepath) {
	return path.resolve(filepath).split(path.sep).some(function(name, index, names) {
		return $tw.boot.excludeRegExp.test(name) || (index === names.length - 1 && NOT_TIDDLERS.includes(name));
	});
}

function stripMeta(filepath) {
	return filepath.endsWith(META_SUFFIX) ? filepath.slice(0, -META_SUFFIX.length) : filepath;
}

// One spelling per file, since Windows paths ignore case.
function fileKey(filepath) {
	var resolved = path.resolve(filepath);
	return process.platform === "win32" ? resolved.toLowerCase() : resolved;
}

// Reads one changed path into the wiki and returns the titles it touched, or null
// when the path is not a file of the wiki's.
function fileChanged(filepath) {
	filepath = stripMeta(filepath);
	if(isExcluded(filepath)) {
		return null;
	}
	var stat = fs.statSync(filepath, { throwIfNoEntry: false });
	if(!stat) {
		return reload.forgetFile(filepath);
	}
	return stat.isFile() ? reload.reloadFile(filepath) : null;
}

function startWatching(options) {
	options = options || {};
	var log = options.log || function() {},
		filepaths = Object.keys($tw.boot.files || {}).map(function(title) {
			return $tw.boot.files[title].filepath;
		}).filter(Boolean),
		roots = watchRoots($tw.boot.wikiTiddlersPath, filepaths).filter(function(dir) {
			return fs.existsSync(dir);
		}),
		timers = Object.create(null),
		startedAt = Date.now(),
		loadedAtStart = new Set(filepaths.map(fileKey)),
		lastWrite = Object.create(null);

	// Windows reports a file that was only read, too; one not written since it was loaded is skipped.
	function unwritten(filepath) {
		var stat = fs.statSync(filepath, { throwIfNoEntry: false }),
			key = fileKey(filepath);
		if(!stat || !stat.isFile()) {
			return false;
		}
		if(lastWrite[key] !== undefined) {
			return stat.mtimeMs === lastWrite[key];
		}
		return loadedAtStart.has(fileKey(stripMeta(filepath))) && stat.mtimeMs < startedAt;
	}

	function schedule(filepath, attempt) {
		clearTimeout(timers[filepath]);
		timers[filepath] = setTimeout(function() {
			delete timers[filepath];
			var titles;
			try {
				if(unwritten(filepath)) {
					return;
				}
				var stat = fs.statSync(filepath, { throwIfNoEntry: false });
				titles = fileChanged(filepath);
				if(stat) {
					lastWrite[fileKey(filepath)] = stat.mtimeMs;
				}
			} catch(err) {
				if(!RETRY_CODES.includes(err.code)) {
					throw err;
				}
				if(attempt + 1 < MAX_ATTEMPTS) {
					schedule(filepath, attempt + 1);
				} else {
					log("Could not read " + filepath + ": " + err.message);
				}
				return;
			}
			if(titles && titles.length) {
				log("Reloaded from disk: " + titles.join(", "));
			}
		}, DEBOUNCE_MS);
	}

	var watchers = roots.map(function(root) {
		var watcher = fs.watch(root, { recursive: true }, function(eventType, filename) {
			if(filename) {
				schedule(path.join(root, filename.toString()), 0);
			}
		});
		watcher.on("error", function(err) {
			log("Stopped watching " + root + ": " + err.message);
		});
		// The pipe keeps the process alive; a watcher alone must not.
		watcher.unref();
		return watcher;
	});

	return {
		roots: roots,
		close: function() {
			watchers.forEach(function(watcher) {
				watcher.close();
			});
			Object.keys(timers).forEach(function(filepath) {
				clearTimeout(timers[filepath]);
			});
		}
	};
}

exports.watchRoots = watchRoots;
exports.fileChanged = fileChanged;
exports.startWatching = startWatching;
","type":"application/javascript","module-type":"library"},"$:/core/modules/commands/inspect/lsp/lsp-widgets.js":{"title":"$:/core/modules/commands/inspect/lsp/lsp-widgets.js","text":"/*\
title: $:/core/modules/commands/inspect/lsp/lsp-widgets.js
type: application/javascript
module-type: library

Hovering a widget: what it is, whether it exists, which module defines it, what
each attribute is worth, and which variables it introduces.

An attribute is not always a literal. It may be an indirect reference, a macro
call or a filtered value, and the interesting half is what those RESOLVE to at
this position, which only a booted wiki can say.

\*/

"use strict";

var source = require("$:/core/modules/commands/inspect/lsp/lsp-source.js"),
	modules = require("$:/core/modules/commands/inspect/modules.js");

// Widgets whose every attribute becomes a variable of the same name, and those
// naming one variable in an attribute.
var VARIABLE_WIDGETS = { let: true, vars: true, parameters: true };
var NAMING_ATTRIBUTE = { set: "name", qualify: "name", wikify: "name" };

// The attributes each widget's code treats as a tiddler title, in the wiki's global cache.
var TITLE_ATTRIBUTES_CACHE_KEY = "tw-lsp-title-attributes";

// Wiki and tiddler methods whose first argument is a title.
var TITLE_CALLS = "(?:getTiddler|getTiddlerText|tiddlerExists|isShadowTiddler|getTiddlerDataCached|getTiddlerData|deleteTiddler|parseTiddler|getTiddlerList|getTiddlerAsJson|renderTiddler|getCacheForTiddler|isDraftModified|getChangeCount|findDraft|generateDraftTitle|getTiddlersWithTag|sortByList|setText|setTiddlerData)\\(\\s*";

/**
 * Tells whether a widget class of this name is registered.
 * @param {string} name - widget name without $
 * @returns {boolean} True if registered
 */
function isRegistered(name) {
	var classes = $tw.rootWidget && $tw.rootWidget.widgetClasses;
	return !!(classes && classes[name]);
}

/**
 * The \widget definition that takes over this tag, decided as makeChildWidget in core widget.js does.
 * @param {string} name - widget name without $
 * @param {object} [context] - widget at the position
 * @returns {(object|null)} The definition variable, or null
 */
function customWidgetOf(name, context) {
	if(!context || (name.indexOf(".") === -1 && !(isRegistered(name) && !$tw.safeMode))) {
		return null;
	}
	var info = context.getVariableInfo("$" + name, { allowSelfAssigned: true }),
		variable = info && info.srcVariable;
	return variable && variable.value && variable.isWidgetDefinition ? variable : null;
}

/**
 * Tells whether a node is a $list the parser built for an <%if%> or <%elseif%> clause, which no one wrote as a tag.
 * @param {object} node - parse tree node
 * @param {string} text - source text
 * @returns {boolean} True for a conditional clause
 */
function isConditionalList(node, text) {
	return node.tag === "$list" && node.start !== undefined && /^<%\s*(?:if|elseif)\s/.test(text.slice(node.start, node.start + 12));
}

/**
 * Every widget written in angle-bracket syntax, unregistered ones included, since a misspelt widget is silent in TiddlyWiki.
 * @param {object[]} tree - parse tree
 * @param {string} [text] - source text
 * @returns {object[]} Sites as { name, type, start, end, spots, attributes }
 */
function widgetSites(tree, text) {
	var sites = [];
	source.eachNode(tree, function(node) {
		if(!node.tag || node.tag.charAt(0) !== "$" || node.start === undefined) {
			return;
		}
		// An <%if%> block gets a hover of its own.
		if(text !== undefined && isConditionalList(node, text)) {
			return;
		}
		sites.push({
			name: node.tag.slice(1),
			type: node.type,
			start: node.start,
			end: node.end,
			spots: tagSpots(node),
			attributes: node.orderedAttributes || toOrdered(node.attributes)
		});
	});
	return sites;
}

/**
 * Where a widget answers a hover: its opening and closing tags, or the whole self-closing tag.
 * @param {object} node - parse tree node
 * @returns {Array<{start: number, end: number}>} Ranges
 */
function tagSpots(node) {
	if(node.openTagStart === undefined) {
		return [{ start: node.start, end: node.end }];
	}
	var spots = [{ start: node.openTagStart, end: node.openTagEnd }];
	if(node.closeTagEnd > node.closeTagStart) {
		spots.push({ start: node.closeTagStart, end: node.closeTagEnd });
	}
	return spots;
}

/**
 * The attributes of a node as a list.
 * @param {object} [attributes] - attributes by name
 * @returns {object[]} Attributes
 */
function toOrdered(attributes) {
	var out = [];
	for(var name in attributes || {}) {
		out.push(attributes[name]);
	}
	return out;
}

/**
 * An attribute as the author wrote it, whatever its kind.
 * @param {object} attribute - parse tree attribute
 * @returns {string} Written form
 */
function writtenOf(attribute) {
	switch(attribute.type) {
		case "indirect":
			return "{{" + attribute.textReference + "}}";
		case "macro": {
			var variable = attribute.value && attribute.value.attributes && attribute.value.attributes.$variable;
			return "<<" + (variable ? variable.value : "") + ">>";
		}
		case "filtered":
			return "{{{" + attribute.filter + "}}}";
		case "substituted":
			return "`" + attribute.rawValue + "`";
		default:
			return attribute.value;
	}
}

/**
 * What an attribute is worth here; only a string is its own value.
 * @param {object} attribute - parse tree attribute
 * @param {object} [context] - widget at the position
 * @returns {{kind: string, written: string, value: *}} Resolved attribute
 */
function resolveAttribute(attribute, context) {
	switch(attribute.type) {
		case "indirect":
			return {
				kind: "indirect",
				written: writtenOf(attribute),
				value: $tw.wiki.getTextReference(attribute.textReference, "", currentOf(context))
			};
		case "macro": {
			var variable = attribute.value && attribute.value.attributes && attribute.value.attributes.$variable;
			var name = variable ? variable.value : "";
			return {
				kind: "macro",
				written: writtenOf(attribute),
				value: context && name ? context.getVariable(name) : undefined
			};
		}
		case "filtered":
			return {
				kind: "filtered",
				written: writtenOf(attribute),
				value: $tw.wiki.filterTiddlers(attribute.filter, context || undefined).join(" ")
			};
		case "substituted":
			return {
				kind: "substituted",
				written: writtenOf(attribute),
				value: context ? $tw.wiki.getSubstitutedText(attribute.rawValue, context) : undefined
			};
		default:
			return { kind: attribute.type || "string", written: writtenOf(attribute), value: attribute.value };
	}
}

/**
 * The currentTiddler variable at a position.
 * @param {object} [context] - widget at the position
 * @returns {(string|undefined)} Title
 */
function currentOf(context) {
	return context ? context.getVariable("currentTiddler") : undefined;
}

/**
 * The variables this widget introduces, so a <$let> says what it binds.
 * @param {{name: string, attributes: object[]}} site - widget name and ordered attributes
 * @returns {string[]} Variable names
 */
function variablesOf(site) {
	var byName = {};
	site.attributes.forEach(function(attribute) {
		byName[attribute.name] = attribute;
	});
	if(VARIABLE_WIDGETS[site.name]) {
		// On $parameters a $ attribute configures the widget rather than naming one.
		return site.attributes.map(function(a) { return a.name; }).filter(function(name) {
			return site.name !== "parameters" || name.charAt(0) !== "$";
		});
	}
	var naming = NAMING_ATTRIBUTE[site.name];
	if(naming) {
		return literal(byName[naming]) ? [literal(byName[naming])] : [];
	}
	if(site.name === "list") {
		var names = [literal(byName.variable) || "currentTiddler"],
			counter = literal(byName.counter);
		// Core list.js sets <counter>-first and <counter>-last beside the counter.
		if(counter) {
			names.push(counter, counter + "-first", counter + "-last");
		}
		return names;
	}
	return site.name === "tiddler" ? ["currentTiddler"] : [];
}

/**
 * The value of a string attribute.
 * @param {object} [attribute] - parse tree attribute
 * @returns {(string|null)} Value, or null for any other kind
 */
function literal(attribute) {
	return attribute && attribute.type === "string" ? attribute.value : null;
}

/**
 * The attributes a registered widget's code treats as a tiddler title, read from how the code uses each one.
 * @param {string} name - widget name without $
 * @returns {string[]} Attribute names
 */
function titleAttributes(name) {
	var cache = $tw.wiki.getGlobalCache(TITLE_ATTRIBUTES_CACHE_KEY, function() { return Object.create(null); });
	if(!cache[name]) {
		var title = isRegistered(name) ? modules.moduleOfWidget(name) : null;
		cache[name] = title ? titleAttributesIn(codeWithRequired(title)) : [];
	}
	return cache[name];
}

/**
 * A module's code followed by the non-widget libraries it requires, since a widget may read its attributes in a shared factory.
 * @param {string} title - module title
 * @returns {string} Code
 */
function codeWithRequired(title) {
	var code = moduleCode(title),
		required = /require\(\s*["']([^"']+)["']\s*\)/g,
		match,
		all = code;
	while((match = required.exec(code)) !== null) {
		var info = $tw.modules.titles[match[1]];
		if(info && info.moduleType !== "widget") {
			all += "\n" + moduleCode(match[1]);
		}
	}
	return all;
}

/**
 * The code that runs: the definition the module was made from, not a tiddler edited since.
 * @param {string} title - module title
 * @returns {string} Code
 */
function moduleCode(title) {
	var info = $tw.modules.titles[title];
	return info && typeof info.definition === "string" ? info.definition : $tw.wiki.getTiddlerText(title, "");
}

/**
 * The text after the fields of the running module's header, read with boot.js's own pattern.
 * @param {string} title - module title
 * @returns {string} Description
 */
function moduleDescription(title) {
	var header = new RegExp($tw.config.jsModuleHeaderRegExpString, "m").exec(moduleCode(title));
	return header ? header[1].split(/\r?\n\r?\n/).slice(1).join("\n\n").trim() : "";
}

/**
 * Attributes read on a line that falls back to the current tiddler, or kept in a holder used as a title directly or through one alias.
 * @param {string} code - module code
 * @returns {string[]} Attribute names
 */
function titleAttributesIn(code) {
	var found = [],
		match;
	function add(attribute) {
		if(!found.includes(attribute)) {
			found.push(attribute);
		}
	}
	code.split("\n").forEach(function(line) {
		if(/getVariable\(\s*"currentTiddler"/.test(line)) {
			eachMatch(/getAttribute\(\s*"([^"]+)"/g, line, function(read) {
				add(read[1]);
			});
		}
	});
	var kept = /(?:(?:var|let|const|,)\s*|this\.)([\w$]+)\s*=\s*(?:self|this)\.getAttribute\(\s*"([^"]+)"/g;
	while((match = kept.exec(code)) !== null) {
		var holder = (match[0].startsWith("this.") ? "this\\." : "\\b") + $tw.utils.escapeRegExp(match[1]),
			used = usedAsTitle(code, holder),
			aliases = new RegExp("(?:(?:var|let|const|,)\\s*|[;{(\\s])([\\w$]+)\\s*=\\s*" + holder + "\\b", "g"),
			alias;
		while(!used && (alias = aliases.exec(code)) !== null) {
			used = usedAsTitle(code, "\\b" + $tw.utils.escapeRegExp(alias[1]));
		}
		if(used) {
			add(match[2]);
		}
	}
	return found;
}

/**
 * Tells whether code uses an expression as a tiddler title.
 * @param {string} code - module code
 * @param {string} expression - regular expression source of the holder
 * @returns {boolean} True if used as a title
 */
function usedAsTitle(code, expression) {
	return new RegExp(TITLE_CALLS + expression + "\\s*[,)]|\\btitle:\\s*" + expression + "\\b|navigateTo:\\s*" + expression +
		"\\b|\\$?tiddler:\\s*\\{\\s*type:\\s*\"string\",\\s*value:\\s*" + expression + "\\b|setVariable\\(\\s*\"currentTiddler\"\\s*,\\s*" + expression + "\\b").test(code);
}

/**
 * Calls fn with every match of a global pattern.
 * @param {RegExp} pattern - global regular expression
 * @param {string} text - text to search
 * @param {function(Array): void} fn - receives each match
 * @returns {void}
 */
function eachMatch(pattern, text, fn) {
	var match;
	while((match = pattern.exec(text)) !== null) {
		fn(match);
	}
}

exports.widgetSites = widgetSites;
exports.isConditionalList = isConditionalList;
exports.resolveAttribute = resolveAttribute;
exports.writtenOf = writtenOf;
exports.variablesOf = variablesOf;
exports.isRegistered = isRegistered;
exports.customWidgetOf = customWidgetOf;
exports.titleAttributes = titleAttributes;
exports.moduleCode = moduleCode;
exports.moduleDescription = moduleDescription;
","type":"application/javascript","module-type":"library"},"$:/core/modules/commands/inspect/mcp/mcp-lib.js":{"title":"$:/core/modules/commands/inspect/mcp/mcp-lib.js","text":"/*\
title: $:/core/modules/commands/inspect/mcp/mcp-lib.js
type: application/javascript
module-type: library

Zero-dependency MCP (Model Context Protocol) server for TiddlyWiki.
Implements JSON-RPC 2.0 over stdio transport.

\*/

"use strict";

// Node-only modules — guard so this library loads cleanly in the browser
// (where it's exposed via plugin payload but only ever called server-side).
var fs = $tw.node ? require("fs") : null,
	path = $tw.node ? require("path") : null,
	net = $tw.node ? require("net") : null,
	crypto = $tw.node ? require("crypto") : null;

var handlers = require("$:/core/modules/commands/inspect/mcp-handlers.js");

var PROTOCOL_VERSION = "2026-07-28";
var MODERN_VERSIONS = [PROTOCOL_VERSION];

// Handshake-era revisions, still served. The trigger is not a legacy client:
// a DUAL-era client falls back to initialize when server/discover does not
// answer inside its own probe window, and a slow wiki boot is enough to cause
// that. Measured 2026-08-16 — a cold tw5.com boot took 18.6s to reach
// startMCPServer, the client had already fallen back, and answering -32022 to
// the fallback turned a slow start into a hard connection failure.
var LEGACY_VERSIONS = ["2025-11-25", "2025-06-18", "2025-03-26"];
var LEGACY_DEFAULT_VERSION = LEGACY_VERSIONS[0];

var SUPPORTED_VERSIONS = MODERN_VERSIONS.concat(LEGACY_VERSIONS);
var SERVER_NAME = "tiddlywiki-mcp";
var PLUGIN_TITLE = "$:/plugins/wikilabs/tw-mcp";

// Spec-defined _meta keys. 2026-07-28 has no handshake, so a request carries
// its own version and identity and a result carries the server's.
var META_VERSION = "io.modelcontextprotocol/protocolVersion";
var META_CLIENT_INFO = "io.modelcontextprotocol/clientInfo";
var META_CLIENT_CAPS = "io.modelcontextprotocol/clientCapabilities";
var META_SERVER_INFO = "io.modelcontextprotocol/serverInfo";

// tw-mcp's own pipe-transport metadata. Statelessness removes the single
// initialize that used to carry the token and identify the connecting process,
// so every message over the pipe now carries both.
var TW_AUTH = "wikilabs.tw-mcp/auth";
var TW_PID = "wikilabs.tw-mcp/pid";
var TW_LABEL = "wikilabs.tw-mcp/label";
var TW_ROLE = "wikilabs.tw-mcp/role";

var RELOAD_FILE_METHOD = "wikilabs.tw-mcp/reloadFile";
var LSP_HELLO_METHOD = "wikilabs.tw-mcp/lspHello";
var UNREADABLE_CODES = ["EBUSY", "EPERM", "EACCES", "ENOENT"];

// Freshness hint for list results. Deliberately short: the tool list is not
// static here, since it varies with readonly mode and reload_mcp_modules can
// change it mid-process, and we advertise no listChanged notification.
var LIST_TTL_MS = 60000;

/**
 * The tw-mcp plugin version.
 * @returns {string} Version
 */
function getServerVersion() {
	var pluginTiddler = $tw.wiki.getTiddler(PLUGIN_TITLE);
	return (pluginTiddler && pluginTiddler.fields.version) || "0.0.0";
}

var readonlyMode = false;
var allowedPaths = null; // null = no restriction, array of absolute paths = restrict output to these directories
var authToken = null; // generated at startup for pipe transport authentication
var serverLabel = null; // optional user-defined label to identify this instance
var pipeClients = {}; // clientId -> { send, socket } — authenticated pipe clients
var currentPipeServer = null; // reference to the active net.Server for the pipe
var takeoverInProgress = false; // guard against concurrent takeover requests
var lspClients = {}; // clientId -> what an editor's LSP process said about itself

// --- Path validation helpers ---

/**
 * Tells whether a path lies inside the allowed paths.
 * @param {string} targetPath - path to check
 * @returns {boolean} True if allowed
 */
function isPathAllowed(targetPath) {
	if(!allowedPaths || allowedPaths.length === 0) {
		return true;
	}
	// Normalize separators for consistent comparison (Windows can mix / and \)
	var resolved = path.resolve(targetPath).replace(/\\/g, "/");
	for(var i = 0; i < allowedPaths.length; i++) {
		var allowed = path.resolve(allowedPaths[i]).replace(/\\/g, "/");
		// Ensure allowed ends without trailing slash for consistent prefix matching
		if(allowed.length > 1 && allowed.charAt(allowed.length - 1) === "/") {
			allowed = allowed.slice(0, -1);
		}
		// Check that target is inside or equal to an allowed directory
		if(resolved === allowed || resolved.indexOf(allowed + "/") === 0) {
			return true;
		}
	}
	return false;
}

/**
 * Why a path may not be written, or null when it may.
 * @param {string} targetPath - path to check
 * @returns {(string|null)} Error message
 */
function checkPathAllowed(targetPath) {
	if(!isPathAllowed(targetPath)) {
		process.stderr.write("[tw-mcp] BLOCKED path: " + path.resolve(targetPath) + " | allowed: " + allowedPaths.join(", ") + "\n");
		return {
			isError: true,
			content: [{ type: "text", text: "Path not allowed: " + path.resolve(targetPath) + ". Allowed directories: " + allowedPaths.join(", ") }]
		};
	}
	return null;
}

// --- JSON-RPC helpers ---

/**
 * This server's name and version.
 * @returns {{name: string, version: string}} Identity
 */
function serverIdentity() {
	return { name: SERVER_NAME, version: getServerVersion() };
}

/**
 * The _meta of an inbound request, or an empty object when it carries none.
 * @param {object} parsed - JSON-RPC message
 * @returns {object} Meta
 */
function getMeta(parsed) {
	return (parsed && parsed.params && parsed.params._meta) || {};
}

/**
 * The _meta a proxy's own requests carry, declaring version and identity like any client's.
 * @returns {object} Params with _meta
 */
function buildRequestMeta() {
	var params = { _meta: {} };
	params._meta[META_VERSION] = PROTOCOL_VERSION;
	params._meta[META_CLIENT_INFO] = serverIdentity();
	// Empty rather than absent: a proxy front-end relays, so it declares no
	// capabilities of its own. A relayed client message keeps the client's.
	params._meta[META_CLIENT_CAPS] = {};
	return params;
}

/**
 * A JSON-RPC result line; a modern one carries resultType and the server identity, a handshake-era one neither.
 * @param {*} id - request id
 * @param {object} result - result
 * @param {string} [era] - modern (default) or legacy
 * @returns {string} Line
 */
function jsonrpcResponse(id, result, era) {
	var payload = result || {};
	if(era !== "legacy") {
		if(payload.resultType === undefined) {
			payload.resultType = "complete";
		}
		payload._meta = payload._meta || {};
		payload._meta[META_SERVER_INFO] = serverIdentity();
	}
	return JSON.stringify({ jsonrpc: "2.0", id: id, result: payload });
}

/**
 * A JSON-RPC error line.
 * @param {*} id - request id
 * @param {number} code - error code
 * @param {string} message - message
 * @param {*} [data] - error data
 * @returns {string} Line
 */
function jsonrpcError(id, code, message, data) {
	var err = { jsonrpc: "2.0", id: id, error: { code: code, message: message } };
	if(data !== undefined) {
		err.error.data = data;
	}
	return JSON.stringify(err);
}

/**
 * A parsed JSON-RPC line, or null when it is not JSON; any other failure propagates.
 * @param {string} line - input line
 * @returns {(object|null)} Message
 */
function parseJsonRpc(line) {
	try {
		return JSON.parse(line);
	} catch(e) {
		if(e instanceof SyntaxError) {
			return null;
		}
		throw e;
	}
}

// --- MCP Server ---

// --- Shared message dispatcher (used by stdio and pipe transports) ---

/**
 * Logs a line to stderr, which is free since stdout carries the protocol.
 * @param {string} msg - message
 * @returns {void}
 */
function log(msg) {
	var now = new Date();
	var ts = now.toISOString().slice(11, 23);
	process.stderr.write("[tw-mcp " + ts + "] " + msg + "\n");
}

// Shorten pipe paths after the first mention so repeated log lines stay readable.
var pipePathFullyShown = false;
/**
 * A pipe path shortened for the log.
 * @param {string} p - pipe path
 * @returns {string} Display form
 */
function fmtPipe(p) {
	if(!p) return p;
	if(!pipePathFullyShown) {
		pipePathFullyShown = true;
		return p;
	}
	var idx = p.lastIndexOf("tiddlywiki-mcp-");
	if(idx < 0) return p;
	var tail = p.slice(idx + "tiddlywiki-mcp-".length);
	if(tail.length > 24) {
		tail = "…" + tail.slice(-22);
	}
	return "pipe:" + tail;
}

// Suppress the redundant "Initialized" log for pipe clients — the auth log already covers it.
var suppressNextInitLog = false;

/**
 * The mode for the log, READONLY in capitals so a disabled write is noticed.
 * @returns {string} Mode
 */
function fmtMode() {
	return "mode: " + (readonlyMode ? "READONLY" : "readwrite");
}

/**
 * The client named by a message, per request for modern clients and in clientInfo on initialize for older ones.
 * @param {object} parsed - JSON-RPC message
 * @returns {string} Description
 */
function describeClient(parsed) {
	var info = getMeta(parsed)[META_CLIENT_INFO] || (parsed && parsed.params && parsed.params.clientInfo);
	if(info && info.name) {
		return info.name + (info.version ? " " + info.version : "");
	}
	return "unidentified client";
}

/**
 * The revision a message belongs to, as a pure function of the message; an absent version means legacy.
 * @param {object} parsed - JSON-RPC message
 * @returns {(string|null)} modern, legacy, or null for an unknown version
 */
function eraOfMessage(parsed) {
	if(parsed.method === "server/discover") {
		return "modern";
	}
	if(parsed.method === "initialize") {
		return "legacy";
	}
	var declared = getMeta(parsed)[META_VERSION];
	if(declared === undefined || declared === null) {
		return "legacy";
	}
	if(MODERN_VERSIONS.indexOf(declared) >= 0) {
		return "modern";
	}
	if(LEGACY_VERSIONS.indexOf(declared) >= 0) {
		return "legacy";
	}
	return null;
}

// Rolling history of recent requests so we can identify what was cancelled.
// Map: requestId -> { method, toolName, at }
var requestHistory = Object.create(null);
var requestHistoryOrder = [];
var REQUEST_HISTORY_SIZE = 50;

/**
 * Remembers a request, so a later log line can name it.
 * @param {*} id - request id
 * @param {string} method - method
 * @param {string} [toolName] - tool of a tools/call
 * @returns {void}
 */
function recordRequest(id, method, toolName) {
	if(id === undefined || id === null) return;
	requestHistory[id] = { method: method, toolName: toolName, at: Date.now() };
	requestHistoryOrder.push(id);
	while(requestHistoryOrder.length > REQUEST_HISTORY_SIZE) {
		var old = requestHistoryOrder.shift();
		delete requestHistory[old];
	}
}

/**
 * A remembered request with its age, for the log.
 * @param {*} id - request id
 * @returns {string} Description
 */
function describeRequest(id) {
	var entry = requestHistory[id];
	if(!entry) return "unknown (id=" + id + ")";
	var elapsed = Date.now() - entry.at;
	var name = entry.toolName ? entry.method + " " + entry.toolName : entry.method;
	return name + " (id=" + id + ", " + elapsed + "ms ago)";
}

// --- Confirmation gate (MRTR) ---

// Tools whose blast radius is invisible in their arguments. A filter string
// does not tell anyone it resolves to 43 tiddlers, so these are confirmed
// against the RESOLVED set instead of the arguments. Tools whose argument IS
// the consequence (delete_tiddler names one title) are deliberately absent:
// the client already prompts for them and would only ask the same thing twice.
var CONFIRM_TOOLS = { replace_in_tiddlers: true };
var CONFIRM_THRESHOLD = 1; // confirm when MORE than this many tiddlers change
var CONFIRM_KEY = "confirm_bulk_write";
var CONFIRM_TTL_MS = 5 * 60 * 1000;
var CONFIRM_TITLE_SAMPLE = 20;

// Per-process secret. requestState travels through the client, which the spec
// treats as attacker-controlled, so it is signed and verified on return.
var confirmSecret = crypto ? crypto.randomBytes(32) : null;

/**
 * A confirmation state signed with this process's secret.
 * @param {object} payload - state to sign
 * @returns {string} Signed state
 */
function signRequestState(payload) {
	var body = Buffer.from(JSON.stringify(payload), "utf8").toString("base64");
	return body + "." + crypto.createHmac("sha256", confirmSecret).update(body).digest("hex");
}

/**
 * Tells whether a confirmation state is signed, unexpired and still matches the impact digest.
 * @param {string} state - signed state
 * @param {string} expectedDigest - digest of the current impact
 * @returns {boolean} True if valid
 */
function verifyRequestState(state, expectedDigest) {
	if(typeof state !== "string") return false;
	var parts = state.split(".");
	if(parts.length !== 2) return false;
	var expectedMac = Buffer.from(crypto.createHmac("sha256", confirmSecret).update(parts[0]).digest("hex"), "utf8");
	var actualMac = Buffer.from(parts[1], "utf8");
	if(expectedMac.length !== actualMac.length || !crypto.timingSafeEqual(expectedMac, actualMac)) {
		return false;
	}
	var payload = JSON.parse(Buffer.from(parts[0], "base64").toString("utf8"));
	return payload.exp > Date.now() && payload.digest === expectedDigest;
}

/**
 * A digest of what a write would affect, so a changed target set needs a new confirmation.
 * @param {string} toolName - tool
 * @param {object} toolArgs - arguments
 * @param {string[]} titles - affected titles
 * @returns {string} Digest
 */
function impactDigest(toolName, toolArgs, titles) {
	return crypto.createHash("sha256").update(JSON.stringify({
		tool: toolName,
		rules: toolArgs.rules,
		filter: toolArgs.filter,
		fields: toolArgs.fields,
		titles: titles.slice().sort()
	}), "utf8").digest("hex");
}

/**
 * The message asking the user to confirm a write.
 * @param {string[]} titles - affected titles
 * @param {object} impact - what the write does
 * @returns {string} Message
 */
function confirmMessage(titles, impact) {
	var shown = titles.slice(0, CONFIRM_TITLE_SAMPLE);
	var more = titles.length - shown.length;
	return "Apply " + impact.totalReplacements + " replacement(s) across " + titles.length + " tiddlers?\n\n" +
		shown.join("\n") + (more > 0 ? "\n... and " + more + " more" : "") +
		(impact.truncated ? "\n\n(the preview was truncated by a limit, so more may match)" : "");
}

/**
 * Answers a write that needs confirmation; false lets the call proceed.
 * @param {object} parsed - JSON-RPC message
 * @param {string} toolName - tool
 * @param {object} toolArgs - arguments
 * @param {*} id - request id
 * @param {function(string): void} send - writes a line
 * @returns {boolean} True when answered here
 */
function confirmationHandled(parsed, toolName, toolArgs, id, send) {
	if(!CONFIRM_TOOLS[toolName] || !crypto) return false;
	// dry_run defaults true, so only an explicit apply is destructive.
	if(toolArgs.dry_run !== false) return false;
	// The spec forbids sending an input request a client has not declared.
	// Without elicitation there is no way to ask, so behaviour is unchanged.
	var caps = getMeta(parsed)[META_CLIENT_CAPS];
	if(!caps || !caps.elicitation) return false;

	// Resolve the real impact by previewing. This is what we confirm against.
	var previewArgs = $tw.utils.extend({}, toolArgs);
	previewArgs.dry_run = true;
	var preview = handlers.handleToolCall(toolName, previewArgs);
	var impact = preview && preview.structuredContent;
	if(!impact || !impact.affectedTitles || impact.affectedTitles.length <= CONFIRM_THRESHOLD) {
		return false; // narrow enough to need no confirmation
	}

	var digest = impactDigest(toolName, toolArgs, impact.affectedTitles);
	var responses = parsed.params && parsed.params.inputResponses;
	var answer = responses && responses[CONFIRM_KEY];
	if(answer && verifyRequestState(parsed.params && parsed.params.requestState, digest)) {
		if(answer.action === "accept" && answer.content && answer.content.confirm === true) {
			return false; // confirmed against this exact set — proceed
		}
		send(jsonrpcResponse(id, {
			isError: true,
			content: [{ type: "text", text: toolName + ": cancelled, not confirmed. Nothing was written." }]
		}));
		return true;
	}

	var request = { method: "elicitation/create", params: {
		mode: "form",
		message: confirmMessage(impact.affectedTitles, impact),
		requestedSchema: {
			type: "object",
			properties: { confirm: { type: "boolean", description: "Apply these changes" } },
			required: ["confirm"]
		}
	}};
	var result = { resultType: "input_required", inputRequests: {}, requestState: signRequestState({
		digest: digest,
		exp: Date.now() + CONFIRM_TTL_MS
	})};
	result.inputRequests[CONFIRM_KEY] = request;
	send(jsonrpcResponse(id, result));
	return true;
}

/**
 * The guidance a client gets about this wiki, on server/discover and on initialize alike.
 * @returns {string} Instructions
 */
function buildInstructions() {
	return "TiddlyWiki MCP server." +
		(readonlyMode ? " READONLY mode — writes disabled." : "") +
		($tw.wiki.getTiddler("$:/temp/mcp/html-import") && $tw.wiki.getTiddler("$:/temp/mcp/html-import").fields.status === "pending" ?
			"\n\n## HTML import pending\n" +
			"$:/temp/mcp/html-import staged but not on disk. Read it for analysis, let user review/edit $:/config/FileSystemPaths, then call extract_html_wiki."
			: "") +
		"\n\n## Safety\n" +
		"- Never write tiddlers without explicit user request (create/edit/update/delete/rename/tag/untag). 'list','show','find','search' = read-only.\n" +
		"- Bulk ops: list affected tiddlers and confirm first.\n" +
		"- get_tiddler before overwriting.\n" +
		"\n## System tiddlers\n" +
		"- Default-exclude '$:/' — prepend '!is[system]' to filters unless user asks for system/shadow tiddlers.\n" +
		"- Shadow fallback: if 2-3 searches return empty, retry with '[all[shadows+tiddlers]]'. Many important tiddlers are shadows.\n" +
		"- Don't fetch '$:/core/modules/...' unless user names one.\n" +
		"\n## Token use\n" +
		"- Tool results are pre-formatted; pass through, don't reformat.\n" +
		"- Render/filter/wiki-info → MCP. Code search → Read/Grep/Glob.\n" +
		"\n## Tool choice (trigger words)\n" +
		"- WRITE (create/edit/update/change/fix/delete/rename/tag/untag): get_tiddler(detailed=true) → edit_tiddler for small edits (LINE#HASH anchors), put_tiddler for new tiddlers or full rewrites.\n" +
		"- READ (show/list/find/search/what/how many/which): get_tiddler(detailed=true); format='tid' only when plain text needed.\n" +
		"- RENDER (render/preview/'what does X look like'): render_tiddler (whole), render_field (one field), render_text (raw wikitext). get_tiddler returns SOURCE, not rendered output.\n" +
		"- put_tiddler resends full text — never use for small edits.\n" +
		"- Omit type when it's text/vnd.tiddlywiki (default).\n" +
		"\n## Filters\n" +
		"- Narrow first: '[!is[system]search[x]]'. Shadows: '[all[shadows+tiddlers]prefix[$:/config/]]'.\n" +
		"\n## Single-file HTML wiki import\n" +
		"- import_html_wiki(path) into an empty wiki folder, then extract_html_wiki() once user approves FileSystemPaths.\n" +
		"\n## Hot reload (no server restart)\n" +
		"- Edition tiddlers on disk → reload_tiddlers (scope='tiddlers').\n" +
		"- Non-JS plugin subtiddler in tw-mcp → reload_mcp_modules. Other plugins: user re-adds plugin tiddler so TW auto-reloads.\n" +
		"- tw-mcp JS handler → reload_mcp_modules (disk re-read + JS re-exec).\n" +
		"- mcp.js / mcp-lib.js / shared.js / filesystem.js → full server restart.";
}

/**
 * Answers one JSON-RPC line.
 * @param {string} line - input line
 * @param {function(string): void} send - writes a line
 * @returns {void}
 */
function dispatchMessage(line, send) {
	var parsed;
	try {
		parsed = JSON.parse(line);
	} catch(e) {
		send(jsonrpcError(null, -32700, "Parse error"));
		return;
	}

	// Notifications have no id — no response needed
	if(parsed.id === undefined || parsed.id === null) {
		if(parsed.method === "notifications/initialized") {
			log("Client initialized");
		} else if(parsed.method === "notifications/cancelled") {
			var params = parsed.params || {};
			var reason = params.reason || "no reason given";
			log("Request cancelled: " + describeRequest(params.requestId) + " — reason: " + reason);
		} else if(parsed.method === "notifications/takeover-request") {
			handleTakeoverRequest(parsed.params);
		}
		return;
	}

	var id = parsed.id;
	var method = parsed.method;
	var toolName = (method === "tools/call" && parsed.params) ? parsed.params.name : null;
	recordRequest(id, method, toolName);

	// A message that names a version we do not speak is refused in both eras.
	// An ABSENT version is not that case — it is how a handshake-era client
	// looks — so eraOfMessage reports legacy for it rather than null.
	var era = eraOfMessage(parsed);
	if(era === null) {
		send(jsonrpcError(id, -32022, "Unsupported protocol version",
			{ supported: SUPPORTED_VERSIONS, requested: getMeta(parsed)[META_VERSION] || null }));
		return;
	}
	switch(method) {
		case "initialize": {
			// The handshake spec says to echo the requested version when we speak
			// it and to name one we do speak otherwise, letting the client decide
			// whether to continue. A client arriving here has already given up on
			// server/discover, so refusing it strands the connection.
			var requested = (parsed.params && parsed.params.protocolVersion) || null;
			var negotiated = LEGACY_VERSIONS.indexOf(requested) >= 0 ? requested : LEGACY_DEFAULT_VERSION;
			send(jsonrpcResponse(id, {
				protocolVersion: negotiated,
				capabilities: { tools: {} },
				serverInfo: serverIdentity(),
				instructions: buildInstructions()
			}, era));
			log("Initialized by " + describeClient(parsed) + " (protocol " + negotiated + ", " + fmtMode() + ")");
			break;
		}

		case "server/discover":
			send(jsonrpcResponse(id, {
				supportedVersions: SUPPORTED_VERSIONS,
				capabilities: {
					tools: {}
				},
				instructions: buildInstructions()
			}, era));
			if(suppressNextInitLog) {
				suppressNextInitLog = false;
			} else {
				log("Discovered by " + describeClient(parsed) + " (protocol " + PROTOCOL_VERSION + ", " + fmtMode() + ")");
			}
			break;

		case "ping":
			// 2026-07-28 removed ping, but every handshake-era revision has it and
			// a legacy client may use it as a liveness check. Answer it for those
			// and keep it absent for modern ones, rather than serving one method
			// under two contradicting contracts.
			if(era === "legacy") {
				send(jsonrpcResponse(id, {}, era));
			} else {
				send(jsonrpcError(id, -32601, "Method not found: " + method));
			}
			break;

		case "tools/list": {
			// ttlMs and cacheScope are required on 2026-07-28 list results.
			// private, because the list is specific to this wiki and this readonly
			// mode and must never be reused by a shared intermediary. Neither
			// field exists in the handshake era, so neither is sent there.
			var listResult = { tools: handlers.getToolDefinitions(readonlyMode) };
			if(era === "modern") {
				listResult.ttlMs = LIST_TTL_MS;
				listResult.cacheScope = "private";
			}
			send(jsonrpcResponse(id, listResult, era));
			break;
		}

		case "tools/call": {
			var toolName = parsed.params && parsed.params.name;
			var toolArgs = (parsed.params && parsed.params.arguments) || {};
			if(confirmationHandled(parsed, toolName, toolArgs, id, send)) {
				break;
			}
			var result = handlers.handleToolCall(toolName, toolArgs);
			if(result === null) {
				send(jsonrpcError(id, -32602, "Unknown tool: " + toolName));
			} else {
				send(jsonrpcResponse(id, result, era));
			}
			break;
		}

		// Not MCP: the LSP process an editor started holds its own copy of this wiki
		// and names a file it saved, so the browser and tools here see the save too.
		case RELOAD_FILE_METHOD: {
			var savedPath = parsed.params && parsed.params.path;
			if(typeof savedPath !== "string" || !savedPath) {
				send(jsonrpcError(id, -32602, RELOAD_FILE_METHOD + " needs a path"));
				break;
			}
			send(reloadSavedFile(id, path.resolve(savedPath), era));
			break;
		}

		default:
			send(jsonrpcError(id, -32601, "Method not found: " + method));
			break;
	}
}

/**
 * Reloads a file an editor saved; a file being written or gone is an error answer, anything else propagates.
 * @param {*} id - request id
 * @param {string} filepath - saved file
 * @param {string} era - modern or legacy
 * @returns {string} Response line
 */
function reloadSavedFile(id, filepath, era) {
	var watch = require("$:/core/modules/commands/inspect/lsp/lsp-watch.js"),
		titles;
	try {
		titles = watch.fileChanged(filepath);
	} catch(err) {
		if(!UNREADABLE_CODES.includes(err.code)) {
			throw err;
		}
		return jsonrpcError(id, -32603, "Could not read " + filepath + ": " + err.message);
	}
	if(titles && titles.length) {
		log("Reloaded " + titles.join(", ") + " saved in the editor");
	}
	return jsonrpcResponse(id, { titles: titles }, era);
}

// --- Stream handler for newline-delimited JSON-RPC ---

var MAX_BUFFER_SIZE = 100 * 1024 * 1024; // 100MB — generous limit for base64 uploads

/**
 * Reads newline-delimited messages from a stream and dispatches each.
 * @param {object} input - readable stream
 * @param {function(string): void} send - writes a line
 * @param {function(): void} [onClose] - called when the stream ends
 * @param {function(string, function): void} [customDispatch] - replaces dispatchMessage
 * @returns {void}
 */
function attachStreamHandler(input, send, onClose, customDispatch) {
	var dispatch = customDispatch || function(line, sendFn) { dispatchMessage(line, sendFn); };
	var buffer = "";
	input.setEncoding("utf8");
	input.on("data", function(chunk) {
		buffer += chunk;
		if(buffer.length > MAX_BUFFER_SIZE) {
			log("Buffer overflow — message exceeds " + (MAX_BUFFER_SIZE / 1024 / 1024) + "MB, dropping connection");
			buffer = "";
			input.destroy();
			return;
		}
		var lines = buffer.split("\n");
		buffer = lines.pop();
		for(var i = 0; i < lines.length; i++) {
			var line = lines[i].trim();
			if(line) {
				dispatch(line, send);
			}
		}
	});
	input.on("end", function() {
		if(onClose) {
			onClose();
		}
	});
}

// --- Named pipe transport ---

/**
 * The wiki path the pipe and discovery file are named after: the first includeWikis entry, so editions sharing a wiki converge.
 * @returns {(string|null)} Path
 */
function getCanonicalWikiPath() {
	if(!$tw.boot.wikiPath) {
		return null;
	}
	// Resolved, or every wiki started as `.` would share one pipe name.
	var wikiPath = path.resolve($tw.boot.wikiPath);
	var includeWikis = ($tw.boot.wikiInfo && $tw.boot.wikiInfo.includeWikis) || [];
	if(includeWikis.length > 0) {
		var first = includeWikis[0];
		return path.resolve(wikiPath, typeof first === "string" ? first : first.path);
	}
	return wikiPath;
}

/**
 * The pipe path of this wiki: a named pipe on Windows, a socket in the wiki folder elsewhere.
 * @returns {string} Pipe path
 */
function getPipePath() {
	var canonical = getCanonicalWikiPath() || "default";
	if(process.platform === "win32") {
		// Windows named pipe — use wiki path hash for uniqueness
		var wikiId = canonical.replace(/[^a-zA-Z0-9]/g, "-");
		return "\\\\.\\pipe\\tiddlywiki-mcp-" + wikiId;
	} else {
		// Unix domain socket in the canonical wiki directory
		return path.resolve(canonical, ".mcp.sock");
	}
}

/**
 * Tells whether a process id is alive.
 * @param {number} pid - process id
 * @returns {boolean} True if running
 */
function isProcessRunning(pid) {
	try {
		process.kill(pid, 0);
		return true;
	} catch(e) {
		return false;
	}
}

/**
 * Removes a discovery file whose process is gone.
 * @returns {void}
 */
function cleanStaleDiscoveryFile() {
	var canonical = getCanonicalWikiPath();
	if(!canonical) {
		return;
	}
	var discoveryFile = path.resolve(canonical, ".tw-mcp", "connect");
	try {
		var raw = fs.readFileSync(discoveryFile, "utf8");
		var data = JSON.parse(raw);
		if(data.pid && !isProcessRunning(data.pid)) {
			log("Removing stale .tw-mcp/connect (PID " + data.pid + " is no longer running)");
			fs.unlinkSync(discoveryFile);
		}
	} catch(e) {
		// Ignore — file doesn't exist or is unreadable
	}
}

/**
 * The discovery file of a wiki folder when its process is alive.
 * @param {string} wikiPath - wiki folder
 * @returns {(object|null)} Discovery data
 */
function tryReadDiscovery(wikiPath) {
	var discoveryFile = path.resolve(wikiPath, ".tw-mcp", "connect");
	try {
		var raw = fs.readFileSync(discoveryFile, "utf8");
		var data = JSON.parse(raw);
		if(data.pid && data.pipe && data.token && isProcessRunning(data.pid)) {
			return data;
		}
	} catch(e) {
		// File doesn't exist or is unreadable
	}
	return null;
}

/**
 * The live discovery file of this wiki, from the canonical path first, then the wiki's own folder.
 * @returns {(object|null)} Discovery data
 */
function readDiscoveryFile() {
	if(!$tw.boot.wikiPath) {
		return null;
	}
	// includeWikis path takes precedence (shared editions converge here)
	var canonical = getCanonicalWikiPath();
	if(canonical !== $tw.boot.wikiPath) {
		var result = tryReadDiscovery(canonical);
		if(result) {
			return result;
		}
	}
	// Fall back to own wiki directory
	return tryReadDiscovery($tw.boot.wikiPath);
}

/**
 * Checks whether another server owns the pipe, removing a stale Unix socket.
 * @param {string} pipePath - pipe path
 * @param {function((Error|null)): void} callback - receives an error when the pipe is taken
 * @returns {void}
 */
function probeAndCleanPipe(pipePath, callback) {
	// Clean up stale discovery files left by hard-killed processes
	cleanStaleDiscoveryFile();
	// Try connecting to the pipe to see if another server is alive.
	// callback(err) — err is null if the pipe is available, or an Error if another server owns it.
	var probe = net.createConnection(pipePath, function() {
		// Connection succeeded — another server is alive
		probe.destroy();
		callback(new Error("Another MCP server is already listening on " + pipePath));
	});
	probe.on("error", function(err) {
		// Connection failed — pipe is stale or doesn't exist
		if(process.platform !== "win32") {
			// On Unix, remove the stale socket file
			try {
				fs.unlinkSync(pipePath);
			} catch(e) {
				// Ignore — file doesn't exist
			}
		}
		callback(null);
	});
	// Short timeout so startup isn't delayed
	probe.setTimeout(1000, function() {
		probe.destroy();
		callback(null);
	});
}

/**
 * Sends a message to every pipe client.
 * @param {string} message - line
 * @returns {void}
 */
function broadcastToClients(message) {
	var ids = Object.keys(pipeClients);
	for(var i = 0; i < ids.length; i++) {
		var client = pipeClients[ids[i]];
		client.send(message);
	}
}

/**
 * Starts the pipe server and writes the discovery file once it listens.
 * @returns {object} The net server
 */
function startPipeServer() {
	var pipePath = getPipePath();

	var pipeServer = net.createServer(function(socket) {
		var clientId = "pipe-" + Date.now();
		var clientSuffix = ""; // will be set to " @<label>[role]" after auth

		var send = function(msg) {
			if(!socket.destroyed) {
				socket.write(msg + "\n");
			}
		};

		// Statelessness removes the one initialize that used to carry the token,
		// so EVERY message must present it. The registry is keyed to the socket,
		// which is still a real connection even though the protocol above it is
		// not: identity is recorded from the first message that authenticates.
		var authenticated = false;
		var authenticatedDispatch = function(line, sendFn) {
			var parsed;
			try {
				parsed = JSON.parse(line);
			} catch(e) {
				sendFn(jsonrpcError(null, -32700, "Parse error"));
				return;
			}
			var meta = getMeta(parsed);
			var replyId = (parsed.id === undefined) ? null : parsed.id;
			var clientToken = meta[TW_AUTH];
			if(!clientToken || typeof clientToken !== "string") {
				sendFn(jsonrpcError(replyId, -32600, "Authentication failed: missing " + TW_AUTH + " in _meta"));
				socket.destroy();
				return;
			}
			// Constant-time comparison to prevent timing attacks
			var tokenBuf = Buffer.from(authToken, "utf8");
			var clientBuf = Buffer.from(clientToken, "utf8");
			if(tokenBuf.length !== clientBuf.length || !crypto.timingSafeEqual(tokenBuf, clientBuf)) {
				sendFn(jsonrpcError(replyId, -32600, "Authentication failed: invalid token"));
				log("Auth failed for client " + clientId + " — invalid token" + clientSuffix);
				socket.destroy();
				return;
			}
			if(!authenticated) {
				authenticated = true;
				// Append PID to clientId, keep label/role separate so they're always last
				var clientPid = meta[TW_PID];
				var clientLabel = meta[TW_LABEL];
				var clientRole = meta[TW_ROLE];
				if(clientPid) {
					clientId = clientId + " (PID " + clientPid + ")";
				}
				if(clientLabel) {
					clientSuffix = " @" + clientLabel;
				}
				if(clientRole) {
					clientSuffix = clientSuffix + " [" + clientRole + "]";
				}
				log("Client ready: " + clientId + clientSuffix + " (protocol " + PROTOCOL_VERSION + ", " + fmtMode() + ")");
				// Register in client registry for broadcast
				pipeClients[clientId] = { send: sendFn, socket: socket };
				// Suppress the redundant per-client discovery log — the line above already covers it
				suppressNextInitLog = true;
			}
			if(handlePipeNotification(clientId, parsed)) {
				// An LSP process sends no discovery, so nothing is left to suppress.
				suppressNextInitLog = false;
				return;
			}
			dispatchMessage(line, sendFn);
		};

		attachStreamHandler(socket, send, function() {
			delete pipeClients[clientId];
			forgetPipeClient(clientId);
			log("Client gone: " + clientId + clientSuffix);
		}, authenticatedDispatch);

		socket.on("error", function(err) {
			delete pipeClients[clientId];
			forgetPipeClient(clientId);
			log("Client error: " + clientId + clientSuffix + " — " + err.message);
		});
	});

	pipeServer.on("error", function(err) {
		if(err.code === "EADDRINUSE") {
			log("Pipe already in use: " + fmtPipe(pipePath) + " — another MCP server may be running for this wiki");
		} else {
			log("Pipe server error: " + err.message);
		}
	});

	// Cleanup: close pipe server and remove discovery file if we created it (PID check)
	var canonical = getCanonicalWikiPath();
	function cleanup() {
		pipeServer.close();
		if(canonical) {
			var cleanupFile = path.resolve(canonical, ".tw-mcp", "connect");
			try {
				var raw = fs.readFileSync(cleanupFile, "utf8");
				var data = JSON.parse(raw);
				if(data.pid === process.pid) {
					fs.unlinkSync(cleanupFile);
				}
			} catch(e) {
				// Ignore — file doesn't exist or is unreadable
			}
		}
		if(process.platform !== "win32") {
			try {
				fs.unlinkSync(pipePath);
			} catch(e) {
				// Ignore
			}
		}
	}
	process.on("exit", cleanup);
	process.on("SIGINT", function() { cleanup(); process.exit(0); });
	process.on("SIGTERM", function() { cleanup(); process.exit(0); });

	// Probe the pipe before listening — detect if another server already owns it
	probeAndCleanPipe(pipePath, function(probeErr) {
		if(probeErr) {
			log(probeErr.message);
			log("Pipe transport disabled — stdio transport is still active");
			return;
		}
		pipeServer.listen(pipePath, function() {
			log("Pipe server listening: " + fmtPipe(pipePath));
			// Restrict socket permissions on Unix to owner only
			if(process.platform !== "win32") {
				try {
					fs.chmodSync(pipePath, 0o600);
				} catch(e) {
					log("Warning: could not restrict socket permissions: " + e.message);
				}
			}
			// Write discovery file to the canonical wiki path so all editions converge
			var writePrimaryDiscovery = function() {
				writeDiscoveryFile({ pipe: pipePath, token: authToken, pid: process.pid, label: serverLabel || undefined, listen: !!$tw.httpServer, port: listeningPort(), host: browserHost() });
			};
			writePrimaryDiscovery();
			// The editor's LSP process links to the browser through this port, which exists only once HTTP listens.
			if($tw.httpServer && !listeningPort()) {
				$tw.httpServer.nodeServer.once("listening", writePrimaryDiscovery);
			}
		});
	});

	return pipeServer;
}

/**
 * Records an editor LSP process's hello, so get_wiki_info can list it.
 * @param {string} clientId - pipe client
 * @param {object} parsed - JSON-RPC message
 * @returns {boolean} True when the message was that hello
 */
function handlePipeNotification(clientId, parsed) {
	if(parsed.method !== LSP_HELLO_METHOD) {
		return false;
	}
	var info = Object.assign({}, parsed.params);
	delete info._meta;
	if(!lspClients[clientId]) {
		log("LSP client: " + describeLspClient(info));
	}
	lspClients[clientId] = info;
	return true;
}

/**
 * Drops a pipe client that disconnected.
 * @param {string} clientId - pipe client
 * @returns {void}
 */
function forgetPipeClient(clientId) {
	if(lspClients[clientId]) {
		log("LSP client gone: " + describeLspClient(lspClients[clientId]));
		delete lspClients[clientId];
	}
}

/**
 * An LSP client for get_wiki_info.
 * @param {object} info - hello data
 * @returns {string} Description
 */
function describeLspClient(info) {
	return (info.client || "an editor") + " (PID " + info.pid + ", " + (info.transport || "pipe") + ")" + (info.label ? " @" + info.label : "") + (info.wiki ? " on " + info.wiki : "");
}

/**
 * The LSP processes linked to this server.
 * @returns {object[]} Clients
 */
function listLspClients() {
	return Object.keys(lspClients).map(function(clientId) {
		return lspClients[clientId];
	});
}

/**
 * The port this process's HTTP server listens on.
 * @returns {(number|undefined)} Port
 */
function listeningPort() {
	var address = $tw.httpServer && $tw.httpServer.nodeServer && $tw.httpServer.nodeServer.address();
	return address && address.port ? address.port : undefined;
}

/**
 * The host a browser opens this process's HTTP server at: a host= name as given, else the address it is bound to.
 * @returns {(string|undefined)} Host, bracketed when it is an IPv6 address
 */
function browserHost() {
	var http = $tw.httpServer,
		address = http && http.nodeServer && http.nodeServer.address(),
		WILDCARDS = ["0.0.0.0", "::"];
	if(!address || !address.address) {
		return undefined;
	}
	var host = http.server.get("host");
	// localhost resolves to whichever address it was bound to; using that spares the browser trying the other one first.
	if(!host || host === "localhost" || WILDCARDS.includes(host)) {
		host = WILDCARDS.includes(address.address) ? "127.0.0.1" : address.address;
	}
	return host.includes(":") && host.charAt(0) !== "[" ? "[" + host + "]" : host;
}

// --- Takeover: primary steps down, new primary takes over ---

/**
 * Writes the discovery file to the canonical wiki path.
 * @param {object} data - discovery data
 * @returns {void}
 */
function writeDiscoveryFile(data) {
	var canonical = getCanonicalWikiPath();
	if(!canonical) {
		return;
	}
	var mcpDir = path.resolve(canonical, ".tw-mcp");
	var discoveryFile = path.resolve(mcpDir, "connect");
	try {
		$tw.utils.createDirectory(mcpDir);
		fs.writeFileSync(discoveryFile, JSON.stringify(data), { encoding: "utf8", mode: 0o600 });
	} catch(e) {
		log("Warning: could not write .tw-mcp/connect discovery file: " + e.message);
	}
}

/**
 * Steps down for a proxy that serves HTTP and asks to become primary.
 * @param {object} params - the new primary's pid and label
 * @returns {void}
 */
function handleTakeoverRequest(params) {
	if(takeoverInProgress) {
		log("Takeover already in progress, ignoring request from PID " + params.pid);
		return;
	}
	if(!params || !params.pid) {
		log("Invalid takeover-request: missing params");
		return;
	}
	takeoverInProgress = true;
	log("Takeover requested by PID " + params.pid + (params.label ? " @" + params.label : ""));

	// Broadcast takeover notification to all pipe clients so they know to reconnect
	var notification = JSON.stringify({
		jsonrpc: "2.0",
		method: "notifications/takeover",
		params: { pid: params.pid, label: params.label }
	});
	broadcastToClients(notification);

	// Remove discovery file so the new primary can write its own
	var canonical = getCanonicalWikiPath();
	if(canonical) {
		try {
			fs.unlinkSync(path.resolve(canonical, ".tw-mcp", "connect"));
		} catch(e) {
			// Ignore
		}
	}

	// Close our pipe server after a short delay to flush broadcasts.
	// The new primary will start its pipe server on the now-free path.
	// Then we'll read its discovery file and connect as proxy.
	setTimeout(function() {
		// Destroy all client sockets so proxies detect the disconnect
		var ids = Object.keys(pipeClients);
		for(var i = 0; i < ids.length; i++) {
			var client = pipeClients[ids[i]];
			if(client.socket && !client.socket.destroyed) {
				client.socket.destroy();
			}
		}
		pipeClients = {};
		if(currentPipeServer) {
			currentPipeServer.close();
			currentPipeServer = null;
		}

		// Wait for new primary to write its discovery file, then connect as proxy
		waitForNewPrimary(params.pid);
	}, 100);
}

/**
 * Waits for the new primary's discovery file, then turns this process into its proxy.
 * @param {number} expectedPid - new primary's pid
 * @returns {void}
 */
function waitForNewPrimary(expectedPid) {
	var attempts = 0;
	var maxAttempts = 30; // 3 seconds max
	function check() {
		attempts++;
		var discovery = readDiscoveryFile();
		if(discovery && discovery.pid === expectedPid) {
			log("New primary discovered (PID " + discovery.pid + "), connecting as proxy");
			transitionToProxy(discovery);
			return;
		}
		if(attempts < maxAttempts) {
			setTimeout(check, 100);
		} else {
			log("Timed out waiting for new primary (PID " + expectedPid + "), staying as primary");
			takeoverInProgress = false;
			// Re-start pipe server since we closed ours
			currentPipeServer = startPipeServer();
			$tw.mcp.role = "primary";
		}
	}
	check();
}

// stdinRelay: swappable function ref for stdin dispatch — set by startAsPrimary,
// swapped by transitionToProxy to relay mode
var stdinRelay = null;

/**
 * Turns a former primary into a proxy of the new one.
 * @param {object} newPrimary - discovery data
 * @returns {void}
 */
function transitionToProxy(newPrimary) {
	log("Stepping down to PROXY → new primary (PID " + newPrimary.pid + ") at " + fmtPipe(newPrimary.pipe) + (newPrimary.label ? " @" + newPrimary.label : ""));
	$tw.mcp.role = "proxy";
	takeoverInProgress = false;

	// Connect to new primary's pipe
	var proxySocket = net.createConnection(newPrimary.pipe, function() {
		log("Transition: connected to new primary");
		// There is no handshake to authenticate with, so the message that
		// registers us with the new primary is an ordinary server/discover
		// carrying auth. The former-primary role marks us as the one stepping
		// down rather than a freshly started proxy.
		var initMsg = injectAuth(JSON.stringify({
			jsonrpc: "2.0",
			id: "transition-init",
			method: "server/discover",
			params: buildRequestMeta()
		}), newPrimary.token, serverLabel, "former-primary");
		proxySocket.write(initMsg + "\n");
		// Flush any pending stdin lines
		for(var i = 0; i < pendingRelay.length; i++) {
			proxySocket.write(pendingRelay[i] + "\n");
		}
		pendingRelay = [];
		proxyConnected = true;
	});

	proxySocket.setEncoding("utf8");
	var proxyConnected = false;
	var pendingRelay = [];
	var proxyBuffer = "";

	// Relay: new primary pipe → stdout
	proxySocket.on("data", function(chunk) {
		proxyBuffer += chunk;
		var lines = proxyBuffer.split("\n");
		proxyBuffer = lines.pop();
		for(var i = 0; i < lines.length; i++) {
			var line = lines[i].trim();
			if(line) {
				// Suppress the initialize response we sent for auth
				try {
					var msg = JSON.parse(line);
					if(msg.id === "transition-init") {
						continue;
					}
				} catch(e) {
					// pass through
				}
				process.stdout.write(line + "\n");
			}
		}
	});

	proxySocket.on("error", function(err) {
		log("Transition proxy: pipe error — " + err.message);
	});

	proxySocket.on("end", function() {
		log("Transition proxy: new primary disconnected, exiting");
		process.exit(1);
	});

	// Swap stdin dispatch to relay mode
	stdinRelay = function(line) {
		var modified = injectAuth(line, newPrimary.token, serverLabel);
		if(proxyConnected && proxySocket && !proxySocket.destroyed) {
			proxySocket.write(modified + "\n");
		} else {
			pendingRelay.push(modified);
		}
	};
}

// --- Proxy mode helpers ---

/**
 * Stamps the token on a relayed message, since the primary checks it on every request.
 * @param {string} line - JSON-RPC line
 * @param {string} token - pipe token
 * @param {string} [label] - this process's label
 * @param {string} [role] - pipe role
 * @returns {string} Line
 */
function injectAuth(line, token, label, role) {
	var msg = parseJsonRpc(line);
	if(!msg) {
		return line; // not valid JSON, let the primary reject it
	}
	msg.params = msg.params || {};
	msg.params._meta = msg.params._meta || {};
	msg.params._meta[TW_AUTH] = token;
	msg.params._meta[TW_PID] = process.pid;
	if(label) {
		msg.params._meta[TW_LABEL] = label;
	}
	if(role) {
		msg.params._meta[TW_ROLE] = role;
	}
	return JSON.stringify(msg);
}

/**
 * What the proxy does with a client message: which answer to track, whether to block it, and the refusal.
 * @param {object} msg - JSON-RPC message
 * @param {object} options - readonly and writeToolNames
 * @returns {{track: (string|null), block: boolean, response: (string|null)}} Decision
 */
function classifyOutbound(msg, options) {
	var nothing = { track: null, block: false, response: null };
	if(!msg || msg.id === undefined) {
		return nothing; // unparseable, or a notification nobody answers
	}
	if(msg.method === "server/discover") {
		return { track: "discover", block: false, response: null };
	}
	if(msg.method === "initialize") {
		return { track: "initialize", block: false, response: null };
	}
	if(!options.readonly) {
		return nothing;
	}
	if(msg.method === "tools/list") {
		return { track: "toolsList", block: false, response: null };
	}
	if(msg.method === "tools/call") {
		var toolName = msg.params && msg.params.name;
		if(toolName && options.writeToolNames[toolName]) {
			// The refusal is ours, not the primary's, so it must be shaped for
			// whichever era the client is speaking.
			return {
				track: null,
				block: true,
				response: jsonrpcResponse(msg.id, {
					isError: true,
					content: [{ type: "text", text: "Tool '" + toolName + "' is disabled in readonly mode" }]
				}, eraOfMessage(msg))
			};
		}
	}
	return nothing;
}

/**
 * Relays stdio to a running primary over its pipe.
 * @param {object} discovery - primary's discovery data
 * @returns {void}
 */
function startProxyMode(discovery) {
	var pipePath = discovery.pipe;
	var token = discovery.token;
	var pipeSocket = null;
	var connected = false;
	var pendingStdio = [];
	var discoverId = null;
	var initializeId = null; // handshake-era counterpart of discoverId
	var toolsListIds = {}; // track tools/list request ids for readonly filtering
	// Build write tool name set for readonly enforcement (discovered from
	// the handler definitions' write flag)
	var writeToolNames = handlers.getWriteToolNames();

	var takingOver = false; // true when we received a takeover notification (other proxies)
	var initiatedTakeover = false; // true when WE requested the takeover
	var takeoverStartedAt = 0; // ms timestamp for elapsed-time reporting
	var currentPrimaryPid = discovery.pid;

	$tw.mcp.role = "proxy";
	log("Server started as PROXY (PID " + process.pid + ", " + fmtMode() + ") → primary (PID " + discovery.pid + ") at " + fmtPipe(pipePath) + (serverLabel ? " @" + serverLabel : ""));

	// A relayed answer comes from the primary, not from us — say so, so the
	// client's logs name the process that actually holds the wiki.
	function annotateProxyOrigin(info) {
		info.proxy = true;
		info.primaryPid = discovery.pid;
		info.primaryLabel = discovery.label || null;
	}

	// --- Pipe connection to primary ---
	var proxyAuthenticated = false; // true after our self-init is ack'd
	var selfInitId = "proxy-init-" + Date.now();

	pipeSocket = net.createConnection(pipePath, function() {
		connected = true;
		log("Proxy: connected to primary");
		// Our own server/discover both authenticates us with the primary's pipe
		// and confirms it is alive, which is what the self-init used to do.
		var selfInit = injectAuth(JSON.stringify({
			jsonrpc: "2.0",
			id: selfInitId,
			method: "server/discover",
			params: buildRequestMeta()
		}), token, serverLabel);
		pipeSocket.write(selfInit + "\n");
		// Flush buffered client messages (the client's own discover is a second one — harmless)
		for(var i = 0; i < pendingStdio.length; i++) {
			pipeSocket.write(pendingStdio[i] + "\n");
		}
		pendingStdio = [];
	});

	pipeSocket.setEncoding("utf8");

	// Relay: pipe -> stdout
	var pipeBuffer = "";
	pipeSocket.on("data", function(chunk) {
		pipeBuffer += chunk;
		var lines = pipeBuffer.split("\n");
		pipeBuffer = lines.pop();
		for(var i = 0; i < lines.length; i++) {
			var line = lines[i].trim();
			if(line) {
				// Intercept takeover notification
				try {
					var notification = JSON.parse(line);
					if(notification.method === "notifications/takeover" && notification.params) {
						if(notification.params.pid === process.pid) {
							// We initiated this takeover — ignore our own notification
							continue;
						}
						takingOver = true;
						log("Proxy: takeover notification — new primary is PID " + notification.params.pid + (notification.params.label ? " @" + notification.params.label : ""));
						// Don't reconnect yet — wait for pipe disconnect + new discovery file
						continue; // don't forward to client
					}
				} catch(e) {
					// Not valid JSON — pass through
				}
				// Suppress our self-init response and trigger takeover if applicable
				if(!proxyAuthenticated) {
					try {
						var selfResp = JSON.parse(line);
						if(selfResp.id === selfInitId) {
							proxyAuthenticated = true;
							log("Proxy: authenticated with primary");
							if($tw.httpServer && !takingOver) {
								setTimeout(initiateTakeover, 0);
							}
							continue; // don't forward self-init response to client
						}
					} catch(e) {}
				}
				// Intercept responses that need proxy-side modification
				if(discoverId !== null || initializeId !== null || (readonlyMode && Object.keys(toolsListIds).length > 0)) {
					try {
						var resp = JSON.parse(line);
						if(resp.id !== undefined) {
							// Annotate the discover response with proxy info. Under
							// 2026-07-28 serverInfo lives in _meta, because there is no
							// handshake result to carry it.
							if(resp.id === discoverId && resp.result && resp.result._meta && resp.result._meta[META_SERVER_INFO]) {
								annotateProxyOrigin(resp.result._meta[META_SERVER_INFO]);
								discoverId = null;
								line = JSON.stringify(resp);
							}
							// Same annotation for the handshake era, where the client
							// learns who answered from the initialize result instead.
							if(resp.id === initializeId && resp.result && resp.result.serverInfo) {
								annotateProxyOrigin(resp.result.serverInfo);
								initializeId = null;
								line = JSON.stringify(resp);
							}
							// Filter write tools from tools/list response when proxy is readonly
							if(readonlyMode && toolsListIds[resp.id] && resp.result && resp.result.tools) {
								resp.result.tools = resp.result.tools.filter(function(t) {
									return !writeToolNames[t.name];
								});
								delete toolsListIds[resp.id];
								line = JSON.stringify(resp);
							}
						}
					} catch(e) {
						// Not valid JSON — pass through
					}
				}
				process.stdout.write(line + "\n");
			}
		}
	});

	pipeSocket.on("error", function(err) {
		log("Proxy: pipe error — " + err.message);
		handlePrimaryDisconnect();
	});

	pipeSocket.on("end", function() {
		log("Proxy: primary disconnected" + (initiatedTakeover ? " (stepping up)" : ""));
		handlePrimaryDisconnect();
	});

	function handlePrimaryDisconnect() {
		connected = false;
		pipeSocket = null;
		if(initiatedTakeover) {
			becomePrimary();
			return;
		}
		if(takingOver) {
			// We received a takeover notification — wait for new discovery file
			waitForNewDiscovery();
			return;
		}
		// Check if a new primary appeared (e.g. takeover we missed)
		var newDiscovery = readDiscoveryFile();
		if(newDiscovery && newDiscovery.pid !== currentPrimaryPid) {
			log("Proxy: primary changed, reconnecting to new primary (PID " + newDiscovery.pid + ")");
			reconnectToNewPrimary(newDiscovery);
			return;
		}
		log("Proxy: primary is gone, exiting");
		process.exit(1);
	}

	function reconnectToNewPrimary(params) {
		// Disconnect from old primary
		if(pipeSocket && !pipeSocket.destroyed) {
			pipeSocket.destroy();
		}
		pipePath = params.pipe;
		token = params.token;
		currentPrimaryPid = params.pid;
		connected = false;
		takingOver = false;

		// Connect to new primary
		pipeSocket = net.createConnection(params.pipe, function() {
			connected = true;
			log("Proxy: reconnected to new primary (PID " + params.pid + ")");
			// Flush any pending messages. They were stamped with the previous
			// primary's token, which this one would reject, so re-stamp them.
			for(var i = 0; i < pendingStdio.length; i++) {
				pipeSocket.write(injectAuth(pendingStdio[i], params.token, serverLabel) + "\n");
			}
			pendingStdio = [];
		});

		pipeSocket.setEncoding("utf8");

		// Re-wire pipe data relay (reuse existing pipeBuffer)
		pipeBuffer = "";
		pipeSocket.on("data", function(chunk) {
			pipeBuffer += chunk;
			var lines = pipeBuffer.split("\n");
			pipeBuffer = lines.pop();
			for(var i = 0; i < lines.length; i++) {
				var line = lines[i].trim();
				if(line) {
					// Check for further takeover
					try {
						var notification = JSON.parse(line);
						if(notification.method === "notifications/takeover" && notification.params) {
							takingOver = true;
							log("Proxy: takeover notification — reconnecting to new primary (PID " + notification.params.pid + ")");
							reconnectToNewPrimary(notification.params);
							return;
						}
					} catch(e) {}
					process.stdout.write(line + "\n");
				}
			}
		});

		pipeSocket.on("error", function(err) {
			log("Proxy: pipe error — " + err.message);
			handlePrimaryDisconnect();
		});

		pipeSocket.on("end", function() {
			log("Proxy: primary disconnected");
			handlePrimaryDisconnect();
		});

		// Re-authenticate with the new primary the same way: a plain
		// server/discover carrying the new primary's token.
		var initMsg = injectAuth(JSON.stringify({
			jsonrpc: "2.0",
			id: "reconnect-init-" + Date.now(),
			method: "server/discover",
			params: buildRequestMeta()
		}), params.token, serverLabel);

		if(connected) {
			pipeSocket.write(initMsg + "\n");
		} else {
			pendingStdio.push(initMsg);
		}
	}

	// --- Takeover initiation (when this proxy also runs --listen) ---

	function waitForNewDiscovery() {
		var attempts = 0;
		var maxAttempts = 30;
		function check() {
			attempts++;
			var newDiscovery = readDiscoveryFile();
			if(newDiscovery && newDiscovery.pid !== currentPrimaryPid) {
				log("Proxy: new primary found (PID " + newDiscovery.pid + "), reconnecting");
				reconnectToNewPrimary(newDiscovery);
				return;
			}
			if(attempts < maxAttempts) {
				setTimeout(check, 100);
			} else {
				log("Proxy: timed out waiting for new primary, exiting");
				process.exit(1);
			}
		}
		check();
	}

	function initiateTakeover() {
		initiatedTakeover = true;
		takeoverStartedAt = Date.now();
		log("── Takeover initiated ──");
		log("   reason: --listen (HTTP server) detected in this process");
		log("   old primary: PID " + currentPrimaryPid);
		log("   new primary: PID " + process.pid + (serverLabel ? " @" + serverLabel : ""));

		// Send takeover request to current primary. It needs the token like any
		// other message now — an unauthenticated one gets the socket destroyed.
		var request = injectAuth(JSON.stringify({
			jsonrpc: "2.0",
			method: "notifications/takeover-request",
			params: {
				pid: process.pid,
				label: serverLabel
			}
		}), token, serverLabel);
		if(connected && pipeSocket && !pipeSocket.destroyed) {
			pipeSocket.write(request + "\n");
		}
	}

	// Called when pipe disconnects during takeover — old primary has stepped down
	function becomePrimary() {
		log("Old primary stepped down, becoming PRIMARY");
		// Generate auth token and init handlers
		authToken = crypto.randomBytes(32).toString("hex");
		if(!allowedPaths && $tw.boot.wikiPath) {
			var canonical = getCanonicalWikiPath() || $tw.boot.wikiPath;
			allowedPaths = [
				$tw.boot.wikiTiddlersPath || path.resolve(canonical, "tiddlers"),
				path.resolve(canonical, "files"),
				path.resolve(canonical, "output"),
				path.resolve($tw.boot.wikiPath, "tiddlers"),
				path.resolve($tw.boot.wikiPath, "files"),
				path.resolve($tw.boot.wikiPath, "output")
			];
		}
		handlers.init({
			readonlyMode: readonlyMode,
			checkPathAllowed: checkPathAllowed
		});

		// Start pipe server on the now-free path
		currentPipeServer = startPipeServer();

		// Swap stdin from relay to dispatch mode
		proxyStdinHandler = function(line) {
			dispatchMessage(line, stdioSend);
		};
		$tw.mcp.role = "primary";
		log("Server started as PRIMARY (PID " + process.pid + ")" + (serverLabel ? " @" + serverLabel : ""));
		var elapsed = Date.now() - takeoverStartedAt;
		log("── Takeover complete (" + elapsed + "ms) ──");
	}

	// --- Relay: stdin -> pipe (swappable via proxyStdinHandler for takeover) ---
	var proxyStdinHandler = relayToPrimary;
	var stdioSend = function(msg) {
		process.stdout.write(msg + "\n");
	};
	var stdioBuffer = "";
	process.stdin.setEncoding("utf8");
	process.stdin.on("data", function(chunk) {
		stdioBuffer += chunk;
		var lines = stdioBuffer.split("\n");
		stdioBuffer = lines.pop();
		for(var i = 0; i < lines.length; i++) {
			var line = lines[i].trim();
			if(line) {
				proxyStdinHandler(line);
			}
		}
	});
	process.stdin.on("end", function() {
		log("stdin closed, shutting down");
		if(pipeSocket && !pipeSocket.destroyed) {
			pipeSocket.destroy();
		}
		process.exit(0);
	});

	function relayToPrimary(line) {
		var modified = injectAuth(line, token, serverLabel);
		// This runs OUTSIDE any catch on purpose: classifyOutbound decides
		// whether a write call reaches the primary, and the early return below
		// is the only thing that stops it. Swallowing a throw from here would
		// forward the very call we just refused.
		var msg = parseJsonRpc(line);
		var decision = classifyOutbound(msg, { readonly: readonlyMode, writeToolNames: writeToolNames });
		if(decision.track === "discover") {
			discoverId = msg.id;
		} else if(decision.track === "initialize") {
			initializeId = msg.id;
		} else if(decision.track === "toolsList") {
			toolsListIds[msg.id] = true;
		}
		if(decision.block) {
			process.stdout.write(decision.response + "\n");
			return; // don't forward to primary
		}
		if(connected && pipeSocket && !pipeSocket.destroyed) {
			pipeSocket.write(modified + "\n");
		} else {
			pendingStdio.push(modified);
		}
	}
}

// --- MCP Server entry point ---

/**
 * Serves the wiki on stdio and the pipe.
 * @param {object} options - server options
 * @returns {void}
 */
function startAsPrimary(options) {
	// Generate auth token for pipe transport (256-bit random hex)
	authToken = crypto.randomBytes(32).toString("hex");
	// Default allowed paths: wiki's tiddlers/, files/, and output/ subdirectories
	if(options.allowedPaths) {
		allowedPaths = options.allowedPaths;
	} else if($tw.boot.wikiPath) {
		var canonical = getCanonicalWikiPath() || $tw.boot.wikiPath;
		var pathSet = {};
		var paths = [
			$tw.boot.wikiTiddlersPath || path.resolve(canonical, "tiddlers"),
			path.resolve(canonical, "files"),
			path.resolve(canonical, "output"),
			path.resolve($tw.boot.wikiPath, "tiddlers"),
			path.resolve($tw.boot.wikiPath, "files"),
			path.resolve($tw.boot.wikiPath, "output")
		];
		allowedPaths = [];
		for(var pi = 0; pi < paths.length; pi++) {
			var resolved = path.resolve(paths[pi]);
			if(!pathSet[resolved]) {
				pathSet[resolved] = true;
				allowedPaths.push(resolved);
			}
		}
	} else {
		allowedPaths = null;
	}

	// Initialize handlers with shared state
	handlers.init({
		readonlyMode: readonlyMode,
		checkPathAllowed: checkPathAllowed
	});

	// stdio transport — uses stdinRelay indirection so transitionToProxy can swap to relay mode
	var stdioSend = function(msg) {
		process.stdout.write(msg + "\n");
	};
	stdinRelay = null; // reset; when null, dispatch normally
	attachStreamHandler(process.stdin, stdioSend, function() {
		log("stdin closed, shutting down");
		process.exit(0);
	}, function(line, sendFn) {
		if(stdinRelay) {
			stdinRelay(line);
		} else {
			dispatchMessage(line, sendFn);
		}
	});

	// Named pipe transport
	currentPipeServer = startPipeServer();

	$tw.mcp.role = "primary";
	log("Server started as PRIMARY (v" + getServerVersion() + ", PID " + process.pid + ", protocol " + PROTOCOL_VERSION + " +legacy, " + fmtMode() + ", filesystem: " + !!$tw.syncadaptor + ")" + (serverLabel ? " @" + serverLabel : ""));
	if(allowedPaths) {
		log("Allowed paths:\n  - " + allowedPaths.join("\n  - "));
	}
}

/**
 * A tag naming the workspace of an IDE-spawned process, so instances from different windows are told apart.
 * @returns {(string|null)} Tag
 */
function deriveIDEWorkspaceTag() {
	var env = process.env;
	var fromIDE = !!(env.VSCODE_PID || env.VSCODE_IPC_HOOK || env.TERM_PROGRAM === "vscode" || env.CLAUDECODE || env.CLAUDE_CODE_ENTRYPOINT);
	if(!fromIDE) {
		return null;
	}
	var tag = path.basename(process.cwd());
	var wikiPath = $tw && $tw.boot && $tw.boot.wikiPath;
	if(wikiPath) {
		var wikiBase = path.basename(path.resolve(wikiPath));
		if(wikiBase && wikiBase !== tag) {
			tag = tag + "/" + wikiBase;
		}
	}
	return tag || null;
}

/**
 * Starts as primary, or as proxy when a primary already runs.
 * @param {object} options - server options
 * @returns {void}
 */
function startMCPServer(options) {
	options = options || {};
	readonlyMode = !!options.readonly;
	serverLabel = options.label || null;
	var ideTag = deriveIDEWorkspaceTag();
	if(ideTag) {
		serverLabel = serverLabel ? (serverLabel + ":" + ideTag) : ideTag;
	}

	// Expose MCP state on $tw so other commands (e.g. --listen) can discover it
	$tw.mcp = {
		pid: process.pid,
		label: serverLabel,
		role: null,
		readonly: readonlyMode,
		version: getServerVersion(),
		started: Date.now(),
		lspClients: listLspClients,
		heartbeat: function() {
			return {
				pid: process.pid,
				role: $tw.mcp.role,
				label: $tw.mcp.label,
				version: getServerVersion(),
				uptime: Date.now() - $tw.mcp.started,
				readonly: $tw.mcp.readonly
			};
		}
	};

	// Check for an existing primary server via the discovery file
	var discovery = readDiscoveryFile();
	if(discovery) {
		// Verify the primary is actually reachable via pipe
		var probe = net.createConnection(discovery.pipe, function() {
			probe.destroy();
			startProxyMode(discovery);
		});
		probe.on("error", function() {
			log("Discovery file exists but pipe is unreachable — becoming primary");
			cleanStaleDiscoveryFile();
			startAsPrimary(options);
		});
		probe.setTimeout(1000, function() {
			probe.destroy();
			log("Pipe probe timed out — becoming primary");
			cleanStaleDiscoveryFile();
			startAsPrimary(options);
		});
		return;
	}

	startAsPrimary(options);
}

exports.startMCPServer = startMCPServer;
exports.readDiscoveryFile = readDiscoveryFile;
exports.getCanonicalWikiPath = getCanonicalWikiPath;
// Test seam. The protocol contract (discovery, version gate, result shape) is
// worth pinning without standing up a transport to reach it.
exports.dispatchMessage = dispatchMessage;
exports.classifyOutbound = classifyOutbound;
exports.RELOAD_FILE_METHOD = RELOAD_FILE_METHOD;
exports.LSP_HELLO_METHOD = LSP_HELLO_METHOD;
exports.handlePipeNotification = handlePipeNotification;
exports.forgetPipeClient = forgetPipeClient;
exports.listLspClients = listLspClients;
exports.browserHost = browserHost;
exports.TW_AUTH = TW_AUTH;
exports.TW_PID = TW_PID;
exports.TW_LABEL = TW_LABEL;
","type":"application/javascript","module-type":"library"},"$:/core/modules/commands/inspect/mcp/mcp-pear.js":{"title":"$:/core/modules/commands/inspect/mcp/mcp-pear.js","text":"/*\
title: $:/core/modules/commands/inspect/mcp/mcp-pear.js
type: application/javascript
module-type: library

Pear-mode backend: `--mcp pear=<accountDir>` serves a RUNNING Facets (Pear)
app instead of this process's wiki. The account dir's discovery file
(mcp.json, written by the app when it is started with --mcp) names a same-user
OS pipe; every tool call is forwarded over it as an NDJSON bridge frame
({v:1,id,cmd,args} -> {id,ok,result|error}). This process's own wiki is only
the plugin host — no local handlers, no HTTP, no primary/proxy machinery.

Every tool runs the REAL tw-mcp handler inside the app's headless TW engine
over the member's composed bag+staging view — full feature parity with the
node server (ruled 2026-07-17). Write tools are admitted only at rw scope;
their persistence leaves the engine through the persist seam (shared.init
persist/remove hooks) and routes through the app's bag/staging path, so
staging gates them like member saves.
\*/

"use strict";

var fs = $tw.node ? require("fs") : null;
var path = $tw.node ? require("path") : null;
var net = $tw.node ? require("net") : null;
var os = $tw.node ? require("os") : null;
var ncrypto = $tw.node ? require("crypto") : null;

var PROTOCOL_VERSION = "2026-07-28";
var MODERN_VERSIONS = [PROTOCOL_VERSION];

// Handshake-era revisions, still served for the same reason as in mcp-lib.js:
// a dual-era client falls back to initialize when server/discover does not
// answer inside its probe window, and refusing that fallback turns a slow
// start into a hard connection failure.
var LEGACY_VERSIONS = ["2025-11-25", "2025-06-18", "2025-03-26"];
var LEGACY_DEFAULT_VERSION = LEGACY_VERSIONS[0];

var SUPPORTED_VERSIONS = MODERN_VERSIONS.concat(LEGACY_VERSIONS);
var SERVER_NAME = "tiddlywiki-mcp";
var CALL_TIMEOUT_MS = 20000;

// Spec-defined _meta keys. The revision has no handshake, so a request carries
// its own version and a result carries the server's identity.
var META_VERSION = "io.modelcontextprotocol/protocolVersion";
var META_SERVER_INFO = "io.modelcontextprotocol/serverInfo";
var META_SUBSCRIPTION_ID = "io.modelcontextprotocol/subscriptionId";

// Freshness hint for tools/list. Short, because the advertised set depends on
// whether the app is reachable and on the scope the handshake settled on.
var LIST_TTL_MS = 30000;

// Every tool forwards VERBATIM (feature parity, ruled 2026-07-17): the app
// runs the real tw-mcp handler in its headless engine over the composed
// bag+staging view and the pre-formatted text passes through. Write tools
// are admitted only at rw scope; their persistence routes through the app's
// bag/staging path (the persist seam).
var PEAR_READ_TOOLS = ["get_wiki_info", "list_tiddlers", "get_tiddler", "run_filter", "render_tiddler", "render_text",
	"search_lines", "get_tiddlers", "render_field", "inspect_tree", "inspect_pos", "inspect_tw", "inspect_scope"];
var PEAR_WRITE_TOOLS = ["put_tiddler", "delete_tiddler", "edit_tiddler", "rename_tiddler", "replace_in_tiddlers"];

// The app's own tools (Facets concept 12.2): no tw-mcp handler defines them, so their
// definitions live here, and the app answers them. check_writes lists only at rw.
const PEAR_APP_TOOLS = [
	{
		name: "get_guide",
		description: "Read this first. The rules of this Facets workspace for an agent: what you are connected to, what you see, where your writes go, what fails without an error, and what to check before you finish. Topics: start (the default), failures, check.",
		inputSchema: { type: "object", properties: { topic: { type: "string", enum: ["start", "failures", "check"] } } },
		annotations: { readOnlyHint: true },
		rw: false
	},
	{
		name: "check_writes",
		description: "Before you finish: reports on the tiddlers you last modified, or on the titles you name. Finds protected titles, overrides of a plugin's tiddler, code, and links to tiddlers that do not exist. Writes nothing.",
		inputSchema: { type: "object", properties: { titles: { type: "array", items: { type: "string" } } } },
		annotations: { readOnlyHint: true },
		rw: true
	}
];

// A self-heal must fit inside the window a client is given to notice it, with
// room for the handshake, so the retry period is a fraction of it, not equal
// to it (bead tw-mcp-server-cjt).
var SELF_HEAL_NOTICE_MS = 30000;
var SELF_HEAL_RETRY_MS = 10000;

// This client's own ed25519 identity for `agent` mode (concept 12
// §Authorization). Persisted per-user so an approval sticks across restarts.
// node's ed25519 is RFC 8032 and verifies under the app's libsodium (measured).
// Where this instance keeps that identity; agent-key= lets one machine run
// more than one, which enrollment testing and two scopes both need.
function agentKeyPath(options) {
	return (options && options.agentKeyFile) || path.join(os.homedir(), ".tw-mcp", "agent-key.json");
}
function loadOrCreateAgentKey(options) {
	var file = agentKeyPath(options);
	var dir = path.dirname(file);
	try {
		var jwk = JSON.parse(fs.readFileSync(file, "utf8"));
		return {
			priv: ncrypto.createPrivateKey({ key: jwk, format: "jwk" }),
			pubHex: Buffer.from(jwk.x, "base64url").toString("hex")
		};
	} catch(e) {}
	var pair = ncrypto.generateKeyPairSync("ed25519");
	var privJwk = pair.privateKey.export({ format: "jwk" });
	try {
		fs.mkdirSync(dir, { recursive: true });
		fs.writeFileSync(file, JSON.stringify(privJwk), { mode: 0o600 });
	} catch(e) {}
	return {
		priv: pair.privateKey,
		pubHex: Buffer.from(pair.publicKey.export({ format: "jwk" }).x, "base64url").toString("hex")
	};
}
function signChallenge(priv, challengeHex) {
	return ncrypto.sign(null, Buffer.from(challengeHex, "hex"), priv).toString("hex");
}

function getServerVersion() {
	var plugin = $tw.wiki.getTiddler("$:/plugins/wikilabs/tw-mcp");
	return (plugin && plugin.fields.version) || "unknown";
}

// Under 2026-07-28 every result must carry resultType and should identify the
// server, so both are stamped here rather than at each call site. A
// handshake-era result carries neither: it got the identity at initialize.
function jsonrpcResponse(id, result, era) {
	var payload = result || {};
	if(era !== "legacy") {
		if(payload.resultType === undefined) {
			payload.resultType = "complete";
		}
		payload._meta = payload._meta || {};
		payload._meta[META_SERVER_INFO] = { name: SERVER_NAME, version: getServerVersion() };
	}
	return JSON.stringify({ jsonrpc: "2.0", id: id, result: payload });
}

// Which revision a message belongs to: "modern", "legacy", or null when it
// names a version we do not speak. Pure function of the message, so no
// per-connection state is needed. See eraOfMessage in mcp-lib.js.
function eraOfMessage(parsed) {
	if(parsed.method === "server/discover") {
		return "modern";
	}
	if(parsed.method === "initialize") {
		return "legacy";
	}
	var declared = parsed.params && parsed.params._meta && parsed.params._meta[META_VERSION];
	if(declared === undefined || declared === null) {
		return "legacy";
	}
	if(MODERN_VERSIONS.indexOf(declared) >= 0) {
		return "modern";
	}
	if(LEGACY_VERSIONS.indexOf(declared) >= 0) {
		return "legacy";
	}
	return null;
}

function jsonrpcError(id, code, message, data) {
	var err = { jsonrpc: "2.0", id: id, error: { code: code, message: message } };
	if(data !== undefined) {
		err.error.data = data;
	}
	return JSON.stringify(err);
}

function textResult(msg) {
	return { content: [{ type: "text", text: msg }] };
}

function errorResult(msg) {
	return { isError: true, content: [{ type: "text", text: msg }] };
}

function log(msg) {
	console.error("[tw-mcp pear] " + msg);
}

// The app side of pear mode: the pipe, the frames and the scope the handshake
// settled on. Split from the dispatcher (bead tw-mcp-server-i1k) because
// reaching it means dialling a running app, which a test cannot do; everything
// the protocol contract turns on lives in createPearSession instead.
// onHandshake fires whenever a handshake settles, so the session can tell a
// subscribed client that the tool list changed under it.
function createPearBridge(pearDir, options) {
	options = options || {};
	var onHandshake = options.onHandshake || function() {};

	// --- the pipe client (lazy connect, reconnect per call, per-call timeout) ---
	var sock = null;
	var sockBuf = "";
	var nextFrameId = 1;
	var inflight = {}; // frame id -> { cb, timer }
	var authState = "none"; // none | authenticated | pending | denied
	var authScope = "ro";
	var agentKey = null; // { priv, pubHex } — lazy, agent mode only
	var connState = "idle"; // idle | connecting | open — single-flight connect
	var connWaiters = [];
	var readyWaiters = []; // single-flight handshake
	var handshakeInFlight = false;
	function effectiveRw() {
		return (authScope === "rw") && (authState === "authenticated");
	}

	function readDiscovery() {
		try {
			return JSON.parse(fs.readFileSync(path.join(pearDir, "mcp.json"), "utf8"));
		} catch(e) {
			return null;
		}
	}
	function failInflight(err) {
		for(var id in inflight) {
			var entry = inflight[id];
			delete inflight[id];
			clearTimeout(entry.timer);
			entry.cb(err);
		}
	}
	function flushConn(err) {
		var w = connWaiters; connWaiters = [];
		if(err) connState = "idle";
		for(var i = 0; i < w.length; i++) w[i](err);
	}
	// single-flight: concurrent callers share ONE socket (a naive guard would
	// open a socket per pipelined request and race the handshake)
	function connect(cb) {
		if(connState === "open" && sock) return cb(null);
		connWaiters.push(cb);
		if(connState === "connecting") return;
		connState = "connecting";
		var disco = readDiscovery();
		if(!disco || !disco.pipe) {
			return flushConn(new Error("Facets app not reachable — no discovery file at " + path.join(pearDir, "mcp.json") + ". Is the app running with --mcp?"));
		}
		var s = net.connect(disco.pipe);
		var settled = false;
		s.on("connect", function() {
			settled = true;
			sock = s;
			sockBuf = "";
			connState = "open";
			flushConn(null);
		});
		s.on("data", function(chunk) {
			sockBuf += chunk.toString();
			var nl;
			while((nl = sockBuf.indexOf("\n")) >= 0) {
				var line = sockBuf.slice(0, nl);
				sockBuf = sockBuf.slice(nl + 1);
				if(!line.trim()) continue;
				var msg;
				try { msg = JSON.parse(line); } catch(e) { continue; }
				var entry = inflight[msg.id];
				if(entry) {
					delete inflight[msg.id];
					clearTimeout(entry.timer);
					entry.cb(null, msg);
				}
			}
		});
		s.on("error", function(e) {
			if(!settled) {
				settled = true;
				sock = null;
				flushConn(new Error("Facets pipe connect failed (" + e.message + ") — the app may have exited; restart it and retry"));
			} else {
				sock = null;
				failInflight(new Error("Facets pipe error: " + e.message));
			}
		});
		s.on("close", function() {
			sock = null;
			connState = "idle";
			authState = "none"; // re-enroll on the next connection
			failInflight(new Error("Facets pipe closed — the app exited or restarted; retry"));
		});
	}
	// raw frame over an already-open socket (no auth gate — used by the
	// handshake itself and, post-auth, by tool calls)
	function frame(cmd, args, cb) {
		var id = "mcp-" + (nextFrameId++);
		inflight[id] = {
			cb: cb,
			timer: setTimeout(function() {
				if(inflight[id]) {
					delete inflight[id];
					cb(new Error("Facets pipe timeout (" + CALL_TIMEOUT_MS + "ms) on " + cmd));
				}
			}, CALL_TIMEOUT_MS)
		};
		try {
			sock.write(JSON.stringify({ v: 1, id: id, cmd: cmd, args: args || {} }) + "\n");
		} catch(e) {
			delete inflight[id];
			cb(new Error("Facets pipe write failed: " + e.message));
		}
	}
	// connect + (in agent mode) run the enrollment handshake per socket;
	// single-flight so pipelined callers don't launch parallel handshakes that
	// clobber the server's per-connection nonce. A "pending" enrollment
	// re-runs the handshake — the approval may have landed since (the server
	// answers authenticated once the member approved in the Agents panel).
	function ready(cb) {
		connect(function(err) {
			if(err) return cb(err);
			if(authState !== "none" && authState !== "pending") return cb(null);
			readyWaiters.push(cb);
			if(handshakeInFlight) return;
			handshakeInFlight = true;
			function done(e) {
				handshakeInFlight = false;
				var w = readyWaiters; readyWaiters = [];
				for(var i = 0; i < w.length; i++) w[i](e);
				onHandshake();
			}
			if(!agentKey) agentKey = loadOrCreateAgentKey(options);
			frame("agent-hello", { pub: agentKey.pubHex, name: options.label || "claude-code" }, function(e, hello) {
				if(e) return done(e);
				if(!hello.ok) return done(new Error("agent-hello: " + hello.error));
				frame("agent-auth", { sig: signChallenge(agentKey.priv, hello.result.challenge) }, function(e2, auth) {
					if(e2) return done(e2);
					if(!auth.ok) return done(new Error("agent-auth: " + auth.error));
					if(auth.result.authenticated) { authState = "authenticated"; authScope = auth.result.scope || "ro"; }
					else { authState = "pending"; }
					done(null);
				});
			});
		});
	}
	// the tool-facing call: ensure ready, surface an un-approved enrollment as a
	// readable error, otherwise forward the frame
	function call(cmd, args, cb) {
		ready(function(err) {
			if(err) return cb(err);
			if(authState === "pending") return cb(new Error("Agent enrollment PENDING — approve this agent in the Facets app (pub " + agentKey.pubHex.slice(0, 8) + "…) via the dashboard Agents panel, then retry."));
			if(authState === "denied") return cb(new Error("Agent enrollment was denied for pub " + agentKey.pubHex.slice(0, 8) + "…"));
			frame(cmd, args, cb);
		});
	}

	// Self-healing: while unreachable or enrollment-pending, another handshake
	// may settle where the last one did not, so onHandshake can tell the client.
	function retryIfUnsettled() {
		if(authState !== "none" && authState !== "pending") return;
		ready(function() {});
	}

	return {
		ready: ready,
		call: call,
		effectiveRw: effectiveRw,
		readDiscovery: readDiscovery,
		retryIfUnsettled: retryIfUnsettled
	};
}

// The protocol contract of pear mode, with the app handed in. `send` takes one
// serialised line and `makeBridge(onHandshake)` supplies the app; the defaults
// are stdout and a real pipe client, so a test can replace both.
function createPearSession(options) {
	var pearDir = options.pearDir;
	var handlers = require("$:/core/modules/commands/inspect/mcp-handlers.js");
	var send = options.send || function(line) { process.stdout.write(line + "\n"); };
	var makeBridge = options.makeBridge || function(onHandshake) {
		return createPearBridge(pearDir, { onHandshake: onHandshake, label: options.label, agentKeyFile: options.agentKeyFile });
	};
	var bridge = makeBridge(function() { maybeNotifyListChanged(); });

	// tools/list_changed: remember what the last tools/list advertised; when a
	// later handshake lands in a different effective scope (the app came up,
	// the enrollment was approved, the agent was revoked) notify the client so
	// it re-fetches — the write set appears exactly when it becomes callable.
	// Delivery rides an open subscriptions/listen. This revision forbids an
	// unsolicited notification, and every one must name the subscription that
	// asked for it, so nothing is sent until a client opts in.
	var lastAdvertisedRw = null;
	var toolsListSubscribers = {}; // String(listen request id) -> the id itself
	function notifyOnSubscription(subscriptionId, method, params) {
		var body = params || {};
		body._meta = body._meta || {};
		body._meta[META_SUBSCRIPTION_ID] = subscriptionId;
		send(JSON.stringify({ jsonrpc: "2.0", method: method, params: body }));
	}
	function maybeNotifyListChanged() {
		if(lastAdvertisedRw === null || bridge.effectiveRw() === lastAdvertisedRw) return;
		lastAdvertisedRw = bridge.effectiveRw();
		for(var key in toolsListSubscribers) {
			notifyOnSubscription(toolsListSubscribers[key], "notifications/tools/list_changed");
		}
	}
	// Graceful closure: answer each open subscriptions/listen so the client can
	// tell a clean shutdown from a dropped transport.
	function closeSubscriptions() {
		for(var key in toolsListSubscribers) {
			var payload = { _meta: {} };
			payload._meta[META_SUBSCRIPTION_ID] = toolsListSubscribers[key];
			send(jsonrpcResponse(toolsListSubscribers[key], payload));
		}
		toolsListSubscribers = {};
	}

	function handlePearTool(name, args, done) {
		// every tool forwards VERBATIM: the app runs the real tw-mcp handler
		// in its headless engine (feature parity, ruled 2026-07-17) and the
		// handler's pre-formatted text passes through
		const appTool = PEAR_APP_TOOLS.find(function(t) { return t.name === name; });
		if(PEAR_READ_TOOLS.indexOf(name) < 0 && PEAR_WRITE_TOOLS.indexOf(name) < 0 && !appTool) {
			return done(null); // unknown tool
		}
		return bridge.call(name, args, function(err, r) {
			if(err) return done(errorResult(err.message));
			if(!r.ok) return done(errorResult("Facets: " + r.error));
			done(textResult((r.result && r.result.text) || ""));
		});
	}

	function pearToolDefinitions() {
		// Write tools show only once the agent is authenticated at rw; before
		// approval the read set still lists and calls return a pending error.
		var rw = bridge.effectiveRw();
		var names = rw ? PEAR_READ_TOOLS.concat(PEAR_WRITE_TOOLS) : PEAR_READ_TOOLS;
		const own = PEAR_APP_TOOLS.filter(function(t) { return rw || !t.rw; }).map(function(t) {
			return { name: t.name, description: t.description, inputSchema: t.inputSchema, annotations: t.annotations };
		});
		return own.concat(handlers.getToolDefinitions(!rw).filter(function(t) {
			return names.indexOf(t.name) >= 0;
		}));
	}

	// Handed over on server/discover and on initialize alike, so it lives in one
	// place. Read fresh each time: what the app is doing can change between calls.
	function pearInstructions() {
		var disco = bridge.readDiscovery();
		return "TiddlyWiki MCP server — PEAR MODE: tools answer from a RUNNING Facets app" +
			(disco ? " (group '" + (disco.name || disco.group) + "')" : " (NOT currently reachable)") +
			", not from this process's wiki.\n" +
			"- Call get_guide first: the workspace's rules for an agent, and what fails without an error.\n" +
			"- run_filter / render_* execute in the app's headless engine over the member's composed view (bag + staged edits).\n" +
			"- get_tiddler / list_tiddlers reflect the shared bag; staged-only edits appear in the engine view.\n" +
			"- This client enrolls with its own device identity; the member must approve it in the app's Agents panel before any tool works. A 'PENDING' error means approval is still needed.\n" +
			"- Once approved at rw, writes land like member saves: they stay PRIVATE in staging until the member commits them.\n" +
			"- A staged write is NOT yours to undo: only the member can discard or commit it, and delete_tiddler stages a deletion rather than removing the entry. Ask before writing what you cannot take back.\n" +
			"- 'Facets app not reachable' errors mean the app is not running; ask the user to start it with --mcp.";
	}

	function dispatch(line) {
		var parsed;
		try {
			parsed = JSON.parse(line);
		} catch(e) {
			return send(jsonrpcError(null, -32700, "Parse error"));
		}
		if(parsed.id === undefined || parsed.id === null) {
			// On stdio there is no stream to close, so a client ends a
			// subscription by cancelling the request that opened it.
			if(parsed.method === "notifications/cancelled" && parsed.params) {
				delete toolsListSubscribers[String(parsed.params.requestId)];
			}
			return; // notifications need no reply
		}
		var id = parsed.id;

		// A message naming a version we do not speak is refused in both eras. An
		// ABSENT version is not that case — it is how a handshake-era client
		// looks — so eraOfMessage reports legacy for it rather than null.
		var era = eraOfMessage(parsed);
		if(era === null) {
			return send(jsonrpcError(id, -32022, "Unsupported protocol version",
				{ supported: SUPPORTED_VERSIONS, requested: (parsed.params && parsed.params._meta && parsed.params._meta[META_VERSION]) || null }));
		}

		switch(parsed.method) {
			case "initialize": {
				// Echo the requested version when we speak it, otherwise name one we
				// do and let the client decide. A client that gets here has already
				// given up on server/discover, so refusing it strands the connection.
				var requested = (parsed.params && parsed.params.protocolVersion) || null;
				var negotiated = LEGACY_VERSIONS.indexOf(requested) >= 0 ? requested : LEGACY_DEFAULT_VERSION;
				return send(jsonrpcResponse(id, {
					protocolVersion: negotiated,
					// NOT listChanged: the tool-list notification rides an open
					// subscriptions/listen, which is a 2026-07-28 mechanism. Claiming
					// it here would promise a handshake-era client a notification
					// this dispatcher never sends.
					capabilities: { tools: {} },
					serverInfo: { name: SERVER_NAME, version: getServerVersion() },
					instructions: pearInstructions()
				}, era));
			}
			case "server/discover": {
				return send(jsonrpcResponse(id, {
					supportedVersions: SUPPORTED_VERSIONS,
					capabilities: { tools: { listChanged: true } },
					instructions: pearInstructions()
				}, era));
			}
			case "ping":
				// Removed in 2026-07-28 but present in every handshake-era revision,
				// where a client may use it as a liveness check.
				if(era === "legacy") {
					return send(jsonrpcResponse(id, {}, era));
				}
				return send(jsonrpcError(id, -32601, "Method not found: " + parsed.method));
			case "subscriptions/listen": {
				// The request stays OPEN: the acknowledgement is a notification,
				// and the JSON-RPC response is sent only when the subscription
				// ends. The acknowledged filter reports what we actually honour,
				// so unsupported types are omitted rather than silently implied.
				var wanted = (parsed.params && parsed.params.notifications) || {};
				var honoured = {};
				if(wanted.toolsListChanged) {
					toolsListSubscribers[String(id)] = id;
					honoured.toolsListChanged = true;
				}
				return notifyOnSubscription(id, "notifications/subscriptions/acknowledged", { notifications: honoured });
			}
			case "tools/list":
				// resolve the connection (and enrollment) first so the write
				// tools appear exactly when they are actually callable
				return bridge.ready(function() {
					lastAdvertisedRw = bridge.effectiveRw();
					// The cache hints are 2026-07-28 fields; the handshake era has
					// no such thing, so they are sent only to modern clients.
					var listResult = { tools: pearToolDefinitions() };
					if(era === "modern") {
						listResult.ttlMs = LIST_TTL_MS;
						listResult.cacheScope = "private";
					}
					send(jsonrpcResponse(id, listResult, era));
				});
			case "tools/call": {
				var toolName = parsed.params && parsed.params.name;
				var toolArgs = (parsed.params && parsed.params.arguments) || {};
				return handlePearTool(toolName, toolArgs, function(result) {
					if(result === null) return send(jsonrpcError(id, -32602, "Unknown tool: " + toolName));
					send(jsonrpcResponse(id, result, era));
				});
			}
			default:
				return send(jsonrpcError(id, -32601, "Method not found: " + parsed.method));
		}
	}

	return {
		dispatch: dispatch,
		closeSubscriptions: closeSubscriptions,
		bridge: bridge
	};
}

function startPearMode(options) {
	var session = createPearSession(options);

	// --- the stdio JSON-RPC loop (async dispatch — replies ride the pipe) ---
	var stdinBuf = "";
	process.stdin.setEncoding("utf8");
	process.stdin.on("data", function(chunk) {
		stdinBuf += chunk;
		var lines = stdinBuf.split("\n");
		stdinBuf = lines.pop();
		for(var i = 0; i < lines.length; i++) {
			if(lines[i].trim()) session.dispatch(lines[i].trim());
		}
	});
	process.stdin.on("end", function() {
		session.closeSubscriptions();
		process.exit(0);
	});
	var disco = session.bridge.readDiscovery();
	log("pear mode: " + options.pearDir + (disco ? " -> " + disco.pipe + " (" + disco.mode + ")" : " (app not running yet — will dial on first call)"));
	// self-healing: while unreachable or enrollment-pending, retry the
	// handshake — when the app comes up or the approval lands, the client is
	// told to re-fetch the tool list.
	setInterval(function() {
		session.bridge.retryIfUnsettled();
	}, SELF_HEAL_RETRY_MS);
}

exports.startPearMode = startPearMode;
// Test seam: the protocol contract is worth pinning without a running app to
// dial (bead tw-mcp-server-i1k).
exports.createPearSession = createPearSession;
// Test seam: the default must keep an existing approval working (bead tw-mcp-server-u7n).
exports.agentKeyPath = agentKeyPath;
exports.SELF_HEAL_NOTICE_MS = SELF_HEAL_NOTICE_MS;
exports.SELF_HEAL_RETRY_MS = SELF_HEAL_RETRY_MS;
","type":"application/javascript","module-type":"library"},"$:/core/modules/commands/inspect/mcp/mcp-route.js":{"title":"$:/core/modules/commands/inspect/mcp/mcp-route.js","text":"/*\
title: $:/core/modules/commands/inspect/mcp/mcp-route.js
type: application/javascript
module-type: library

Route mode: `--mcp route=<dir>` serves every tw-mcp primary running in a
subfolder of <dir>, found by its `.tw-mcp/connect` discovery file. Each tool
gains a `wiki` argument; without it a call goes to the wiki on the default
port. Calls are forwarded over the primary's pipe like a proxy's.
\*/

"use strict";

var fs = $tw.node ? require("fs") : null;
var path = $tw.node ? require("path") : null;
var net = $tw.node ? require("net") : null;

var PROTOCOL_VERSION = "2026-07-28";
var MODERN_VERSIONS = [PROTOCOL_VERSION];
var LEGACY_VERSIONS = ["2025-11-25", "2025-06-18", "2025-03-26"];
var LEGACY_DEFAULT_VERSION = LEGACY_VERSIONS[0];
var SUPPORTED_VERSIONS = MODERN_VERSIONS.concat(LEGACY_VERSIONS);
var SERVER_NAME = "tiddlywiki-mcp";
var CALL_TIMEOUT_MS = 120000;
var LIST_TTL_MS = 60000;
var DEFAULT_PORT = 8080;

var META_VERSION = "io.modelcontextprotocol/protocolVersion";
var META_SERVER_INFO = "io.modelcontextprotocol/serverInfo";
var META_SUBSCRIPTION_ID = "io.modelcontextprotocol/subscriptionId";

var LIST_WIKIS_TOOL = {
	name: "list_wikis",
	description: "Lists the TiddlyWiki servers this router can reach right now: their names, labels and HTTP ports. Pass a name, label or port as the `wiki` argument of any other tool to choose one.",
	inputSchema: { type: "object", properties: {} },
	annotations: { readOnlyHint: true }
};

/**
 * Returns the tw-mcp plugin version.
 * @returns {string} Version, or "unknown"
 */
function getServerVersion() {
	var plugin = $tw.wiki.getTiddler("$:/plugins/wikilabs/tw-mcp");
	return (plugin && plugin.fields.version) || "unknown";
}

/**
 * Tells whether a process id is alive.
 * @param {number} pid - process id
 * @returns {boolean} True if the process exists
 */
function isProcessRunning(pid) {
	try {
		process.kill(pid, 0);
		return true;
	} catch(e) {
		// ESRCH: no such process; EPERM: alive but not ours, still running
		if(e.code === "EPERM") {
			return true;
		}
		if(e.code === "ESRCH") {
			return false;
		}
		throw e;
	}
}

/**
 * Lists the live primaries whose discovery file sits one folder below dir.
 * @param {string} dir - folder to scan, eg: an editions folder
 * @returns {Array<{name: string, label: (string|null), port: (number|null), listen: boolean, pid: number, pipe: string, token: string}>} Live wikis, sorted by name
 */
function scanWikis(dir) {
	var wikis = [];
	if(!fs.existsSync(dir)) {
		return wikis;
	}
	fs.readdirSync(dir, { withFileTypes: true }).forEach(function(entry) {
		if(!entry.isDirectory()) {
			return;
		}
		var file = path.join(dir, entry.name, ".tw-mcp", "connect");
		if(!fs.existsSync(file)) {
			return;
		}
		var data;
		try {
			data = JSON.parse(fs.readFileSync(file, "utf8"));
		} catch(e) {
			// A primary may be rewriting the file; skip it until the next scan
			if(e instanceof SyntaxError) {
				return;
			}
			throw e;
		}
		if(!data || !data.pid || !data.pipe || !data.token || !isProcessRunning(data.pid)) {
			return;
		}
		wikis.push({
			name: entry.name,
			label: data.label || null,
			port: data.port || null,
			listen: !!data.listen,
			pid: data.pid,
			pipe: data.pipe,
			token: data.token
		});
	});
	return wikis.sort(function(a, b) {
		return a.name < b.name ? -1 : (a.name > b.name ? 1 : 0);
	});
}

/**
 * Picks the wiki a call goes to.
 * @param {Array<object>} wikis - live wikis from scanWikis
 * @param {string} [wanted] - name, label or port the caller asked for
 * @param {number} defaultPort - port used when nothing is asked for
 * @returns {{wiki: (object|null), error: (string|null)}} The wiki, or why none fits
 */
function pickWiki(wikis, wanted, defaultPort) {
	if(wikis.length === 0) {
		return { wiki: null, error: "No TiddlyWiki server is running. Start one with `npm start` in its edition folder, then retry." };
	}
	var names = wikis.map(describeWiki).join("\n");
	if(wanted !== undefined && wanted !== null && wanted !== "") {
		var key = String(wanted);
		var match = wikis.find(function(w) {
			return w.name === key || w.name === key.replace(/-server$/, "") || w.label === key || String(w.port) === key;
		});
		return match ? { wiki: match, error: null } : { wiki: null, error: "No running wiki matches '" + key + "'. Running:\n" + names };
	}
	var byPort = wikis.find(function(w) {
		return w.listen && w.port === defaultPort;
	});
	if(byPort) {
		return { wiki: byPort, error: null };
	}
	if(wikis.length === 1) {
		return { wiki: wikis[0], error: null };
	}
	return { wiki: null, error: "Several wikis are running and none is on port " + defaultPort + ". Name one with the `wiki` argument:\n" + names };
}

/**
 * Formats one wiki for list_wikis and error texts.
 * @param {object} wiki - live wiki from scanWikis
 * @returns {string} One line
 */
function describeWiki(wiki) {
	return "- " + wiki.name + (wiki.label ? " (label " + wiki.label + ")" : "") +
		(wiki.listen && wiki.port ? " http://localhost:" + wiki.port : " no HTTP") +
		", pid " + wiki.pid;
}

/**
 * Opens and reuses one pipe connection per primary, matching answers to calls.
 * @param {object} lib - mcp-lib exports, for the auth meta keys
 * @param {string} [label] - this router's label, sent to the primary
 * @returns {{call: function(object, object, function): void}} Pipe client
 */
function createPipeLinks(lib, label) {
	var links = {}; // pipe path -> { socket, buffer, inflight }
	var nextId = 1;

	function failAll(link, message) {
		Object.keys(link.inflight).forEach(function(id) {
			var entry = link.inflight[id];
			clearTimeout(entry.timer);
			entry.cb(new Error(message));
		});
		link.inflight = {};
	}

	function open(wiki) {
		var link = { socket: net.connect(wiki.pipe), buffer: "", inflight: {} };
		link.socket.setEncoding("utf8");
		link.socket.on("data", function(chunk) {
			link.buffer += chunk;
			var lines = link.buffer.split("\n");
			link.buffer = lines.pop();
			lines.forEach(function(line) {
				if(!line.trim()) {
					return;
				}
				var msg;
				try {
					msg = JSON.parse(line);
				} catch(e) {
					if(e instanceof SyntaxError) {
						return;
					}
					throw e;
				}
				// Broadcasts such as notifications/takeover carry no id of ours
				var entry = msg && link.inflight[msg.id];
				if(entry) {
					delete link.inflight[msg.id];
					clearTimeout(entry.timer);
					entry.cb(null, msg);
				}
			});
		});
		link.socket.on("error", function(e) {
			delete links[wiki.pipe];
			failAll(link, "Pipe to " + wiki.name + " failed: " + e.message);
		});
		link.socket.on("close", function() {
			delete links[wiki.pipe];
			failAll(link, "Pipe to " + wiki.name + " closed. The server stopped or restarted; retry.");
		});
		links[wiki.pipe] = link;
		return link;
	}

	function call(wiki, msg, cb) {
		var link = links[wiki.pipe] || open(wiki);
		var id = "route-" + (nextId++);
		var out = JSON.parse(JSON.stringify(msg));
		out.id = id;
		out.params = out.params || {};
		out.params._meta = out.params._meta || {};
		out.params._meta[lib.TW_AUTH] = wiki.token;
		out.params._meta[lib.TW_PID] = process.pid;
		if(label) {
			out.params._meta[lib.TW_LABEL] = label;
		}
		link.inflight[id] = {
			cb: cb,
			timer: setTimeout(function() {
				if(link.inflight[id]) {
					delete link.inflight[id];
					cb(new Error("No answer from " + wiki.name + " within " + CALL_TIMEOUT_MS + "ms"));
				}
			}, CALL_TIMEOUT_MS)
		};
		link.socket.write(JSON.stringify(out) + "\n");
	}

	return { call: call };
}

/**
 * Builds the route-mode dispatcher; send, scan and link are seams for tests.
 * @param {object} options - routeDir, readonly, label, defaultPort, send, scan, links
 * @returns {{dispatch: function(string): void}} Session
 */
function createRouteSession(options) {
	var handlers = require("$:/core/modules/commands/inspect/mcp-handlers.js");
	var lib = require("$:/core/modules/commands/inspect/mcp/mcp-lib.js");
	var defaultPort = options.defaultPort || DEFAULT_PORT;
	var readonly = options.readonly !== false;
	var send = options.send || function(line) { process.stdout.write(line + "\n"); };
	var scan = options.scan || function() { return scanWikis(options.routeDir); };
	var links = options.links || createPipeLinks(lib, options.label);
	var writeToolNames = handlers.getWriteToolNames();

	function respond(id, result, era) {
		if(era !== "legacy") {
			if(result.resultType === undefined) {
				result.resultType = "complete";
			}
			result._meta = result._meta || {};
			result._meta[META_SERVER_INFO] = { name: SERVER_NAME, version: getServerVersion() };
		}
		send(JSON.stringify({ jsonrpc: "2.0", id: id, result: result }));
	}

	function fail(id, code, message, data) {
		var err = { jsonrpc: "2.0", id: id, error: { code: code, message: message } };
		if(data !== undefined) {
			err.error.data = data;
		}
		send(JSON.stringify(err));
	}

	function textResult(text, isError) {
		var result = { content: [{ type: "text", text: text }] };
		if(isError) {
			result.isError = true;
		}
		return result;
	}

	function eraOf(parsed) {
		if(parsed.method === "server/discover") {
			return "modern";
		}
		if(parsed.method === "initialize") {
			return "legacy";
		}
		var declared = parsed.params && parsed.params._meta && parsed.params._meta[META_VERSION];
		if(declared === undefined || declared === null) {
			return "legacy";
		}
		if(MODERN_VERSIONS.includes(declared)) {
			return "modern";
		}
		return LEGACY_VERSIONS.includes(declared) ? "legacy" : null;
	}

	function toolDefinitions() {
		var wikiArg = {
			type: "string",
			description: "Which running wiki: its folder name, label or HTTP port. Default: the wiki on port " + defaultPort + ". See list_wikis."
		};
		return [LIST_WIKIS_TOOL].concat(handlers.getToolDefinitions(readonly).map(function(def) {
			var copy = JSON.parse(JSON.stringify(def));
			copy.inputSchema = copy.inputSchema || { type: "object", properties: {} };
			copy.inputSchema.properties = copy.inputSchema.properties || {};
			copy.inputSchema.properties.wiki = wikiArg;
			return copy;
		}));
	}

	function instructions() {
		var wikis = scan();
		return "TiddlyWiki MCP server — ROUTE MODE: one entry for every tw-mcp server running under " + options.routeDir + ".\n" +
			"- Every tool takes an optional `wiki` argument: a folder name, label or HTTP port. Without it, the call goes to the wiki on port " + defaultPort + ".\n" +
			"- Servers come and go; call list_wikis to see which are running now.\n" +
			(readonly ? "- READONLY mode — writes disabled.\n" : "") +
			"Running at start:\n" + (wikis.length ? wikis.map(describeWiki).join("\n") : "- none");
	}

	function callTool(parsed, id, era) {
		var name = parsed.params && parsed.params.name;
		var args = Object.assign({}, (parsed.params && parsed.params.arguments) || {});
		if(name === LIST_WIKIS_TOOL.name) {
			var wikis = scan();
			return respond(id, textResult(wikis.length ? wikis.map(describeWiki).join("\n") : "No TiddlyWiki server is running."), era);
		}
		if(!toolDefinitions().some(function(def) { return def.name === name; })) {
			if(readonly && writeToolNames[name]) {
				return respond(id, textResult("Tool '" + name + "' is disabled in readonly mode", true), era);
			}
			return fail(id, -32602, "Unknown tool: " + name);
		}
		var pick = pickWiki(scan(), args.wiki, defaultPort);
		if(!pick.wiki) {
			return respond(id, textResult(pick.error, true), era);
		}
		delete args.wiki;
		var forwarded = JSON.parse(JSON.stringify(parsed));
		forwarded.params.arguments = args;
		links.call(pick.wiki, forwarded, function(err, answer) {
			if(err) {
				return respond(id, textResult(err.message, true), era);
			}
			var reply = { jsonrpc: "2.0", id: id };
			if(answer.error) {
				reply.error = answer.error;
			} else {
				reply.result = answer.result;
			}
			send(JSON.stringify(reply));
		});
	}

	function dispatch(line) {
		var parsed;
		try {
			parsed = JSON.parse(line);
		} catch(e) {
			if(e instanceof SyntaxError) {
				return fail(null, -32700, "Parse error");
			}
			throw e;
		}
		if(parsed.id === undefined || parsed.id === null) {
			return; // notifications need no reply
		}
		var id = parsed.id;
		var era = eraOf(parsed);
		if(era === null) {
			return fail(id, -32022, "Unsupported protocol version",
				{ supported: SUPPORTED_VERSIONS, requested: parsed.params._meta[META_VERSION] });
		}
		switch(parsed.method) {
			case "initialize": {
				var requested = (parsed.params && parsed.params.protocolVersion) || null;
				return respond(id, {
					protocolVersion: LEGACY_VERSIONS.includes(requested) ? requested : LEGACY_DEFAULT_VERSION,
					capabilities: { tools: {} },
					serverInfo: { name: SERVER_NAME, version: getServerVersion() },
					instructions: instructions()
				}, era);
			}
			case "server/discover":
				return respond(id, {
					supportedVersions: SUPPORTED_VERSIONS,
					capabilities: { tools: {} },
					instructions: instructions()
				}, era);
			case "ping":
				if(era === "legacy") {
					return respond(id, {}, era);
				}
				return fail(id, -32601, "Method not found: " + parsed.method);
			case "subscriptions/listen": {
				// The tool list never changes, so no notification type is honoured
				var ack = { notifications: {}, _meta: {} };
				ack._meta[META_SUBSCRIPTION_ID] = id;
				return send(JSON.stringify({ jsonrpc: "2.0", method: "notifications/subscriptions/acknowledged", params: ack }));
			}
			case "tools/list": {
				var listResult = { tools: toolDefinitions() };
				if(era === "modern") {
					listResult.ttlMs = LIST_TTL_MS;
					listResult.cacheScope = "private";
				}
				return respond(id, listResult, era);
			}
			case "tools/call":
				return callTool(parsed, id, era);
			default:
				return fail(id, -32601, "Method not found: " + parsed.method);
		}
	}

	return { dispatch: dispatch };
}

/**
 * Starts route mode on stdio.
 * @param {object} options - routeDir, readonly, label, defaultPort
 * @returns {void}
 */
function startRouteMode(options) {
	var session = createRouteSession(options);
	var buffer = "";
	process.stdin.setEncoding("utf8");
	process.stdin.on("data", function(chunk) {
		buffer += chunk;
		var lines = buffer.split("\n");
		buffer = lines.pop();
		lines.forEach(function(line) {
			if(line.trim()) {
				session.dispatch(line.trim());
			}
		});
	});
	process.stdin.on("end", function() {
		process.exit(0);
	});
	var wikis = scanWikis(options.routeDir);
	console.error("[tw-mcp route] " + options.routeDir + " (" + (options.readonly !== false ? "READONLY" : "readwrite") + "), " + wikis.length + " wiki(s) running" +
		(wikis.length ? ": " + wikis.map(function(w) { return w.name; }).join(", ") : ""));
}

exports.startRouteMode = startRouteMode;
// Test seams: the dispatcher and target choice without a running primary.
exports.createRouteSession = createRouteSession;
exports.pickWiki = pickWiki;
exports.scanWikis = scanWikis;
","type":"application/javascript","module-type":"library"},"$:/core/modules/commands/inspect/handlers/admin.js":{"title":"$:/core/modules/commands/inspect/handlers/admin.js","text":"/*\
title: $:/core/modules/commands/inspect/handlers/admin.js
type: application/javascript
module-type: mcp-handler

MCP admin tools — currently: reload_mcp_modules for hot-reload of
plugin JS during development without restarting the server.

\*/

"use strict";

var shared = require("$:/core/modules/commands/inspect/handlers/shared.js");

// Both halves of the split plugin reload together: the runtime-agnostic
// tool core and this server plugin.
var PLUGIN_NAMES = ["wikilabs/tw-mcp-core", "wikilabs/tw-mcp"];

// Modules that hold live state and cannot be reloaded without breaking
// running connections, init context, or change listeners.
var EXCLUDE_FROM_RELOAD = {
	"$:/core/modules/commands/mcp.js": "command module, runs once at boot",
	"$:/core/modules/commands/inspect/mcp/mcp-lib.js": "holds dispatcher, pipe server, stdin listener",
	"$:/core/modules/commands/inspect/handlers/shared.js": "holds readonlyMode and checkPathAllowed init context",
	"$:/core/modules/commands/inspect/handlers/filesystem.js": "holds reload_tiddlers change listener"
};

// Modules whose exports object identity must be preserved because
// mcp-lib.js captured a reference at require-time.
var PRESERVE_IDENTITY = {
	"$:/core/modules/commands/inspect/mcp-handlers.js": true
};

// Map module-type to the $tw.Wiki.prototype cache TW builds lazily from
// $tw.modules.applyMethods. After a re-execute the cache holds stale
// function references; deleting the property forces the next
// getFilterOperators/getFilterRunPrefixes to rebuild from the now-fresh
// $tw.modules.types map.
var CACHE_INVALIDATE_MAP = {
	"filteroperator": "filterOperators",
	"filterrunprefix": "filterRunPrefixes"
};

// Gives a module its fresh text and forgets its exports, so the next require executes it again.
function resetModule(title, moduleType) {
	var text = $tw.wiki.getTiddlerText(title);
	if(!text) return { error: "no text in wiki store" };
	// Checked before the reset, so a broken module keeps its old exports instead of a half-executed one a dependent required.
	try {
		new Function("module", "exports", "require", text);
	} catch(e) {
		if(e instanceof SyntaxError) return { error: "SyntaxError: " + e.message };
		throw e;
	}
	var info = $tw.modules.titles[title];
	if(!info) {
		// Module added since boot — register it now so it can be executed.
		$tw.modules.titles[title] = info = {
			moduleType: moduleType,
			definition: text,
			exports: undefined
		};
	}
	var oldExports = info.exports;
	info.definition = text;
	info.exports = undefined;
	return { ok: true, oldExports: oldExports };
}

// Executes a reset module, unless a module requiring it already did.
function executeModule(title, moduleType, oldExports) {
	var info = $tw.modules.titles[title];
	if(info.exports === undefined) {
		try {
			$tw.modules.execute(title);
		} catch(e) {
			info.exports = oldExports;
			return { error: e.message };
		}
	}
	var newExports = info.exports;
	if(PRESERVE_IDENTITY[title] && oldExports && typeof oldExports === "object" && oldExports !== newExports) {
		var k;
		for(k in oldExports) {
			if(!Object.prototype.hasOwnProperty.call(newExports, k)) {
				delete oldExports[k];
			}
		}
		for(k in newExports) {
			oldExports[k] = newExports[k];
		}
		info.exports = oldExports;
		newExports = oldExports;
	}
	// $tw.modules.types[<type>][<title>] holds the per-type exports map that
	// applyMethods walks. $tw.modules.execute updates info.exports but does NOT
	// touch the types map, so re-point it explicitly.
	if(moduleType && $tw.modules.types[moduleType]) {
		$tw.modules.types[moduleType][title] = newExports;
	}
	return { ok: true };
}

module.exports = {
	"reload_mcp_modules": function(args) {
		var denied = shared.checkWritable("reload_mcp_modules");
		if(denied) return denied;
		args = args || {};

		var messages = [];
		var reloaded = [];
		var skipped = [];
		var errors = [];

		// Phase 1: re-read both plugins from disk so $tw.wiki has fresh
		// subtiddler text.
		if(args.skip_disk_reload !== true) {
			try {
				var paths = $tw.getLibraryItemSearchPaths(
					$tw.config.pluginsPath,
					$tw.config.pluginsEnvVar
				);
				// Replicate $tw.loadPlugin without its bare addTiddler. Use
				// the syncer's storeTiddler instead, which adds the tiddler
				// AND updates the syncer's tiddlerInfo.changeCount to match
				// the bumped wiki.changeCount. The syncer's later sync check
				// (`wiki.getChangeCount > tiddlerInfo.changeCount`) is then
				// false, so the bundle is never persisted to the edition's
				// tiddlers/ folder. Fallback to addTiddler if no syncer is
				// active (eg headless `--build`).
				for(var pi = 0; pi < PLUGIN_NAMES.length; pi++) {
					var pluginPath = $tw.findLibraryItem(PLUGIN_NAMES[pi], paths);
					if(!pluginPath) {
						return shared.errorResult("Plugin folder not found: " + PLUGIN_NAMES[pi]);
					}
					var pluginFields = $tw.loadPluginFolder(pluginPath);
					if(!pluginFields) {
						return shared.errorResult("Failed to load plugin from folder: " + pluginPath);
					}
					if($tw.syncer) {
						$tw.syncer.storeTiddler(pluginFields);
					} else {
						$tw.wiki.addTiddler(pluginFields);
					}
					messages.push("Plugin re-read from disk: $:/plugins/" + PLUGIN_NAMES[pi]);
				}
				$tw.wiki.readPluginInfo();
				$tw.wiki.registerPluginTiddlers(null);
				$tw.wiki.unpackPluginTiddlers();
			} catch(e) {
				return shared.errorResult("Failed to re-read plugin from disk: " + e.message);
			}
		}

		// Phase 2: collect JS module titles from both plugins.
		var moduleTitles = [];
		var moduleTypes = {};
		for(var pj = 0; pj < PLUGIN_NAMES.length; pj++) {
			var pluginTitle = "$:/plugins/" + PLUGIN_NAMES[pj];
			var pluginInfo = $tw.wiki.getPluginInfo(pluginTitle);
			if(!pluginInfo || !pluginInfo.tiddlers) {
				return shared.errorResult("Plugin info not found: " + pluginTitle);
			}
			Object.keys(pluginInfo.tiddlers).forEach(function(t) {
				var pt = pluginInfo.tiddlers[t];
				if(pt.type === "application/javascript" && pt["module-type"]) {
					moduleTitles.push(t);
					moduleTypes[t] = pt["module-type"];
				}
			});
		}
		moduleTitles.sort();

		// Phase 3: reset every module before executing any, so a module requiring
		// one that sorts after it gets that module's new exports.
		var touchedTypes = Object.create(null);
		var oldExports = Object.create(null);
		var reset = [];
		moduleTitles.forEach(function(title) {
			if(EXCLUDE_FROM_RELOAD[title]) {
				skipped.push(title + " (" + EXCLUDE_FROM_RELOAD[title] + ")");
				return;
			}
			var result = resetModule(title, moduleTypes[title]);
			if(result.ok) {
				oldExports[title] = result.oldExports;
				reset.push(title);
			} else {
				errors.push(title + ": " + result.error);
			}
		});
		reset.forEach(function(title) {
			var moduleType = moduleTypes[title];
			var result = executeModule(title, moduleType, oldExports[title]);
			if(result.ok) {
				reloaded.push(title + (PRESERVE_IDENTITY[title] ? " [identity]" : ""));
				if(moduleType && CACHE_INVALIDATE_MAP[moduleType]) {
					touchedTypes[moduleType] = true;
				}
			} else {
				errors.push(title + ": " + result.error);
			}
		});

		// Phase 4: invalidate Wiki.prototype caches whose source module-types
		// were touched. The next getFilterOperators / getFilterRunPrefixes
		// call rebuilds from the now-fresh $tw.modules.types map.
		var invalidatedCaches = [];
		Object.keys(touchedTypes).forEach(function(mt) {
			var protoKey = CACHE_INVALIDATE_MAP[mt];
			if(Object.prototype.hasOwnProperty.call($tw.Wiki.prototype, protoKey)) {
				delete $tw.Wiki.prototype[protoKey];
				invalidatedCaches.push(protoKey + " (" + mt + ")");
			}
		});

		// Build output
		var out = messages.concat([
			"",
			"Reloaded " + reloaded.length + " module(s):"
		]).concat(reloaded.map(function(s) { return "  " + s; }));
		if(invalidatedCaches.length > 0) {
			out.push("");
			out.push("Invalidated " + invalidatedCaches.length + " Wiki.prototype cache(s):");
			invalidatedCaches.forEach(function(s) { out.push("  " + s); });
		}
		if(skipped.length > 0) {
			out.push("");
			out.push("Skipped " + skipped.length + " (excluded; restart required):");
			skipped.forEach(function(s) { out.push("  " + s); });
		}
		if(errors.length > 0) {
			out.push("");
			out.push("Errors (" + errors.length + "):");
			errors.forEach(function(s) { out.push("  " + s); });
		}
		return errors.length > 0
			? shared.errorResult(out.join("\n"))
			: shared.textResult(out.join("\n"));
	}
};

// MCP tool definition — advertised via mcp-handlers getToolDefinitions();
// write:true marks tools hidden in readonly mode.
module.exports["reload_mcp_modules"].definition = {
	"description": "Hot-reload tw-mcp plugin. Re-reads plugin folder, refreshes ALL subtiddlers (JS + non-JS doc/wikitext/CSS), re-executes JS modules. Non-JS applies immediately; JS modules apply on next tool call. Excludes mcp.js/mcp-lib.js/shared.js/filesystem.js (hold live state — need server restart).",
	"inputSchema": {
		"type": "object",
		"properties": {
			"skip_disk_reload": {
				"type": "boolean",
				"default": false,
				"description": "Skip the $tw.loadPlugin step. Use only when the wiki store already has fresh plugin source (e.g., after a manual reload_tiddlers)."
			}
		},
		"required": []
	},
	"write": true
};
