"},"$:/config/SyncPollingInterval":{"title":"$:/config/SyncPollingInterval","text":"600000
"},"$:/core/modules/server/routes/sse-delete-tiddler.js":{"title":"$:/core/modules/server/routes/sse-delete-tiddler.js","text":"/*\
title: $:/core/modules/server/routes/sse-delete-tiddler.js
type: application/javascript
module-type: route

DELETE /bags/default/tiddlers/:title  --  with X-MCP-Client-Id stash for SSE
echo suppression. Mirrors the core delete-tiddler.js handler, but before
deleteTiddler() it records the originator clientId on $tw.mcp.sse so the
upcoming wiki "change" event can be broadcast tagged with that clientId.

Higher priority than the core handler so it wins the route match.

\*/

"use strict";

exports.methods = ["DELETE"];

exports.path = /^\/bags\/default\/tiddlers\/(.+)$/;

exports.info = {
	priority: 200
};

exports.handler = function(request, response, state) {
	var title = $tw.utils.decodeURIComponentSafe(state.params[0]);
	var clientId = request.headers["x-mcp-client-id"];
	if($tw.mcp && $tw.mcp.sse && $tw.mcp.sse.isConfigLockdownViolation(title, clientId)) {
		response.writeHead(403, {"Content-Type": "text/plain"});
		response.end("Main mode: only the admin can change SSE settings\n");
		return;
	}
	if(clientId && $tw.mcp && $tw.mcp.sse) {
		$tw.mcp.sse.recordOriginator(title, clientId);
	}
	state.wiki.deleteTiddler(title);
	response.writeHead(204, "OK", {
		"Content-Type": "text/plain"
	});
	response.end();
};
","type":"application/javascript","module-type":"route"},"$:/core/modules/server/routes/sse-main-claim.js":{"title":"$:/core/modules/server/routes/sse-main-claim.js","text":"/*\
title: $:/core/modules/server/routes/sse-main-claim.js
type: application/javascript
module-type: route

POST /main/claim  --  the requesting tab claims the i-am-main admin role
in main mode. Last-claim-wins -- a new claim demotes the previous admin.
The clientId is read from the X-MCP-Client-Id header; an optional
X-MCP-Username header carries the friendly name.

\*/

"use strict";

exports.methods = ["POST"];

exports.path = /^\/main\/claim$/;

exports.info = {
	priority: 500
};

exports.handler = function(request, response, state) {
	if(!$tw.mcp || !$tw.mcp.sse) {
		response.writeHead(503, {"Content-Type": "text/plain"});
		response.end("SSE not enabled\n");
		return;
	}
	var clientId = $tw.mcp.sse.assertCaller(request, response);
	if(!clientId) return;
	// Main is exclusive. Reject takeover attempts with 409 so the UI can
	// distinguish "already held" from generic refusal.
	if($tw.mcp.sse.mainClientId && $tw.mcp.sse.mainClientId !== clientId) {
		response.writeHead(409, {"Content-Type": "text/plain"});
		response.end("Main role already held by another tab\n");
		return;
	}
	var username = $tw.mcp.sse.capUsername(request.headers["x-mcp-username"] || null);
	// Becoming main also takes presenter -- the admin starts the session
	// in control. Only on the initial claim (mainClientId was null); a
	// re-claim with updated username won't yank presenter back from
	// someone the admin previously granted.
	var wasInitial = !$tw.mcp.sse.mainClientId;
	$tw.mcp.sse.claimMain(clientId, username);
	if(wasInitial) {
		$tw.mcp.sse.claimPresenter(clientId, username);
	}
	response.writeHead(204);
	response.end();
};
","type":"application/javascript","module-type":"route"},"$:/core/modules/server/routes/sse-main-release.js":{"title":"$:/core/modules/server/routes/sse-main-release.js","text":"/*\
title: $:/core/modules/server/routes/sse-main-release.js
type: application/javascript
module-type: route

POST /main/release  --  the requesting tab releases the i-am-main admin
role. Only the current admin can release the role; a release from a
different clientId is a no-op (returns 204 anyway, idempotent).

\*/

"use strict";

exports.methods = ["POST"];

exports.path = /^\/main\/release$/;

exports.info = {
	priority: 500
};

exports.handler = function(request, response, state) {
	if(!$tw.mcp || !$tw.mcp.sse) {
		response.writeHead(503, {"Content-Type": "text/plain"});
		response.end("SSE not enabled\n");
		return;
	}
	var clientId = $tw.mcp.sse.assertCaller(request, response);
	if(!clientId) return;
	$tw.mcp.sse.releaseMain(clientId);
	response.writeHead(204);
	response.end();
};
","type":"application/javascript","module-type":"route"},"$:/core/modules/server/routes/sse-presenter-claim.js":{"title":"$:/core/modules/server/routes/sse-presenter-claim.js","text":"/*\
title: $:/core/modules/server/routes/sse-presenter-claim.js
type: application/javascript
module-type: route

POST /presenter/claim  --  the requesting tab claims the presenter role
in presentation/main mode. Last-claim-wins -- a new claim demotes the
previous presenter. The clientId is read from the X-MCP-Client-Id
header. Idempotent.

\*/

"use strict";

exports.methods = ["POST"];

exports.path = /^\/presenter\/claim$/;

exports.info = {
	priority: 500
};

exports.handler = function(request, response, state) {
	if(!$tw.mcp || !$tw.mcp.sse) {
		response.writeHead(503, {"Content-Type": "text/plain"});
		response.end("SSE not enabled\n");
		return;
	}
	var clientId = $tw.mcp.sse.assertCaller(request, response);
	if(!clientId) return;
	// Main mode with an admin set: only the admin can grant presenter via
	// /presenter/grant. Self-claim from any other tab is forbidden. With
	// no admin, main behaves as last-wins (same as presentation).
	if($tw.mcp.sse.getMode() === "main"
		&& $tw.mcp.sse.mainClientId
		&& $tw.mcp.sse.mainClientId !== clientId) {
		response.writeHead(403, {"Content-Type": "text/plain"});
		response.end("Main mode: only the admin can grant presenter\n");
		return;
	}
	var username = $tw.mcp.sse.capUsername(request.headers["x-mcp-username"] || null);
	$tw.mcp.sse.claimPresenter(clientId, username);
	response.writeHead(204);
	response.end();
};
","type":"application/javascript","module-type":"route"},"$:/core/modules/server/routes/sse-presenter-grant.js":{"title":"$:/core/modules/server/routes/sse-presenter-grant.js","text":"/*\
title: $:/core/modules/server/routes/sse-presenter-grant.js
type: application/javascript
module-type: route

POST /presenter/grant  --  the i-am-main admin grants the presenter role
to a target clientId. Body: {"clientId": "<target>"}. The caller's
clientId rides in X-MCP-Client-Id and must equal the current main, else
403.

\*/

"use strict";

// Body should be a tiny `{"clientId":"<uuid>"}` (~50 bytes). 1KB is a
// generous ceiling that closes audit L3 without rejecting any legitimate
// payload.
var MAX_GRANT_BODY_BYTES = 1024;

exports.methods = ["POST"];

exports.path = /^\/presenter\/grant$/;

exports.info = {
	priority: 500
};

exports.bodyFormat = "string";

exports.handler = function(request, response, state) {
	if(!$tw.mcp || !$tw.mcp.sse) {
		response.writeHead(503, {"Content-Type": "text/plain"});
		response.end("SSE not enabled\n");
		return;
	}
	var adminClientId = $tw.mcp.sse.assertCaller(request, response);
	if(!adminClientId) return;
	var body = state.data || "";
	if(body.length > MAX_GRANT_BODY_BYTES) {
		response.writeHead(413, {"Content-Type": "text/plain"});
		response.end("Request body too large\n");
		return;
	}
	var parsed = null;
	try { parsed = JSON.parse(body); } catch(e) {
		response.writeHead(400, {"Content-Type": "text/plain"});
		response.end("Body must be JSON: {\"clientId\": \"...\"}\n");
		return;
	}
	var targetClientId = parsed && parsed.clientId;
	if(!targetClientId || !$tw.mcp.sse.isValidClientId(targetClientId)) {
		response.writeHead(400, {"Content-Type": "text/plain"});
		response.end("Body clientId missing or malformed\n");
		return;
	}
	var ok = $tw.mcp.sse.grantPresenter(adminClientId, targetClientId);
	if(!ok) {
		response.writeHead(403, {"Content-Type": "text/plain"});
		response.end("Grant rejected: caller is not main, or target is not connected\n");
		return;
	}
	response.writeHead(204);
	response.end();
};
","type":"application/javascript","module-type":"route"},"$:/core/modules/server/routes/sse-presenter-release.js":{"title":"$:/core/modules/server/routes/sse-presenter-release.js","text":"/*\
title: $:/core/modules/server/routes/sse-presenter-release.js
type: application/javascript
module-type: route

POST /presenter/release  --  the requesting tab releases the presenter
role. Only the current presenter can release the role; a release from a
different clientId is a no-op (returns 204 anyway, idempotent).

\*/

"use strict";

exports.methods = ["POST"];

exports.path = /^\/presenter\/release$/;

exports.info = {
	priority: 500
};

exports.handler = function(request, response, state) {
	if(!$tw.mcp || !$tw.mcp.sse) {
		response.writeHead(503, {"Content-Type": "text/plain"});
		response.end("SSE not enabled\n");
		return;
	}
	var clientId = $tw.mcp.sse.assertCaller(request, response);
	if(!clientId) return;
	// In main mode with an admin set, the admin force-clears the granted
	// presenter, and the current presenter may release themselves. Other
	// tabs are 403'd.
	var sse = $tw.mcp.sse;
	if(sse.getMode() === "main" && sse.mainClientId) {
		if(clientId === sse.mainClientId) {
			sse.releasePresenter(null);
		} else if(clientId === sse.presenterClientId) {
			sse.releasePresenter(clientId);
		} else {
			response.writeHead(403, {"Content-Type": "text/plain"});
			response.end("Main mode: only the admin or current presenter can release\n");
			return;
		}
	} else {
		sse.releasePresenter(clientId);
	}
	response.writeHead(204);
	response.end();
};
","type":"application/javascript","module-type":"route"},"$:/core/modules/server/routes/sse-put-tiddler.js":{"title":"$:/core/modules/server/routes/sse-put-tiddler.js","text":"/*\
title: $:/core/modules/server/routes/sse-put-tiddler.js
type: application/javascript
module-type: route

PUT /recipes/default/tiddlers/:title  --  with X-MCP-Client-Id stash for SSE
echo suppression. Mirrors the core put-tiddler.js handler, but before
addTiddler() it records the originator clientId on $tw.mcp.sse so the
upcoming wiki "change" event can be broadcast tagged with that clientId
(letting receivers skip events they triggered themselves).

Higher priority than the core handler so it wins the route match.

\*/

"use strict";

exports.methods = ["PUT"];

exports.path = /^\/recipes\/default\/tiddlers\/(.+)$/;

exports.info = {
	priority: 200
};

exports.handler = function(request, response, state) {
	var title = $tw.utils.decodeURIComponentSafe(state.params[0]),
		fields = $tw.utils.parseJSONSafe(state.data);
	if(fields.fields) {
		$tw.utils.each(fields.fields, function(field, name) {
			fields[name] = field;
		});
		delete fields.fields;
	}
	if(fields.revision) {
		delete fields.revision;
	}
	if(fields._is_skinny !== undefined) {
		var existing = state.wiki.getTiddler(title);
		if(existing) {
			fields.text = existing.fields.text;
		}
		delete fields._is_skinny;
	}
	var clientId = request.headers["x-mcp-client-id"];
	if($tw.mcp && $tw.mcp.sse && $tw.mcp.sse.isConfigLockdownViolation(title, clientId)) {
		response.writeHead(403, {"Content-Type": "text/plain"});
		response.end("Main mode: only the admin can change SSE settings\n");
		return;
	}
	if(clientId && $tw.mcp && $tw.mcp.sse) {
		$tw.mcp.sse.recordOriginator(title, clientId);
	}
	state.wiki.addTiddler(new $tw.Tiddler(fields, {title: title}));
	var changeCount = state.wiki.getChangeCount(title).toString();
	response.writeHead(204, "OK", {
		Etag: "\"default/" + encodeURIComponent(title) + "/" + changeCount + ":\"",
		"Content-Type": "text/plain"
	});
	response.end();
};
","type":"application/javascript","module-type":"route"},"$:/plugins/wikilabs/tw-mcp/sse-adaptor.js":{"title":"$:/plugins/wikilabs/tw-mcp/sse-adaptor.js","text":"/*\
title: $:/plugins/wikilabs/tw-mcp/sse-adaptor.js
type: application/javascript
module-type: library

Factory that wraps the stock tiddlyweb syncadaptor with SSE behaviour.

The bootstrap calls makeSSEAdaptor(TiddlyWebAdaptor) and assigns the
returned class back to tiddlyweb's `exports.adaptorClass`. The syncer's
adaptor selection then instantiates the SSE-aware subclass.

We inherit four methods from tiddlyweb unchanged:
  getSkinnyTiddlers, loadTiddler, login, logout
And two prototype helpers:
  convertTiddlerToTiddlyWebFormat, convertTiddlerFromTiddlyWebFormat,
  parseEtag, getHost, getCsrfToken, getTiddlerInfo, getTiddlerRevision,
  setLoggerSaveBuffer, isReady

We override:
  getStatus     -- wraps the inherited one to also open the SSE stream
  saveTiddler   -- adds X-MCP-Client-Id header (tiddlyweb hardcodes
                   headers, so we must re-implement the body)
  deleteTiddler -- adds X-MCP-Client-Id header (same reason)

We add:
  connectEventStream, handleHello, handleTiddlerChange, handleTiddlerDelete,
  handleCacheMiss, forceFullSync, plus per-instance clientId / eventSource /
  lastServerInstanceId state.

This keeps all unchanged tiddlyweb logic in tiddlyweb's own module so any
upstream fixes flow through automatically.

\*/

"use strict";

var STATE_PRESENTER = "$:/state/wikilabs/tw-mcp/presenter-clientId";
var STATE_PRESENTER_USERNAME = "$:/state/wikilabs/tw-mcp/presenter-username";
var STATE_MAIN = "$:/state/wikilabs/tw-mcp/main-clientId";
var STATE_MAIN_USERNAME = "$:/state/wikilabs/tw-mcp/main-username";
var STATE_CLIENTS_LIST = "$:/state/wikilabs/tw-mcp/clients-list";
var STATE_MY_CLIENT_ID = "$:/state/wikilabs/tw-mcp/my-clientId";
var STATE_CONNECTION = "$:/state/wikilabs/tw-mcp/sse-connection";
var USERNAME_TIDDLER = "$:/status/UserName";
// sessionStorage key for per-tab username persistence. sessionStorage is
// scoped to a single browser tab, so each tab keeps its own UserName
// across page reloads without bleeding into siblings (which is what
// localStorage / browserStorage would do).
var USERNAME_SESSION_KEY = "wikilabs-tw-mcp-username";
var PER_TAB_TIDDLERS_TIDDLER = "$:/config/wikilabs/tw-mcp/per-tab-tiddlers";
var DEFAULT_PER_TAB_FILTER = "[[$:/StoryList]] [[$:/HistoryList]] [prefix[$:/state/]]";
var SYNC_FILTER_TIDDLER = "$:/config/SyncFilter";

function generateClientId() {
	// Pre-hello placeholder. The server issues the real clientId at /events
	// connect and returns it via hello.assignedClientId; the adaptor adopts
	// it in handleHello. Until then, this UUID stands in for X-MCP-Client-Id
	// headers on any save/delete that fires before hello arrives --
	// echo-suppression matches against this.clientId regardless of who
	// minted it.
	// crypto.randomUUID is universal across modern browsers (Chrome 92+,
	// Firefox 95+, Safari 15.4+) on every origin including plain http
	// (only crypto.subtle is gated by secure context).
	if(typeof crypto === "undefined" || !crypto.randomUUID) {
		throw new Error("crypto.randomUUID() unavailable; tw-mcp/sse requires a modern browser");
	}
	return crypto.randomUUID();
}

function parseSSEData(ev) {
	try {
		return JSON.parse(ev.data);
	} catch(e) {
		return null;
	}
}

exports.makeSSEAdaptor = function(BaseClass) {
	function TiddlyWebSSEAdaptor(options) {
		BaseClass.call(this, options);
		// Pre-hello placeholder; handleHello overwrites with the server-issued
		// clientId. STATE_MY_CLIENT_ID is left unstamped here -- the UI's
		// "(this tab)" match only ever resolves against server-issued ids
		// (which is what presenter-changed events carry), so a placeholder
		// stamp would never match anything anyway.
		this.clientId = generateClientId();
		this.eventSource = null;
		this.lastServerInstanceId = null;
		this.lastPingAt = null;
		// Re-stamp the logger so console output identifies the actual class
		this.logger = new $tw.utils.Logger("TiddlyWebSSEAdaptor");
		// Hook UI buttons. The ControlPanel emits these messages.
		var self = this;
		if($tw.rootWidget) {
			$tw.rootWidget.addEventListener("tm-mcp-claim-presenter", function() {
				self.postRoleAction("presenter", "claim");
			});
			$tw.rootWidget.addEventListener("tm-mcp-release-presenter", function() {
				self.postRoleAction("presenter", "release");
			});
			$tw.rootWidget.addEventListener("tm-mcp-claim-main", function() {
				self.postRoleAction("main", "claim");
			});
			$tw.rootWidget.addEventListener("tm-mcp-release-main", function() {
				self.postRoleAction("main", "release");
			});
			$tw.rootWidget.addEventListener("tm-mcp-grant-presenter", function(event) {
				self.postPresenterGrant(event.param);
			});
			$tw.rootWidget.addEventListener("tm-mcp-refresh-clients", function() {
				self.refreshClientsList();
			});
		}
		// Watch for per-tab tiddler changes the syncer would skip (most
		// notably $:/state/*) and push them directly when we're the
		// presenter. Without this the presenter's UI state wouldn't reach
		// followers because TW's SyncFilter excludes $:/state/* entirely.
		this.wiki.addEventListener("change", function(changes) {
			self.pushPerTabIfPresenter(changes);
			if(changes[USERNAME_TIDDLER]) {
				try {
					var val = self.wiki.getTiddlerText(USERNAME_TIDDLER, "") || "";
					// Only persist non-empty values. TW writes "" at boot
					// before our getStatus override has a chance to restore
					// from sessionStorage; saving that "" would clobber the
					// previously saved name.
					if(val) sessionStorage.setItem(USERNAME_SESSION_KEY, val);
				} catch(e) {}
			}
		});
	}
	TiddlyWebSSEAdaptor.prototype = Object.create(BaseClass.prototype);
	TiddlyWebSSEAdaptor.prototype.constructor = TiddlyWebSSEAdaptor;
	TiddlyWebSSEAdaptor.prototype.name = "tiddlywebsse";

	TiddlyWebSSEAdaptor.prototype.saveTiddler = function(tiddler, callback, options) {
		var self = this;
		if(this.isReadOnly) {
			return callback(null);
		}
		$tw.utils.httpRequest({
			url: this.host + "recipes/" + encodeURIComponent(this.recipe) + "/tiddlers/" + encodeURIComponent(tiddler.fields.title),
			type: "PUT",
			headers: {
				"Content-type": "application/json",
				"X-MCP-Client-Id": this.clientId
			},
			data: this.convertTiddlerToTiddlyWebFormat(tiddler),
			callback: function(err, data, request) {
				if(err) {
					return callback(err);
				}
				if($tw.browserStorage && $tw.browserStorage.isEnabled()) {
					$tw.browserStorage.removeTiddlerFromLocalStorage(tiddler.fields.title);
				}
				var etag = request.getResponseHeader("Etag");
				if(!etag) {
					callback("Response from server is missing required `etag` header");
				} else {
					var etagInfo = self.parseEtag(etag);
					callback(null, {bag: etagInfo.bag}, etagInfo.revision);
				}
			}
		});
	};

	TiddlyWebSSEAdaptor.prototype.deleteTiddler = function(title, callback, options) {
		if(this.isReadOnly) {
			return callback(null);
		}
		var bag = options.tiddlerInfo.adaptorInfo && options.tiddlerInfo.adaptorInfo.bag;
		if(!bag) {
			return callback(null, options.tiddlerInfo.adaptorInfo);
		}
		$tw.utils.httpRequest({
			url: this.host + "bags/" + encodeURIComponent(bag) + "/tiddlers/" + encodeURIComponent(title),
			type: "DELETE",
			headers: {
				"X-MCP-Client-Id": this.clientId
			},
			callback: function(err) {
				if(err) {
					return callback(err);
				}
				callback(null, null);
			}
		});
	};

	var baseGetStatus = BaseClass.prototype.getStatus;
	TiddlyWebSSEAdaptor.prototype.getStatus = function(callback) {
		var self = this;
		baseGetStatus.call(this, function(err, isLoggedIn, username, isReadOnly, isAnonymous) {
			if(!err) {
				// Per-tab UserName: if the server returned no username (the
				// usual anonymous case), substitute whatever this tab last
				// had in sessionStorage. Stamp the wiki up front so the
				// SSE stream URL picks it up, and also pass it through to
				// the syncer's callback so its own $:/status/UserName write
				// matches (instead of clobbering with "").
				if(!username) {
					try {
						var saved = sessionStorage.getItem(USERNAME_SESSION_KEY);
						if(saved) {
							username = saved;
							self.wiki.addTiddler({title: USERNAME_TIDDLER, text: saved});
						}
					} catch(e) {}
				}
				self.connectEventStream();
			}
			if(callback) {
				callback(err, isLoggedIn, username, isReadOnly, isAnonymous);
			}
		});
	};

	TiddlyWebSSEAdaptor.prototype.connectEventStream = function() {
		var self = this;
		if(this.eventSource) return;
		if(typeof EventSource === "undefined") {
			this.logger.log("EventSource not available; SSE disabled, falling back to polling");
			return;
		}
		// EventSource cannot set custom headers, so the username rides in the
		// query string. The server issues the clientId itself (returned via
		// the hello payload's assignedClientId field) -- any caller-supplied
		// clientId is ignored, so we don't bother sending one.
		var username = this.wiki.getTiddlerText(USERNAME_TIDDLER, "") || "";
		var url = this.host + "events";
		if(username) {
			url += "?username=" + encodeURIComponent(username);
		}
		this.logger.log("Opening SSE stream:", url);
		var es = new EventSource(url, {withCredentials: true});
		this.eventSource = es;
		es.addEventListener("hello", function(ev) { self.handleHello(ev); });
		es.addEventListener("tiddler-change", function(ev) { self.handleTiddlerChange(ev); });
		es.addEventListener("tiddler-delete", function(ev) { self.handleTiddlerDelete(ev); });
		es.addEventListener("cache-miss", function(ev) { self.handleCacheMiss(ev); });
		es.addEventListener("presenter-changed", function(ev) { self.handlePresenterChanged(ev); });
		es.addEventListener("main-changed", function(ev) { self.handleMainChanged(ev); });
		es.addEventListener("open", function() {
			self.setConnectionState("open");
		});
		es.addEventListener("ping", function() {
			self.lastPingAt = Date.now();
			// Self-heal the badge: a ping proves the stream is alive even if
			// an earlier error left the state at "reconnecting".
			self.setConnectionState("open");
		});
		es.addEventListener("error", function() {
			var closed = es.readyState === 2;
			self.setConnectionState(closed ? "closed" : "reconnecting");
			self.logger.log(closed ? "SSE stream closed" : "SSE stream error; will auto-reconnect");
		});
	};

	// Surface the EventSource lifecycle as a state tiddler so the UI can show
	// a live connection badge. Write-on-change only, so the periodic ping does
	// not churn the store. $:/state/ titles are excluded from SyncFilter:
	// local to this tab, never persisted or broadcast.
	TiddlyWebSSEAdaptor.prototype.setConnectionState = function(state) {
		if(this.wiki.getTiddlerText(STATE_CONNECTION, "") !== state) {
			this.wiki.addTiddler({title: STATE_CONNECTION, text: state});
		}
	};

	TiddlyWebSSEAdaptor.prototype.handleHello = function(ev) {
		var data = parseSSEData(ev);
		if(!data) return;
		if(this.lastServerInstanceId !== null && this.lastServerInstanceId !== data.serverInstanceId) {
			this.logger.log("Server instance changed - forcing full sync");
			this.forceFullSync();
		}
		this.lastServerInstanceId = data.serverInstanceId;
		// Adopt the server-issued clientId. Role-gated routes 401 any header
		// value not bound to an active connection, so this MUST come before
		// any postRoleAction call below.
		if(data.assignedClientId) {
			this.clientId = data.assignedClientId;
			this.wiki.addTiddler({title: STATE_MY_CLIENT_ID, text: this.clientId});
		}
		// Mirror server's presenter state into local state tiddlers so the UI
		// can show who is presenting (UUID + friendly username).
		this.wiki.addTiddler({title: STATE_PRESENTER, text: data.presenterClientId || ""});
		this.wiki.addTiddler({title: STATE_PRESENTER_USERNAME, text: data.presenterUsername || ""});
		this.wiki.addTiddler({title: STATE_MAIN, text: data.mainClientId || ""});
		this.wiki.addTiddler({title: STATE_MAIN_USERNAME, text: data.mainUsername || ""});
		// Auto-claim: in presentation mode, or in main mode without an admin,
		// the first connecting tab takes the presenter role. In main mode WITH
		// an admin, /presenter/claim returns 403, so don't try -- the admin
		// must grant explicitly.
		var canAutoClaim = (data.mode === "presentation")
			|| (data.mode === "main" && !data.mainClientId);
		if(canAutoClaim && !data.presenterClientId) {
			this.postRoleAction("presenter", "claim");
		}
	};

	TiddlyWebSSEAdaptor.prototype.handlePresenterChanged = function(ev) {
		var data = parseSSEData(ev);
		if(!data) return;
		this.wiki.addTiddler({title: STATE_PRESENTER, text: data.clientId || ""});
		this.wiki.addTiddler({title: STATE_PRESENTER_USERNAME, text: data.username || ""});
	};

	TiddlyWebSSEAdaptor.prototype.handleMainChanged = function(ev) {
		var data = parseSSEData(ev);
		if(!data) return;
		this.wiki.addTiddler({title: STATE_MAIN, text: data.clientId || ""});
		this.wiki.addTiddler({title: STATE_MAIN_USERNAME, text: data.username || ""});
	};

	// Returns a Set of titles in `changedTitles` that match the given filter.
	function runFilterOn(wiki, filterText, changedTitles) {
		var fn = wiki.compileFilter(filterText);
		var source = function(callback) {
			changedTitles.forEach(function(title) {
				var t = wiki.tiddlerExists(title) && wiki.getTiddler(title);
				callback(t, title);
			});
		};
		var hits = fn.call(wiki, source);
		var set = Object.create(null);
		for(var i = 0; i < hits.length; i++) set[hits[i]] = true;
		return set;
	}

	TiddlyWebSSEAdaptor.prototype.pushPerTabIfPresenter = function(changes) {
		if(!this.eventSource || !this.recipe) return;
		// Only the current presenter pushes per-tab tiddlers; followers do not.
		if(this.wiki.getTiddlerText(STATE_PRESENTER, "") !== this.clientId) return;
		var titles = Object.keys(changes);
		var perTab = runFilterOn(this.wiki, this.wiki.getTiddlerText(PER_TAB_TIDDLERS_TIDDLER, DEFAULT_PER_TAB_FILTER), titles);
		// Skip titles the syncer will already push (e.g. $:/StoryList) -- avoids
		// duplicate PUTs for tiddlers in both filters.
		var syncFilter = this.wiki.getTiddlerText(SYNC_FILTER_TIDDLER, "[all[tiddlers]]");
		var synced = runFilterOn(this.wiki, syncFilter, titles);
		var self = this;
		titles.forEach(function(title) {
			if(!perTab[title]) return;
			if(synced[title]) return;
			if(changes[title].deleted) {
				self.directDeleteForPresenter(title);
			} else {
				self.directPutForPresenter(title);
			}
		});
	};

	TiddlyWebSSEAdaptor.prototype.directPutForPresenter = function(title) {
		var tiddler = this.wiki.getTiddler(title);
		if(!tiddler) return;
		var self = this;
		$tw.utils.httpRequest({
			url: this.host + "recipes/" + encodeURIComponent(this.recipe) + "/tiddlers/" + encodeURIComponent(title),
			type: "PUT",
			headers: {
				"Content-type": "application/json",
				"X-MCP-Client-Id": this.clientId
			},
			data: this.convertTiddlerToTiddlyWebFormat(tiddler),
			callback: function(err) {
				if(err) self.logger.log("presenter direct PUT failed for " + title + ":", err);
			}
		});
	};

	TiddlyWebSSEAdaptor.prototype.directDeleteForPresenter = function(title) {
		var self = this;
		// State tiddlers were never tracked by the syncer so we don't have a
		// recorded bag; the default tiddlyweb bag is "default".
		$tw.utils.httpRequest({
			url: this.host + "bags/default/tiddlers/" + encodeURIComponent(title),
			type: "DELETE",
			headers: {
				"X-MCP-Client-Id": this.clientId
			},
			callback: function(err) {
				if(err) self.logger.log("presenter direct DELETE failed for " + title + ":", err);
			}
		});
	};

	// Unified POST for the presenter/* and main/* role routes. The role and
	// action together build the URL ("presenter/claim", "main/release", ...).
	// $:/status/UserName is read fresh every time so the server attaches the
	// current friendly name to the resulting *-changed event -- the user may
	// have set it AFTER the EventSource opened.
	TiddlyWebSSEAdaptor.prototype.postRoleAction = function(role, action) {
		var self = this;
		var path = role + "/" + action;
		var headers = {
			"X-MCP-Client-Id": this.clientId,
			"X-Requested-With": "TiddlyWiki"
		};
		var username = this.wiki.getTiddlerText(USERNAME_TIDDLER, "") || "";
		if(username) {
			headers["X-MCP-Username"] = username;
		}
		$tw.utils.httpRequest({
			url: this.host + path,
			type: "POST",
			headers: headers,
			callback: function(err) {
				if(err) {
					self.logger.log(path + " failed:", err);
				}
			}
		});
	};

	TiddlyWebSSEAdaptor.prototype.postPresenterGrant = function(targetClientId) {
		if(!targetClientId) return;
		var self = this;
		$tw.utils.httpRequest({
			url: this.host + "presenter/grant",
			type: "POST",
			headers: {
				"X-MCP-Client-Id": this.clientId,
				"Content-type": "application/json",
				"X-Requested-With": "TiddlyWiki"
			},
			data: JSON.stringify({ clientId: targetClientId }),
			callback: function(err) {
				if(err) {
					self.logger.log("presenter/grant failed:", err);
				}
			}
		});
	};

	// Polled by the admin sub-panel's Refresh button. Writes the live client
	// set to a list-field tiddler the panel renders against.
	TiddlyWebSSEAdaptor.prototype.refreshClientsList = function() {
		var self = this;
		$tw.utils.httpRequest({
			url: this.host + "clients",
			callback: function(err, data) {
				if(err) {
					self.logger.log("clients fetch failed:", err);
					return;
				}
				var arr;
				try {
					arr = JSON.parse(data);
				} catch(e) {
					self.logger.log("clients parse failed:", e);
					return;
				}
				var ids = [];
				var fields = { title: STATE_CLIENTS_LIST };
				arr.forEach(function(c) {
					ids.push(c.clientId);
					fields["username-" + c.clientId] = c.username || "";
				});
				fields.list = ids;
				self.wiki.addTiddler(fields);
			}
		});
	};

	TiddlyWebSSEAdaptor.prototype.handleTiddlerChange = function(ev) {
		var data = parseSSEData(ev);
		if(!data) return;
		if(data.clientId && data.clientId === this.clientId) return;
		var syncer = $tw.syncer;
		if(!syncer) return;
		if(data.fields) {
			var fields = this.convertTiddlerFromTiddlyWebFormat(data.fields);
			syncer.storeTiddler(fields);
		} else {
			syncer.titlesToBeLoaded[data.title] = true;
			syncer.processTaskQueue();
		}
	};

	TiddlyWebSSEAdaptor.prototype.handleTiddlerDelete = function(ev) {
		var data = parseSSEData(ev);
		if(!data) return;
		if(data.clientId && data.clientId === this.clientId) return;
		var syncer = $tw.syncer;
		if(!syncer) return;
		delete syncer.tiddlerInfo[data.title];
		this.wiki.deleteTiddler(data.title);
	};

	TiddlyWebSSEAdaptor.prototype.handleCacheMiss = function() {
		this.logger.log("SSE cache-miss - forcing full sync");
		this.forceFullSync();
	};

	TiddlyWebSSEAdaptor.prototype.forceFullSync = function() {
		var syncer = $tw.syncer;
		if(!syncer) return;
		syncer.forceSyncFromServer = true;
		syncer.processTaskQueue();
	};

	return TiddlyWebSSEAdaptor;
};
","type":"application/javascript","module-type":"library"},"$:/plugins/wikilabs/tw-mcp/sse-bootstrap.js":{"title":"$:/plugins/wikilabs/tw-mcp/sse-bootstrap.js","text":"/*\
title: $:/plugins/wikilabs/tw-mcp/sse-bootstrap.js
type: application/javascript
module-type: startup

Runs before the core "startup" module (which is when the syncadaptor is
selected). When SSE is active on the server and the user hasn't opted
out, we replace tiddlyweb's `adaptorClass` with an SSE-aware subclass
built by sse-adaptor.js. The syncer then picks the wrapped class
instead of the original.

Two gates must both be "yes" for the takeover to happen:

* `$:/status/wikilabs/tw-mcp/sse-server-active` -- written by the
  server when it was started with `--mcp sse`. The `$:/status/`
  prefix keeps it out of the SyncFilter so it never hits disk and a
  subsequent --mcp listen run starts clean.
* `$:/config/wikilabs/tw-mcp/sse-enabled` -- user-toggle, default
  yes. Set to "no" to keep polling even when the server supports SSE.

Note: $tw.modules.types.syncadaptor[title] is the module *info* object,
not the executed exports. We must call $tw.modules.execute() to load
the module before mutating adaptorClass on its exports.

\*/

"use strict";

exports.name = "tw-mcp-sse-bootstrap";
exports.platforms = ["browser"];
exports.before = ["startup"];
exports.synchronous = true;

var TIDDLYWEB_MODULE = "$:/plugins/tiddlywiki/tiddlyweb/tiddlywebadaptor.js";
var SSE_ADAPTOR_MODULE = "$:/plugins/wikilabs/tw-mcp/sse-adaptor.js";
var ENABLED_TIDDLER = "$:/config/wikilabs/tw-mcp/sse-enabled";
// $:/status/ prefix keeps it out of the default SyncFilter so it never
// gets persisted to disk on the server -- important so a subsequent start
// WITHOUT --mcp sse doesn't see a stale "yes" loaded from .tid files.
var SERVER_ACTIVE_TIDDLER = "$:/status/wikilabs/tw-mcp/sse-server-active";

exports.startup = function() {
	if($tw.wiki.getTiddlerText(SERVER_ACTIVE_TIDDLER, "no").trim() !== "yes") {
		return; // server was not started with --mcp sse
	}
	if($tw.wiki.getTiddlerText(ENABLED_TIDDLER, "yes").trim() !== "yes") {
		return; // user opted out via config tiddler
	}
	if(!$tw.modules.titles[TIDDLYWEB_MODULE]) {
		return; // tiddlyweb plugin not loaded; nothing to wrap
	}
	var tw = $tw.modules.execute(TIDDLYWEB_MODULE);
	if(!tw || !tw.adaptorClass) {
		return;
	}
	var makeSSEAdaptor = require(SSE_ADAPTOR_MODULE).makeSSEAdaptor;
	tw.adaptorClass = makeSSEAdaptor(tw.adaptorClass);
	console.log("tw-mcp/sse: wrapped tiddlyweb adaptor with SSE subclass");
};
","type":"application/javascript","module-type":"startup"},"$:/core/modules/server/sse-broadcaster.js":{"title":"$:/core/modules/server/sse-broadcaster.js","text":"/*\
title: $:/core/modules/server/sse-broadcaster.js
type: application/javascript
module-type: library

Server-Sent Events broadcaster for the wikilabs/tw-mcp plugin.

Singleton lives at $tw.mcp.sse. Holds connected clients, a bounded ring
buffer of recent events for Last-Event-ID replay, the server instance id
(regenerated on every server start), and the wiki "change" listener that
turns mutations into `tiddler-change` and `tiddler-delete` events.

Use exports.initialize(wiki) once at server start to create the singleton.
The /events route handler reads $tw.mcp.sse to attach clients.

\*/

"use strict";

var DEFAULT_RING_SIZE = 500;
// Default inline threshold: above this size the SSE event carries only
// `title` + `revision` and the browser must fetch the body via the syncer
// (a ~250 ms wake-up cycle vs sub-ms for inlined content). 32 KiB covers
// the vast majority of doc tiddlers. Configurable per wiki via
// `$:/config/wikilabs/tw-mcp/sse-inline-threshold`.
var DEFAULT_INLINE_THRESHOLD = 32768;
var HEARTBEAT_MS = 25000;
var INLINE_THRESHOLD_TIDDLER = "$:/config/wikilabs/tw-mcp/sse-inline-threshold";
var SYNC_FILTER_TIDDLER = "$:/config/SyncFilter";
var DEFAULT_SYNC_FILTER = "[all[tiddlers]] -[[$:/isEncrypted]] -[prefix[$:/temp/]] -[prefix[$:/status/]] -[has[plugin-type]]";
// Per-tab view-state tiddlers: changes from a browser (clientId set) are NOT
// broadcast, so each tab keeps its own story river and history. MCP tools and
// filesystem-watcher edits have no clientId and broadcast normally.
var PER_TAB_TIDDLERS_TIDDLER = "$:/config/wikilabs/tw-mcp/per-tab-tiddlers";
var DEFAULT_PER_TAB_FILTER = "[[$:/StoryList]] [[$:/HistoryList]] [prefix[$:/state/]]";
var MODE_TIDDLER = "$:/config/wikilabs/tw-mcp/mode";
var MAX_CONNECTIONS = 50;

var KNOWN_TIDDLYWEB_FIELDS = ["bag","created","creator","modified","modifier","permissions","recipe","revision","tags","text","title","type","uri"];

// Input caps. clientIds are UUIDs in the shape
// `xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx` (36 chars, hex). The server issues
// them itself at /events connect (see addClient); role routes accept them
// only via X-MCP-Client-Id, validated against this regex. Strict length +
// charset rejects a single non-hex byte; combined with the `<$text>` wrap
// in the ControlPanel it is defence-in-depth against wikitext injection
// through any route that echoes the clientId back to admins. Usernames are
// display-only and can contain anything (spaces, emoji, accents) -- only
// the length is capped so a malicious EventSource can't blow up event
// payloads or /clients output.
var MAX_USERNAME_LENGTH = 64;
var CLIENT_ID_PATTERN = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;

function isValidClientId(s) {
	return typeof s === "string" && CLIENT_ID_PATTERN.test(s);
}

function capUsername(s) {
	if(typeof s !== "string") return null;
	return s.length > MAX_USERNAME_LENGTH ? s.substring(0, MAX_USERNAME_LENGTH) : s;
}

exports.isValidClientId = isValidClientId;
exports.capUsername = capUsername;

function SSEBroadcaster(wiki) {
	var self = this;
	this.wiki = wiki;
	// Map<clientId, {res, username}>. Keyed by the server-issued clientId so
	// findUsernameFor / isClientConnected / updateClientUsername are O(1).
	this.clients = new Map();
	this.ring = [];
	this.ringSize = DEFAULT_RING_SIZE;
	this.nextId = 1;
	this.serverInstanceId = generateInstanceId();
	this.pendingOriginators = Object.create(null);
	this.presenterClientId = null;
	this.presenterUsername = null;
	this.mainClientId = null;
	this.mainUsername = null;
	var filterText = wiki.getTiddlerText(SYNC_FILTER_TIDDLER) || DEFAULT_SYNC_FILTER;
	this.filterFn = wiki.compileFilter(filterText);
	wiki.addEventListener("change", function(changes) {
		self.handleWikiChange(changes);
	});
	setInterval(function() {
		self.sendHeartbeat();
	}, HEARTBEAT_MS);
}

SSEBroadcaster.prototype.isValidClientId = isValidClientId;
SSEBroadcaster.prototype.capUsername = capUsername;

SSEBroadcaster.prototype.getInlineThreshold = function() {
	var raw = this.wiki.getTiddlerText(INLINE_THRESHOLD_TIDDLER);
	var n = parseInt(raw, 10);
	return (n > 0 && n < 1024 * 1024) ? n : DEFAULT_INLINE_THRESHOLD;
};

SSEBroadcaster.prototype.getMode = function() {
	var raw = (this.wiki.getTiddlerText(MODE_TIDDLER, "default") || "default").trim();
	if(raw === "presentation" || raw === "main") return raw;
	return "default";
};

function generateInstanceId() {
	var crypto = require("crypto");
	return Date.now().toString(36) + "-" + crypto.randomBytes(4).toString("hex");
}

// Echo-suppression hooks. PUT/DELETE handlers call recordOriginator before
// addTiddler/deleteTiddler so the change event carries the clientId.
// Single-pending-originator-per-title is fine because Node's event loop is
// single-threaded -- the synchronous addTiddler that follows fires the wiki
// "change" event before the next request enters the handler.
SSEBroadcaster.prototype.recordOriginator = function(title, clientId) {
	if(clientId) {
		this.pendingOriginators[title] = clientId;
	}
};

SSEBroadcaster.prototype.consumeOriginatorClientId = function(title) {
	var id = this.pendingOriginators[title];
	delete this.pendingOriginators[title];
	return id || null;
};

SSEBroadcaster.prototype.applySyncFilter = function(titles) {
	var self = this;
	var source = function(callback) {
		titles.forEach(function(title) {
			var t = self.wiki.tiddlerExists(title) && self.wiki.getTiddler(title);
			callback(t, title);
		});
	};
	var allowed = Object.create(null);
	var filtered = this.filterFn.call(this.wiki, source);
	for(var i = 0; i < filtered.length; i++) {
		allowed[filtered[i]] = true;
	}
	return allowed;
};

// Returns a hashmap of titles that count as "per-tab view state" (StoryList,
// HistoryList, $:/state/* by default; user-extendable via the config tiddler).
// Recompiles the filter per call so edits to the config tiddler take effect
// without restart -- compile is microsecond-fast for short filters.
SSEBroadcaster.prototype.applyPerTabFilter = function(titles) {
	var self = this;
	var filterText = this.wiki.getTiddlerText(PER_TAB_TIDDLERS_TIDDLER, DEFAULT_PER_TAB_FILTER);
	var filterFn = this.wiki.compileFilter(filterText);
	var source = function(callback) {
		titles.forEach(function(title) {
			var t = self.wiki.tiddlerExists(title) && self.wiki.getTiddler(title);
			callback(t, title);
		});
	};
	var hits = filterFn.call(this.wiki, source);
	var set = Object.create(null);
	for(var i = 0; i < hits.length; i++) {
		set[hits[i]] = true;
	}
	return set;
};

SSEBroadcaster.prototype.serializeTiddler = function(tiddler) {
	var fields = {};
	$tw.utils.each(tiddler.fields, function(value, name) {
		var stringValue = name === "tags" ? tiddler.fields.tags : tiddler.getFieldString(name);
		if(KNOWN_TIDDLYWEB_FIELDS.indexOf(name) !== -1) {
			fields[name] = stringValue;
		} else {
			fields.fields = fields.fields || {};
			fields.fields[name] = stringValue;
		}
	});
	fields.revision = this.wiki.getChangeCount(tiddler.fields.title);
	fields.bag = fields.bag || "default";
	fields.type = fields.type || "text/vnd.tiddlywiki";
	return fields;
};

// Decide whether a browser-originated change to a per-tab tiddler should
// broadcast. Returns true when the change should pass through.
//   default mode -- never (each tab is independent)
//   presentation -- only when originator is the current presenter
//   main         -- same: only the current presenter broadcasts. The admin
//                   chose that presenter via /presenter/grant; this code
//                   path just honours whoever holds the role now.
SSEBroadcaster.prototype.shouldBroadcastPerTab = function(clientId) {
	var mode = this.getMode();
	if(mode === "presentation" || mode === "main") {
		return !!(this.presenterClientId && clientId === this.presenterClientId);
	}
	return false;
};

SSEBroadcaster.prototype.handleWikiChange = function(changes) {
	var self = this;
	var titles = Object.keys(changes);
	// The i-am-main role only has meaning in main mode. If the wiki's mode
	// tiddler flips to anything else, clear it so a later switch back to
	// main starts unowned and any tab can claim.
	if(changes[MODE_TIDDLER] && this.mainClientId && this.getMode() !== "main") {
		this.releaseMain(null);
	}
	var allowed = this.applySyncFilter(titles);
	var perTab = this.applyPerTabFilter(titles);
	titles.forEach(function(title) {
		var change = changes[title];
		var clientId = self.consumeOriginatorClientId(title);
		// Per-tab tiddlers (StoryList, HistoryList, $:/state/* by default)
		// are gated by mode, regardless of SyncFilter. This lets presentation
		// mode broadcast the presenter's UI state (which is in $:/state/*
		// and would otherwise be excluded from sync).
		// Non-per-tab tiddlers: changes respect the wiki's SyncFilter, but
		// deletes can't (the tiddler is gone, so [is[tiddler]] excludes it).
		// Always broadcast non-per-tab deletes except for the prefixes
		// SyncFilter would have excluded anyway.
		if(perTab[title]) {
			if(clientId && !self.shouldBroadcastPerTab(clientId)) return;
		} else if(change.deleted) {
			if(title.indexOf("$:/temp/") === 0) return;
			if(title.indexOf("$:/status/") === 0) return;
		} else {
			if(!allowed[title]) return;
		}
		if(change.deleted) {
			self.broadcast("tiddler-delete", {
				title: title,
				clientId: clientId
			});
		} else {
			var tiddler = self.wiki.getTiddler(title);
			if(!tiddler) return;
			var fields = self.serializeTiddler(tiddler);
			var json = JSON.stringify(fields);
			var payload = {
				title: title,
				revision: self.wiki.getChangeCount(title).toString(),
				clientId: clientId
			};
			if(json.length <= self.getInlineThreshold()) {
				payload.fields = fields;
			}
			self.broadcast("tiddler-change", payload);
		}
	});
};

// Look up the username an EventSource client supplied at connect time.
SSEBroadcaster.prototype.findUsernameFor = function(clientId) {
	var c = this.clients.get(clientId);
	return c ? (c.username || null) : null;
};

// Backfill the username on any matching EventSource client. Used when a
// claim arrives with X-MCP-Username for a tab whose SSE connection was
// opened before the user typed their name -- without this, getClients()
// keeps returning the connection-time empty value.
SSEBroadcaster.prototype.updateClientUsername = function(clientId, username) {
	if(!clientId || !username) return;
	var c = this.clients.get(clientId);
	if(c) c.username = username;
};

// Presenter election (last-claim-wins). Called from /presenter/claim, from
// grantPresenter (which is the /presenter/grant path), and from /main/claim
// when its initial claim auto-takes presenter. Username may come from the
// claim header (preferred -- always fresh) or from the connection-time
// lookup (fallback).
SSEBroadcaster.prototype.claimPresenter = function(clientId, username) {
	if(!clientId) return false;
	this.updateClientUsername(clientId, username);
	var resolvedUsername = username || this.findUsernameFor(clientId) || null;
	// No-op only if both clientId AND username already match (so a re-claim
	// after the user types their UserName promotes the friendly name).
	if(this.presenterClientId === clientId && this.presenterUsername === resolvedUsername) return false;
	this.presenterClientId = clientId;
	this.presenterUsername = resolvedUsername;
	this.broadcast("presenter-changed", { clientId: clientId, username: resolvedUsername });
	return true;
};

SSEBroadcaster.prototype.releasePresenter = function(clientId) {
	// Only the current presenter can release the role (or null clears it
	// unconditionally for disconnect-driven release).
	if(clientId !== null && clientId !== this.presenterClientId) return false;
	if(this.presenterClientId === null) return false;
	this.presenterClientId = null;
	this.presenterUsername = null;
	this.broadcast("presenter-changed", { clientId: null, username: null });
	return true;
};

// The admin role is exclusive: once a tab holds main, no other tab can
// take over. Same-tab re-claims update the friendly name (e.g. after the
// user types a UserName). Release/disconnect/mode-flip are the only ways
// the role changes hands.
SSEBroadcaster.prototype.claimMain = function(clientId, username) {
	if(!clientId) return false;
	if(this.mainClientId && this.mainClientId !== clientId) return false;
	this.updateClientUsername(clientId, username);
	var resolvedUsername = username || this.findUsernameFor(clientId) || null;
	if(this.mainClientId === clientId && this.mainUsername === resolvedUsername) return false;
	this.mainClientId = clientId;
	this.mainUsername = resolvedUsername;
	this.broadcast("main-changed", { clientId: clientId, username: resolvedUsername });
	return true;
};

SSEBroadcaster.prototype.releaseMain = function(clientId) {
	if(clientId !== null && clientId !== this.mainClientId) return false;
	if(this.mainClientId === null) return false;
	this.mainClientId = null;
	this.mainUsername = null;
	this.broadcast("main-changed", { clientId: null, username: null });
	return true;
};

SSEBroadcaster.prototype.isClientConnected = function(clientId) {
	return !!clientId && this.clients.has(clientId);
};

// True iff a PUT/DELETE on `title` from `clientId` should be 403'd because
// main-mode lockdown applies (admin set, caller is not the admin, target
// is under $:/config/wikilabs/tw-mcp/). Used by the put/delete handlers
// that wrap the core routes.
SSEBroadcaster.prototype.isConfigLockdownViolation = function(title, clientId) {
	if(!clientId) return false;
	if(title.indexOf("$:/config/wikilabs/tw-mcp/") !== 0) return false;
	if(this.getMode() !== "main") return false;
	if(!this.mainClientId) return false;
	return this.mainClientId !== clientId;
};

// Validate the X-MCP-Client-Id header for a role-gated route. Writes a
// 400 (missing/malformed) or 401 (not bound to a live connection) response
// directly when validation fails, so the caller can return immediately on
// a falsy result. Returns the clientId on success.
SSEBroadcaster.prototype.assertCaller = function(request, response) {
	var clientId = request.headers["x-mcp-client-id"];
	if(!clientId || !this.isValidClientId(clientId)) {
		response.writeHead(400, {"Content-Type": "text/plain"});
		response.end("X-MCP-Client-Id header missing or malformed\n");
		return null;
	}
	if(!this.isClientConnected(clientId)) {
		response.writeHead(401, {"Content-Type": "text/plain"});
		response.end("X-MCP-Client-Id not bound to an active connection\n");
		return null;
	}
	return clientId;
};

// Admin-gated presenter grant. Returns false if caller is not the current
// admin (handler converts to 403), or if the target isn't currently
// connected -- granting to a stale/typo'd UUID would otherwise leave the
// presenter role stuck on a non-existent client.
SSEBroadcaster.prototype.grantPresenter = function(adminClientId, targetClientId) {
	if(!this.mainClientId || adminClientId !== this.mainClientId) return false;
	if(!targetClientId) return false;
	if(!this.isClientConnected(targetClientId)) return false;
	var targetUsername = this.findUsernameFor(targetClientId);
	return this.claimPresenter(targetClientId, targetUsername);
};

// Snapshot of currently-connected clients for the admin UI's polling.
SSEBroadcaster.prototype.getClients = function() {
	var out = [];
	this.clients.forEach(function(c, clientId) {
		out.push({ clientId: clientId, username: c.username || null });
	});
	return out;
};

SSEBroadcaster.prototype.broadcast = function(eventName, payload) {
	var event = {
		id: this.nextId++,
		eventName: eventName,
		payload: payload
	};
	this.ring.push(event);
	if(this.ring.length > this.ringSize) {
		this.ring.shift();
	}
	var formatted = formatEvent(event);
	this.clients.forEach(function(c) {
		try {
			c.res.write(formatted);
		} catch(e) {
			// stale write; close handler will reap the client
		}
	});
};

function formatEvent(event) {
	return "id: " + event.id + "\n"
		+ "event: " + event.eventName + "\n"
		+ "data: " + JSON.stringify(event.payload) + "\n\n";
}

// Used for hello/cache-miss: SSE spec says events without `id:` do not advance
// the client cursor, so they can't poison Last-Event-ID on reconnect.
function formatEventNoId(eventName, payload) {
	return "event: " + eventName + "\n"
		+ "data: " + JSON.stringify(payload) + "\n\n";
}

// Heartbeat as a real `ping` event, not an SSE comment: comments are
// invisible to EventSource listeners, a real event lets clients observe
// liveness (the adaptor tracks lastPingAt and drives the connection badge).
// No `id:` so Last-Event-ID replay is unaffected; not pushed to the ring
// for the same reason.
SSEBroadcaster.prototype.sendHeartbeat = function() {
	var formatted = formatEventNoId("ping", {serverTime: Date.now()});
	this.clients.forEach(function(c) {
		try {
			c.res.write(formatted);
		} catch(e) {}
	});
};

SSEBroadcaster.prototype.writeHello = function(response, clientId) {
	try {
		response.write(":\n\n");
		response.write(formatEventNoId("hello", {
			serverInstanceId: this.serverInstanceId,
			inlineThreshold: this.getInlineThreshold(),
			mode: this.getMode(),
			presenterClientId: this.presenterClientId,
			presenterUsername: this.presenterUsername,
			mainClientId: this.mainClientId,
			mainUsername: this.mainUsername,
			assignedClientId: clientId
		}));
	} catch(e) {
		// stale write; close handler will reap the client
	}
};

// Replay any events the client missed if it sent Last-Event-ID. Within the
// ring window the missed events go out in order; outside the window the
// client gets `cache-miss` and is expected to do a full sync.
SSEBroadcaster.prototype.replayFromLastEventId = function(request, response) {
	var rawLastId = request.headers["last-event-id"];
	var lastEventId = parseInt(rawLastId || "", 10);
	if(isNaN(lastEventId) || lastEventId <= 0 || this.ring.length === 0) return;
	try {
		var oldestRingId = this.ring[0].id;
		if(oldestRingId > lastEventId + 1) {
			response.write(formatEventNoId("cache-miss", {
				lastEventId: lastEventId,
				message: "Reconnect window expired - perform full sync"
			}));
			return;
		}
		for(var i = 0; i < this.ring.length; i++) {
			if(this.ring[i].id > lastEventId) {
				response.write(formatEvent(this.ring[i]));
			}
		}
	} catch(e) {
		// stale write; close handler will reap the client
	}
};

SSEBroadcaster.prototype.addClient = function(request, response, username) {
	var self = this;
	if(this.clients.size >= MAX_CONNECTIONS) {
		response.writeHead(503, {"Content-Type": "text/plain"});
		response.end("Too many SSE connections\n");
		return;
	}
	// Server-issued clientId. Browsers cannot supply their own (a `?clientId=`
	// query param is ignored at the route layer); the assigned id is returned
	// in the hello payload so the adaptor can adopt it. Role routes 401 any
	// X-MCP-Client-Id that isn't bound to a live connection here.
	var clientId = require("crypto").randomUUID();
	response.writeHead(200, {
		"Content-Type": "text/event-stream; charset=utf-8",
		"Cache-Control": "no-cache, no-transform",
		"Connection": "keep-alive",
		"X-Accel-Buffering": "no"
	});
	this.clients.set(clientId, { res: response, username: username || null });
	// "close" fires for both graceful (browser tab refresh, EventSource.close())
	// and abnormal (network drop) terminations. Idempotent role releases mean
	// it's safe even if the event somehow fires twice.
	request.on("close", function() {
		self.clients.delete(clientId);
		// If the disconnecting tab held the presenter role, clear it so a
		// remaining tab can claim. Last-wins on the next claim.
		if(clientId === self.presenterClientId) {
			self.releasePresenter(null);
		}
		if(clientId === self.mainClientId) {
			self.releaseMain(null);
		}
	});
	this.writeHello(response, clientId);
	this.replayFromLastEventId(request, response);
};

exports.SSEBroadcaster = SSEBroadcaster;

exports.initialize = function(wiki) {
	if(!$tw.mcp) {
		$tw.mcp = {};
	}
	if(!$tw.mcp.sse) {
		$tw.mcp.sse = new SSEBroadcaster(wiki);
		$tw.mcp.sseEnabled = true;
	}
	return $tw.mcp.sse;
};
","type":"application/javascript","module-type":"library"},"$:/core/modules/server/routes/sse-events.js":{"title":"$:/core/modules/server/routes/sse-events.js","text":"/*\
title: $:/core/modules/server/routes/sse-events.js
type: application/javascript
module-type: route

GET /events  --  Server-Sent Events stream of tiddler change notifications.

Returns 503 if SSE is not enabled (i.e. the server was not started with the
`--mcp sse` keyword). When enabled, attaches the response to the broadcaster
which holds the connection open and writes events as they occur.

\*/

"use strict";

exports.methods = ["GET"];

exports.path = /^\/events$/;

exports.info = {
	priority: 500
};

exports.handler = function(request, response, state) {
	if(!$tw.mcp || !$tw.mcp.sse) {
		response.writeHead(503, {"Content-Type": "text/plain"});
		response.end("SSE not enabled - start the server with --mcp sse\n");
		return;
	}
	// clientId is server-issued in addClient() and returned via the hello
	// payload -- any caller-supplied ?clientId= query parameter is ignored.
	// Usernames are length-capped but otherwise unrestricted.
	var username = $tw.mcp.sse.capUsername(state.queryParameters && state.queryParameters.username || null);
	$tw.mcp.sse.addClient(request, response, username);
};
